def create_user(username, password, email=None, discord_id=None):
    """Create a new user"""
    users = load_users()
    user_id = str(uuid.uuid4())
    
    # Check if username already exists
    for existing_user in users.values():
        if existing_user['username'] == username:
            return None, "Username already exists"
    
    # Check if Discord ID already exists
    if discord_id:
        for existing_user in users.values():
            if existing_user.get('discord_id') == discord_id:
                return None, "Discord account already linked"
    
    user_data = {
        'username': username,
        'password_hash': hash_password(password),
        'email': email,
        'discord_id': discord_id,
        'is_active': True,
        'is_validated': False,  # New users need validation
        'created_at': datetime.now().isoformat(),
        'last_login': None
    }
    
    users[user_id] = user_data
    save_users(users)
    
    return User(
        user_id=user_id,
        username=username,
        email=email,
        discord_id=discord_id,
        is_active=True,
        is_validated=False,
        created_at=user_data['created_at']
    ), None

def update_user_last_login(user_id):
    """Update user's last login time"""
    users = load_users()
    if user_id in users:
        users[user_id]['last_login'] = datetime.now().isoformat()
        save_users(users)

def is_local_auth_disabled():
    """Check if local authentication is disabled"""
    auth_config = config.get('authentication', {})
    return auth_config.get('disable_local_auth', False) or auth_config.get('discord_only', False)

def is_discord_auth_enabled():
    """Check if Discord authentication is enabled"""
    from credential_manager import credential_manager
    discord_config = credential_manager.get_discord_credentials()
    return bool(discord_config.get('client_id') and discord_config.get('client_secret'))

def should_bypass_auth():
    """Check if authentication should be bypassed (disable_local_auth=true and no Discord config)"""
    local_auth_disabled = is_local_auth_disabled()
    discord_auth_enabled = is_discord_auth_enabled()
    
    if not local_auth_disabled:
        return False
    
    # If local auth is disabled, check if Discord is not configured
    if not discord_auth_enabled:
        return True
    
    return False

