def get_gamelist_path(system_name):
    """Get the gamelist path for a system, ensuring the directory exists"""
    gamelist_dir = os.path.join(GAMELISTS_FOLDER, system_name)
    os.makedirs(gamelist_dir, exist_ok=True)
    return os.path.join(gamelist_dir, 'gamelist.xml')

def get_roms_gamelist_path(system_name):
    """Get the path to the gamelist.xml file in the ROMs directory for a system"""
    return os.path.join(ROMS_FOLDER, system_name, 'gamelist.xml')

def ensure_gamelist_exists(system_name):
    """Ensure gamelist.xml exists in var/gamelists, copy from ROMs if needed"""
    var_gamelist_path = get_gamelist_path(system_name)
    roms_gamelist_path = get_roms_gamelist_path(system_name)
    
    # If var gamelist doesn't exist but ROMs gamelist does, copy it
    if not os.path.exists(var_gamelist_path) and os.path.exists(roms_gamelist_path):
        try:
            # Create the directory if it doesn't exist
            os.makedirs(os.path.dirname(var_gamelist_path), exist_ok=True)
            
            # Copy the gamelist.xml from ROMs to var
            shutil.copy2(roms_gamelist_path, var_gamelist_path)
            print(f"📋 Copied gamelist.xml from ROMs to var for system: {system_name}")
            
            # Format release dates in the copied gamelist
            format_releasedates_in_gamelist(var_gamelist_path)
            
            return True
        except Exception as e:
            print(f"❌ Error copying gamelist.xml for {system_name}: {e}")
            return False
    
    return True

def sync_all_gamelists():
    """Sync all gamelist.xml files from ROMs to var/gamelists if needed"""
    print("🔄 Syncing gamelist.xml files from ROMs to var/gamelists...")
    
    synced_count = 0
    error_count = 0
    
    try:
        # Get all system directories in ROMs folder
        for system_name in os.listdir(ROMS_FOLDER):
            system_path = os.path.join(ROMS_FOLDER, system_name)
            
            # Only process directories
            if os.path.isdir(system_path):
                if ensure_gamelist_exists(system_name):
                    synced_count += 1
                else:
                    error_count += 1
        
        print(f"✅ Gamelist sync completed: {synced_count} systems processed, {error_count} errors")
        
    except Exception as e:
        print(f"❌ Error during gamelist sync: {e}")
    
    return synced_count, error_count


def compare_gamelist_files(system_name):
    """Compare gamelist files between var/gamelists and roms directories"""
    gamelist_path = get_gamelist_path(system_name)
    roms_gamelist_path = os.path.join(ROMS_FOLDER, system_name, 'gamelist.xml')
    
    if not os.path.exists(gamelist_path):
        return {'success': False, 'error': f'Gamelist not found in var/gamelists/{system_name}/gamelist.xml'}
    
    try:
        # Parse both gamelist files
        var_games = parse_gamelist_xml(gamelist_path)
        roms_games = parse_gamelist_xml(roms_gamelist_path) if os.path.exists(roms_gamelist_path) else []
        
        # Create dictionaries for easier comparison (using path as key)
        var_games_dict = {game.get('path', ''): game for game in var_games}
        roms_games_dict = {game.get('path', ''): game for game in roms_games}
        
        # Find added and removed games
        var_paths = set(var_games_dict.keys())
        roms_paths = set(roms_games_dict.keys())
        
        added_games = var_paths - roms_paths
        removed_games = roms_paths - var_paths
        
        # Get added and removed game details
        added_games_list = [var_games_dict[path] for path in added_games]
        removed_games_list = [roms_games_dict[path] for path in removed_games]
        
        # Count media changes
        media_fields = ['image', 'thumbnail', 'video', 'marquee', 'manual', 'boxart', 'boxback', 'boxside', 'cartridge', 'wheel', 'bezel', 'fanart', 'extra1', 'screenshot', 'titlescreen']
        
        media_added = 0
        media_removed = 0
        
        # Count media in added games
        for game in added_games_list:
            for field in media_fields:
                if game.get(field):
                    media_added += 1
        
        # Count media in removed games
        for game in removed_games_list:
            for field in media_fields:
                if game.get(field):
                    media_removed += 1
        
        # Count total media in var gamelist
        total_media = 0
        for game in var_games:
            for field in media_fields:
                if game.get(field):
                    total_media += 1
        
        return {
            'success': True,
            'system_name': system_name,
            'games_added': len(added_games_list),
            'games_removed': len(removed_games_list),
            'games_added_list': [{'name': game.get('name', 'Unknown'), 'path': game.get('path', '')} for game in added_games_list],
            'games_removed_list': [{'name': game.get('name', 'Unknown'), 'path': game.get('path', '')} for game in removed_games_list],
            'media_added': media_added,
            'media_removed': media_removed,
            'total_games': len(var_games),
            'total_media': total_media
        }
    except Exception as e:
        return {'success': False, 'error': f'Error comparing gamelist files: {str(e)}'}

def save_gamelist_to_roms(system_name, delete_orphan_medias=False):
    """Copy gamelist from var/gamelists to roms/ directory"""
    gamelist_path = get_gamelist_path(system_name)
    roms_gamelist_path = os.path.join(ROMS_FOLDER, system_name, 'gamelist.xml')
    
    if not os.path.exists(gamelist_path):
        return {'success': False, 'error': f'Gamelist not found in var/gamelists/{system_name}/gamelist.xml'}
    
    try:
        # Ensure the roms directory exists
        os.makedirs(os.path.dirname(roms_gamelist_path), exist_ok=True)
        
        # Create backup of existing roms gamelist if it exists
        if os.path.exists(roms_gamelist_path):
            backup_path = f"{roms_gamelist_path}.backup.{int(time.time())}"
            shutil.copy2(roms_gamelist_path, backup_path)
            print(f"Created backup: {backup_path}")
            # Clean up old backups, keeping only the last 10
            cleanup_old_backups(roms_gamelist_path, max_backups=10)
        
        # Copy the gamelist
        shutil.copy2(gamelist_path, roms_gamelist_path)
        print(f"Copied gamelist from {gamelist_path} to {roms_gamelist_path}")
        
        # Format release dates in the copied gamelist
        format_releasedates_in_gamelist(roms_gamelist_path)
        
        # Delete orphan medias if requested
        deleted_files = []
        if delete_orphan_medias:
            deleted_files = delete_orphan_media_files(system_name)
        
        message = f'Gamelist saved to roms/{system_name}/gamelist.xml'
        if deleted_files:
            message += f' and {len(deleted_files)} orphan media files deleted'
        
        return {'success': True, 'message': message, 'deleted_files': deleted_files}
    except Exception as e:
        return {'success': False, 'error': f'Error saving gamelist: {str(e)}'}

def delete_orphan_media_files(system_name):
    """Delete media files in roms/<system>/media/ that are not referenced in the gamelist"""
    deleted_files = []
    
    try:
        # Path to the media directory
        media_dir = os.path.join(ROMS_FOLDER, system_name, 'media')
        if not os.path.exists(media_dir):
            print(f"Media directory does not exist: {media_dir}")
            return deleted_files
        
        # Load the gamelist to get referenced media files
        gamelist_path = os.path.join(ROMS_FOLDER, system_name, 'gamelist.xml')
        if not os.path.exists(gamelist_path):
            print(f"Gamelist does not exist: {gamelist_path}")
            return deleted_files
        
        # Parse the gamelist to extract all media file references
        referenced_files = set()
        try:
            tree = ET.parse(gamelist_path)
            root = tree.getroot()
            
            print(f"Parsing gamelist for media references...")
            
            # Get media fields from configuration
            config = load_config()
            media_fields = config.get('media_fields', {})
            media_types = list(media_fields.keys())
            
            print(f"Using media types from config: {media_types}")
            
            # Find all media elements (image, video, marquee, etc.)
            for game in root.findall('game'):
                for media_type in media_types:
                    media_elem = game.find(media_type)
                    if media_elem is not None and media_elem.text:
                        # Get the relative path from the media element
                        media_path = media_elem.text.strip()
                        if media_path:
                            # Remove leading ./ if present
                            if media_path.startswith('./'):
                                media_path = media_path[2:]
                            
                            # Check if this is a media file (starts with 'media/')
                            if media_path.startswith('media/'):
                                # Remove 'media/' prefix to get path relative to media directory
                                media_relative_path = media_path[6:]  # Remove 'media/' prefix
                                
                                # Convert to absolute path for comparison
                                abs_media_path = os.path.join(media_dir, media_relative_path)
                                referenced_files.add(os.path.normpath(abs_media_path))
                                
                                # Also add the relative path for comparison
                                referenced_files.add(os.path.normpath(media_relative_path))
                                
                                print(f"Found referenced media: {media_relative_path}")
                            else:
                                print(f"Skipping non-media path: {media_path}")
        except Exception as e:
            print(f"Error parsing gamelist for orphan detection: {e}")
            return deleted_files
        
        print(f"Found {len(referenced_files)} referenced media files in gamelist")
        
        # Safety check: if no referenced files found, don't delete anything
        if len(referenced_files) == 0:
            print("WARNING: No referenced media files found in gamelist. Skipping deletion to prevent data loss.")
            return deleted_files
        
        # Walk through the media directory and find orphaned files
        all_files = []
        for root_dir, dirs, files in os.walk(media_dir):
            for file in files:
                file_path = os.path.join(root_dir, file)
                all_files.append(file_path)
        
        print(f"Found {len(all_files)} total files in media directory")
        
        for file_path in all_files:
            normalized_abs_path = os.path.normpath(file_path)
            
            # Get relative path from media directory
            relative_path = os.path.relpath(file_path, media_dir)
            normalized_rel_path = os.path.normpath(relative_path)
            
            # Skip certain file types that might be system files
            if file_path.split(os.sep)[-1].startswith('.') or file_path.split(os.sep)[-1].endswith('.tmp'):
                print(f"Skipping system file: {relative_path}")
                continue
            
            # Check if this file is referenced in the gamelist
            is_referenced = (normalized_abs_path in referenced_files or 
                           normalized_rel_path in referenced_files)
            
            if is_referenced:
                print(f"Keeping referenced file: {relative_path}")
                continue
            
            # Additional safety: check if file exists in any subdirectory structure
            file_name = os.path.basename(file_path)
            is_referenced_by_name = False
            for ref_path in referenced_files:
                if os.path.basename(ref_path) == file_name:
                    is_referenced_by_name = True
                    break
            
            if is_referenced_by_name:
                print(f"Keeping file (referenced by name): {relative_path}")
                continue
            
            # Delete the orphaned file
            try:
                os.remove(file_path)
                deleted_files.append(relative_path)
                print(f"Deleted orphaned media file: {relative_path}")
            except Exception as e:
                print(f"Error deleting orphaned file {file_path}: {e}")
        
        print(f"Deleted {len(deleted_files)} orphaned media files for system {system_name}")
        return deleted_files
        
    except Exception as e:
        print(f"Error during orphan media cleanup: {e}")
        return deleted_files

