def _load_global_cache_from_file():
    """Load global cache from file (for worker processes)"""
    try:
        import pickle
        import os
        
        cache_file = os.path.join('var', 'cache', 'launchbox_global_metadata_cache.pkl')
        if not os.path.exists(cache_file):
            return None
        
        with open(cache_file, 'rb') as f:
            cache_data = pickle.load(f)
        
        print(f"DEBUG: Loaded global cache from {cache_file}")
        return cache_data
    except Exception as e:
        print(f"WARNING: Failed to load global cache from file: {e}")
        return None

def _save_platform_cache_to_file(platform_name, platform_cache, metadata_games):
    """Save platform-specific cache to file for worker processes"""
    try:
        import pickle
        import os
        
        cache_file = os.path.join('var', 'cache', f'launchbox_platform_{platform_name.replace(" ", "_").replace("/", "_")}_cache.pkl')
        os.makedirs(os.path.dirname(cache_file), exist_ok=True)
        
        cache_data = {
            'platform_cache': platform_cache,
            'metadata_games': metadata_games,
            'platform_name': platform_name
        }
        
        with open(cache_file, 'wb') as f:
            pickle.dump(cache_data, f)
        
        print(f"DEBUG: Saved platform cache for {platform_name} to {cache_file}")
    except Exception as e:
        print(f"WARNING: Failed to save platform cache for {platform_name}: {e}")

def _create_platform_specific_cache_files():
    """Create platform-specific cache files for worker processes"""
    global global_metadata_cache, _launchbox_platforms_cache
    
    if not global_metadata_cache or not _launchbox_platforms_cache:
        return
    
    # Check if platform cache files already exist
    import os
    cache_dir = 'var/cache'
    existing_cache_files = 0
    total_platforms = len(_launchbox_platforms_cache)
    
    for platform in _launchbox_platforms_cache:
        safe_platform_name = platform.replace(" ", "_").replace("/", "_")
        cache_file = os.path.join(cache_dir, f'launchbox_platform_{safe_platform_name}_cache.pkl')
        if os.path.exists(cache_file):
            existing_cache_files += 1
    
    # If all platform cache files exist, skip creation
    if existing_cache_files == total_platforms:
        print(f"✅ All {total_platforms} LaunchBox platform cache files already exist, skipping creation")
        return
    
    print(f"🔄 Creating LaunchBox platform-specific cache files for worker processes... ({existing_cache_files}/{total_platforms} already exist)")
    
    for platform in _launchbox_platforms_cache:
        try:
            # Check if this specific platform cache file already exists
            safe_platform_name = platform.replace(" ", "_").replace("/", "_")
            cache_file = os.path.join(cache_dir, f'launchbox_platform_{safe_platform_name}_cache.pkl')
            if os.path.exists(cache_file):
                continue  # Skip this platform, cache file already exists
            
            # Filter games for this platform
            platform_games = {}
            platform_alternate_names = {}
            
            for db_id, game_data in global_metadata_cache.items():
                if 'game' in game_data and game_data['game']:
                    game = game_data['game']
                    if game.get('Platform') == platform:
                        platform_games[db_id] = game
                        platform_alternate_names[db_id] = game_data.get('alternate_names', [])
            
            if platform_games:
                # Create platform cache structure
                platform_cache = {}
                for db_id, game in platform_games.items():
                    platform_cache[db_id] = {
                        'game': game,
                        'alternate_names': platform_alternate_names.get(db_id, [])
                    }
                
                # Save platform-specific cache file
                _save_platform_cache_to_file(platform, platform_cache, platform_games)
                print(f"DEBUG: Created platform cache for {platform} with {len(platform_games)} games")
        
        except Exception as e:
            print(f"WARNING: Failed to create platform cache for {platform}: {e}")

def _load_platform_cache_from_file(platform_name):
    """Load platform-specific cache from file (for worker processes)"""
    try:
        import pickle
        import os
        
        cache_file = os.path.join('var', 'cache', f'launchbox_platform_{platform_name.replace(" ", "_").replace("/", "_")}_cache.pkl')
        if not os.path.exists(cache_file):
            return None, None
        
        with open(cache_file, 'rb') as f:
            cache_data = pickle.load(f)
        
        print(f"DEBUG: Loaded platform cache for {platform_name} from {cache_file}")
        return cache_data.get('platform_cache', {}), cache_data.get('metadata_games', {})
    except Exception as e:
        print(f"WARNING: Failed to load platform cache for {platform_name}: {e}")
        return None, None

def load_metadata_cache():
    """Load and cache all metadata from Metadata.xml for faster lookups"""
    global global_metadata_cache, global_metadata_cache_loaded, _launchbox_platforms_cache
    
    if global_metadata_cache_loaded:
        # Return a derived view for any legacy callers
        return {
            'gameimage_cache': {k: v.get('images', []) for k, v in global_metadata_cache.items()},
            'games_cache': {k: v.get('game') for k, v in global_metadata_cache.items()},
            'alternate_names_cache': {k: v.get('alternate_names', []) for k, v in global_metadata_cache.items()}
        }
    
    try:
        # Check if cache file exists first
        cache_file = os.path.join('var', 'cache', 'launchbox_global_metadata_cache.pkl')
        if os.path.exists(cache_file):
            print("🔄 Loading LaunchBox metadata cache from file...")
            start_time = time.time()
            
            import pickle
            with open(cache_file, 'rb') as f:
                global_metadata_cache = pickle.load(f)
            
            global_metadata_cache_loaded = True
            
            # Generate LaunchBox platforms cache from consolidated cache
            platforms = set()
            for game_id, game_data in global_metadata_cache.items():
                if 'game' in game_data and game_data['game']:
                    platform = game_data['game'].get('Platform', 'Unknown')
                    if platform and platform.strip():
                        platforms.add(platform.strip())
            
            _launchbox_platforms_cache = sorted(list(platforms))
            
            # Create platform-specific cache files for worker processes
            print("🔄 Creating LaunchBox platform-specific cache files for worker processes...")
            _create_platform_specific_cache_files()
            
            end_time = time.time()
            print(f"✅ LaunchBox metadata cache loaded successfully in {end_time - start_time:.2f} seconds!")
            print(f"📊 Processed {len(_launchbox_platforms_cache)} unique LaunchBox platforms")
            print(f"📊 Found {sum(len(v.get('images', [])) for v in global_metadata_cache.values())} total GameImage files across {len(global_metadata_cache)} games")
            print(f"📊 Cached {len(global_metadata_cache)} total games")
            print(f"📊 Cached {sum(len(v.get('alternate_names', [])) for v in global_metadata_cache.values())} games with alternate names")
            
            
            return {
                'gameimage_cache': {k: v.get('images', []) for k, v in global_metadata_cache.items()},
                'games_cache': {k: v.get('game') for k, v in global_metadata_cache.items()},
                'alternate_names_cache': {k: v.get('alternate_names', []) for k, v in global_metadata_cache.items()}
            }
        
        print("🔄 Loading LaunchBox metadata cache from Metadata.xml...")
        start_time = time.time()
        
        # Ensure the directory exists before checking for the file
        metadata_path = get_launchbox_metadata_path()
        os.makedirs(os.path.dirname(metadata_path), exist_ok=True)
        
        if not os.path.exists(metadata_path):
            print(f"DEBUG: Metadata.xml not found at {metadata_path}")
            global_metadata_cache = {}
            global_metadata_cache_loaded = True
            return {
                'gameimage_cache': {},
                'games_cache': {},
                'alternate_names_cache': {}
            }
        
        # Parse the Metadata.xml using streaming parser for memory efficiency
        import xml.etree.ElementTree as ET
        consolidated = {}
        
        # Use iterparse for memory-efficient XML processing
        context = ET.iterparse(metadata_path, events=('start', 'end'))
        context = iter(context)
        event, root = next(context)
        
        game_images_count = 0
        games_count = 0
        alternate_names_count = 0
        
        for event, elem in context:
            if event == 'end':
                if elem.tag == 'GameImage':
                    game_images_count += 1
                    db_id = elem.find('DatabaseID')
                    if db_id is not None and db_id.text:
                        db_id_text = db_id.text
                        entry = consolidated.setdefault(db_id_text, {'game': {}, 'images': [], 'alternate_names': []})
                        # Extract only the text content we need, not the entire element
                        image_data = {}
                        for child in elem:
                            if child.text:
                                image_data[child.tag] = child.text.strip()
                        entry['images'].append(image_data)
                    elem.clear()
                    
                elif elem.tag == 'Game':
                    games_count += 1
                    db_id = elem.find('DatabaseID')
                    if db_id is not None and db_id.text:
                        db_id_text = db_id.text
                        entry = consolidated.setdefault(db_id_text, {'game': {}, 'images': [], 'alternate_names': []})
                        # Extract only the text content we need, not the entire element
                        game_data = {}
                        for child in elem:
                            if child.text:
                                game_data[child.tag] = child.text.strip()
                        entry['game'] = game_data
                    elem.clear()
                    
                elif elem.tag == 'GameAlternateName':
                    alternate_names_count += 1
                    db_id = elem.find('DatabaseID')
                    if db_id is not None and db_id.text:
                        db_id_text = db_id.text
                        entry = consolidated.setdefault(db_id_text, {'game': {}, 'images': [], 'alternate_names': []})
                        # Extract only the text content we need, not the entire element
                        alt_name_data = {}
                        for child in elem:
                            if child.text:
                                alt_name_data[child.tag] = child.text.strip()
                        entry['alternate_names'].append(alt_name_data)
                    elem.clear()
        
        print(f"DEBUG: Found {game_images_count} GameImage entries in Metadata.xml")
        print(f"DEBUG: Found {games_count} Game entries in Metadata.xml")
        print(f"DEBUG: Found {alternate_names_count} GameAlternateName entries in Metadata.xml")
        
        # Update global consolidated cache (make a copy to avoid clearing it later)
        global_metadata_cache = consolidated.copy()
        global_metadata_cache_loaded = True
        
        # Save cache to file for worker processes to use
        _save_global_cache_to_file(consolidated)
        print(f"✅ Saved LaunchBox global metadata cache to var/cache/launchbox_global_metadata_cache.pkl")
        
        # Generate LaunchBox platforms cache from consolidated cache
        platforms = set()
        for entry in consolidated.values():
            game_data = entry.get('game', {})
            platform = game_data.get('Platform')
            if platform:
                platforms.add(platform.strip())
        
        _launchbox_platforms_cache = sorted(list(platforms))
        print(f"DEBUG: Cached {len(_launchbox_platforms_cache)} unique LaunchBox platforms")
        
        # Create platform-specific cache files for worker processes
        print("🔄 Creating LaunchBox platform-specific cache files for worker processes...")
        _create_platform_specific_cache_files()
        
        load_time = time.time() - start_time
        
        # Count total images across all games before clearing memory
        total_images = sum(len(entry.get('images', [])) for entry in consolidated.values())
        
        print(f"✅ LaunchBox metadata cache loaded successfully in {load_time:.2f} seconds!")
        print(f"📊 Processed {len(_launchbox_platforms_cache)} unique LaunchBox platforms")
        print(f"📊 Found {total_images} total GameImage files across {len(consolidated)} games")
        print(f"📊 Cached {len(consolidated)} total games")
        print(f"DEBUG: Cached {sum(1 for e in consolidated.values() if e.get('alternate_names'))} games with alternate names")
        
        # Clear large data structures from memory after cache generation
        print("🧹 Clearing large data structures from memory...")
        consolidated.clear()
        del consolidated
        
        
        return {
            'gameimage_cache': {k: v.get('images', []) for k, v in global_metadata_cache.items()},
            'games_cache': {k: v.get('game') for k, v in global_metadata_cache.items()},
            'alternate_names_cache': {k: v.get('alternate_names', []) for k, v in global_metadata_cache.items()}
        }
        
    except Exception as e:
        print(f"ERROR: Failed to load metadata cache: {e}")
        import traceback
        traceback.print_exc()
        global_metadata_cache = {}
        global_metadata_cache_loaded = True
        return {
            'gameimage_cache': {},
            'games_cache': {},
            'alternate_names_cache': {}
        }

def get_cached_game_data(database_id):
    """Get cached game data including alternate names"""
    if not global_metadata_cache_loaded:
        load_metadata_cache()
    
    entry = global_metadata_cache.get(database_id) or {}
    game_data = {
        'game': entry.get('game'),
        'alternate_names': entry.get('alternate_names', []),
        'images': entry.get('images', [])
    }
    
    return game_data

def get_cached_games_by_platform(platform):
    """Get all cached games for a specific platform"""
    if not global_metadata_cache_loaded:
        load_metadata_cache()
    
    platform_games = []
    for db_id, entry in global_metadata_cache.items():
        game = entry.get('game')
        if game is None:
            continue
        game_platform = game.find('Platform')
        if game_platform is not None and game_platform.text == platform:
            platform_games.append(game)
    
    return platform_games

def load_platform_metadata_cache(platform, use_global_cache=False, mapping_config=None):
    """Load only games and alternate names cache for a specific platform (no images)"""
    try:
        print(f"DEBUG: Loading platform-specific metadata cache for {platform}...")
        start_time = time.time()
        
        # Use global cache only if explicitly requested (for non-worker processes)
        if use_global_cache and global_metadata_cache_loaded and global_metadata_cache:
            print(f"DEBUG: Using global cache to build platform-specific cache for {platform}...")
            platform_cache = {}
            
            # Filter global cache for this platform
            for db_id, entry in global_metadata_cache.items():
                game_elem = entry.get('game')
                if game_elem is None:
                    continue
                
                # Check if this game is for the target platform
                game_platform = game_elem.get('Platform')
                if game_platform == platform:
                    platform_cache[db_id] = {
                        'game': game_elem,
                        'alternate_names': entry.get('alternate_names', [])
                    }
            
            platform_games_count = len(platform_cache)
            platform_alt_names_count = sum(len(entry.get('alternate_names', [])) for entry in platform_cache.values())
            
            print(f"DEBUG: Found {platform_games_count} games for platform {platform} from global cache")
            print(f"DEBUG: Found {platform_alt_names_count} alternate names for platform {platform} from global cache")
            
            load_time = time.time() - start_time
            print(f"DEBUG: Platform-specific metadata cache loaded in {load_time:.2f} seconds from global cache")
            
            return {
                'games_cache': {k: v.get('game') for k, v in platform_cache.items()},
                'alternate_names_cache': {k: v.get('alternate_names', []) for k, v in platform_cache.items()}
            }
        
        # Default behavior: parse XML file directly (for worker processes)
        print(f"DEBUG: Parsing XML file for platform {platform}...")
        
        metadata_path = get_launchbox_metadata_path()
        os.makedirs(os.path.dirname(metadata_path), exist_ok=True)
        
        if not os.path.exists(metadata_path):
            print(f"DEBUG: Metadata.xml not found at {metadata_path}")
            return {
                'games_cache': {},
                'alternate_names_cache': {}
            }
        
        # Parse the Metadata.xml
        tree = ET.parse(metadata_path)
        root = tree.getroot()
        
        # Initialize platform-specific cache
        platform_cache = {}
        
        # Load games for the specific platform
        all_games = root.findall('.//Game')
        print(f"DEBUG: Found {len(all_games)} total Game entries in Metadata.xml")
        
        platform_games_count = 0
        for game in all_games:
            db_id = game.find('DatabaseID')
            game_platform = game.find('Platform')
            
            if (db_id is not None and db_id.text and 
                game_platform is not None and game_platform.text == platform):
                db_id_text = db_id.text
                entry = platform_cache.setdefault(db_id_text, {'game': None, 'alternate_names': []})
                entry['game'] = game
                platform_games_count += 1
        
        # Load alternate names for games in this platform
        all_alternate_names = root.findall('.//GameAlternateName')
        print(f"DEBUG: Found {len(all_alternate_names)} total GameAlternateName entries in Metadata.xml")
        
        platform_alt_names_count = 0
        for alt_name in all_alternate_names:
            db_id = alt_name.find('DatabaseID')
            if db_id is not None and db_id.text:
                db_id_text = db_id.text
                # Only add if we have a game for this platform
                if db_id_text in platform_cache:
                    entry = platform_cache[db_id_text]
                    entry['alternate_names'].append(alt_name)
                    platform_alt_names_count += 1
        
        load_time = time.time() - start_time
        
        print(f"DEBUG: Platform-specific metadata cache loaded in {load_time:.2f} seconds")
        print(f"DEBUG: Found {platform_games_count} games for platform {platform}")
        print(f"DEBUG: Found {platform_alt_names_count} alternate names for platform {platform}")
        print(f"DEBUG: Cached {sum(1 for e in platform_cache.values() if e.get('alternate_names'))} games with alternate names")
        
        # Convert XML elements to dictionaries for pickling
        metadata_games = {}
        platform_cache_dict = {}
        
        for db_id, entry in platform_cache.items():
            game_elem = entry.get('game')
            if game_elem is not None:
                # Convert XML element to dictionary
                game_data = {}
                for child in game_elem:
                    if child.text:
                        game_data[child.tag] = child.text.strip()
                metadata_games[db_id] = game_data
                
                # Convert alternate names to dictionaries
                alt_names_dict = []
                for alt_elem in entry.get('alternate_names', []):
                    alt_data = {}
                    for child in alt_elem:
                        if child.text:
                            alt_data[child.tag] = child.text.strip()
                    alt_names_dict.append(alt_data)
                
                platform_cache_dict[db_id] = {
                    'game': game_data,
                    'alternate_names': alt_names_dict
                }
        
        # Save platform-specific cache to file for future worker processes
        _save_platform_cache_to_file(platform, platform_cache_dict, metadata_games)
        
        return {
            'games_cache': metadata_games,
            'alternate_names_cache': {k: v.get('alternate_names', []) for k, v in platform_cache_dict.items()}
        }
        
    except Exception as e:
        print(f"ERROR: Failed to load platform metadata cache: {e}")
        import traceback
        traceback.print_exc()
        return {
            'games_cache': {},
            'alternate_names_cache': {}
        }

def get_cache_statistics():
    """Get statistics about the current metadata cache"""
    if not global_metadata_cache_loaded:
        return {
            'status': 'not_loaded',
            'games_with_images': 0,
            'total_games': 0,
            'games_with_alternate_names': 0
        }
    
    # Count total images across all games
    total_images = sum(len(entry.get('images', [])) for entry in global_metadata_cache.values())
    
    return {
        'status': 'loaded',
        'games_with_images': sum(1 for entry in global_metadata_cache.values() if entry.get('images')),
        'total_games': len(global_metadata_cache),
        'games_with_alternate_names': sum(1 for entry in global_metadata_cache.values() if entry.get('alternate_names')),
        'total_images': total_images,
        'total_database_ids': len(global_metadata_cache)
    }
def parse_gamelist_xml(file_path):
    """Parse gamelist.xml file and return list of games"""
    try:
        # Check if file exists and is readable
        if not os.path.exists(file_path):
            print(f"Gamelist file does not exist: {file_path}")
            return []
        
        # Check file size
        file_size = os.path.getsize(file_path)
        if file_size == 0:
            print(f"Gamelist file is empty: {file_path}")
            return []
        
        # Try to read the file content first to check for corruption
        try:
            with open(file_path, 'r', encoding='utf-8') as f:
                content = f.read()
                if not content.strip():
                    print(f"Gamelist file contains only whitespace: {file_path}")
                    return []
        except UnicodeDecodeError as e:
            print(f"Gamelist file has encoding issues: {file_path} - {e}")
            return []
        except Exception as e:
            print(f"Error reading gamelist file: {file_path} - {e}")
            return []
        
        # Parse XML
        tree = ET.parse(file_path)
        root = tree.getroot()
        
        # Check if root element is correct
        if root.tag != 'gameList':
            print(f"Invalid gamelist format: expected 'gameList' root, got '{root.tag}' in {file_path}")
            return []
        
        games = []
        
        for game in root.findall('game'):
            game_data = {}
            
            # Parse each field
            for field in game:
                tag = field.tag
                raw_text = field.text.strip() if field.text else ''
                # Fix over-escaped entities and decode to get original text for storage
                text = fix_over_escaped_xml_entities(raw_text) if raw_text else ''
                
                if tag == 'id':
                    game_data['id'] = int(text) if text.isdigit() else None
                elif tag == 'path':
                    game_data['path'] = text
                elif tag == 'name':
                    game_data['name'] = text
                elif tag == 'desc':
                    game_data['desc'] = text
                elif tag == 'genre':
                    game_data['genre'] = text
                elif tag == 'developer':
                    game_data['developer'] = text
                elif tag == 'publisher':
                    game_data['publisher'] = text
                elif tag == 'rating':
                    game_data['rating'] = text
                elif tag == 'players':
                    game_data['players'] = text
                elif tag == 'image':
                    game_data['image'] = text
                elif tag == 'video':
                    game_data['video'] = text
                elif tag == 'marquee':
                    game_data['marquee'] = text
                elif tag == 'wheel':
                    game_data['wheel'] = text
                elif tag == 'boxart':
                    game_data['boxart'] = text
                elif tag == 'thumbnail':
                    game_data['thumbnail'] = text
                elif tag == 'screenshot':
                    game_data['screenshot'] = text
                elif tag == 'cartridge':
                    game_data['cartridge'] = text
                elif tag == 'fanart':
                    game_data['fanart'] = text
                elif tag == 'titleshot':
                    game_data['titleshot'] = text
                elif tag == 'manual':
                    game_data['manual'] = text
                elif tag == 'boxback':
                    game_data['boxback'] = text
                elif tag == 'extra1':
                    game_data['extra1'] = text
                elif tag == 'launchboxid':
                    game_data['launchboxid'] = int(text) if text.isdigit() else None
                elif tag == 'igdbid':
                    game_data['igdbid'] = int(text) if text.isdigit() else None
                elif tag == 'screenscraperid':
                    game_data['screenscraperid'] = int(text) if text.isdigit() else None
                elif tag == 'mobygamesid':
                    game_data['mobygamesid'] = text
                elif tag == 'nbvotes':
                    game_data['nbvotes'] = int(text) if text.isdigit() else None
                elif tag == 'steamid':
                    game_data['steamid'] = int(text) if text.isdigit() else None
                elif tag == 'steamgridid':
                    game_data['steamgridid'] = int(text) if text.isdigit() else None
                elif tag == 'youtubeurl':
                    game_data['youtubeurl'] = text
                elif tag == 'hidden':
                    game_data['hidden'] = text
                elif tag == 'favorite':
                    # Handle boolean field - convert string to boolean
                    game_data['favorite'] = text.lower() == 'true' if text else False
                elif tag == 'kidgame':
                    # Handle boolean field - convert string to boolean
                    game_data['kidgame'] = text.lower() == 'true' if text else False
                else:
                    # Handle unknown tags by storing them as text
                    game_data[tag] = text
            
            # Ensure required fields exist
            if 'id' not in game_data:
                game_data['id'] = len(games) + 1
            if 'name' not in game_data:
                game_data['name'] = 'Unknown Game'
            if 'path' not in game_data:
                game_data['path'] = './unknown.zip'
            if 'desc' not in game_data:
                game_data['desc'] = ''
            
            games.append(game_data)
        
        print(f"Successfully parsed {len(games)} games from {file_path}")
        return games
        
    except ET.ParseError as e:
        print(f"XML parsing error in gamelist.xml: {e}")
        print(f"File: {file_path}")
        print(f"File size: {os.path.getsize(file_path) if os.path.exists(file_path) else 'N/A'} bytes")
        
        # Try to create a backup of the corrupted file
        try:
            backup_path = f"{file_path}.corrupted.{int(time.time())}"
            import shutil
            shutil.copy2(file_path, backup_path)
            print(f"Created backup of corrupted file: {backup_path}")
        except Exception as backup_error:
            print(f"Failed to create backup: {backup_error}")
        
        return []
    except Exception as e:
        print(f"Unexpected error parsing gamelist.xml: {e}")
        print(f"File: {file_path}")
        return []

@app.route('/test-session')
def test_session():
    """Test route to check session persistence"""
    if 'test_counter' not in session:
        session['test_counter'] = 0
    session['test_counter'] += 1
    return jsonify({
        'test_counter': session['test_counter'],
        'session_id': session.get('_id', 'no-id'),
        'user_logged_in': current_user.is_authenticated if current_user else False
    })

