@app.route('/api/rom-systems')
@login_required
def list_rom_systems():
    """List all available ROM systems"""
    systems = []
    try:
        for system_name in os.listdir(ROMS_FOLDER):
            system_path = os.path.join(ROMS_FOLDER, system_name)
            if os.path.isdir(system_path):
                # Count games from var/<system>/gamelist.xml instead of roms/<system>/gamelist.xml
                gamelist_path = get_gamelist_path(system_name)
                rom_count = 0
                if os.path.exists(gamelist_path):
                    # Parse the actual gamelist.xml to get real count
                    games = parse_gamelist_xml(gamelist_path)
                    rom_count = len(games)
                
                systems.append({
                    'name': system_name,
                    'rom_count': rom_count,
                    'path': system_path
                })
    except Exception as e:
        print(f"Error listing ROM systems: {e}")
    
    # Sort systems alphabetically by name
    systems.sort(key=lambda x: x['name'].lower())
    
    return jsonify(systems)

@app.route('/api/config', methods=['GET', 'PUT'])
@login_required
def get_config():
    """Get or update application configuration"""
    if request.method == 'GET':
        # Include scrapers configuration and systems configuration in the response
        full_config = config.copy()
        full_config.update(scrappers_config)
        full_config['systems'] = load_systems_config()
        return jsonify(full_config)
    elif request.method == 'PUT':
        try:
            new_config = request.get_json()
            if not new_config:
                return jsonify({'error': 'No configuration data provided'}), 400
            
            # Update config with new values
            for key, value in new_config.items():
                if key in config:
                    if isinstance(value, dict) and isinstance(config[key], dict):
                        config[key].update(value)
                    else:
                        config[key] = value
            
            # Save updated config to file
            with open('var/config/config.json', 'w') as f:
                json.dump(config, f, indent=4)
            
            # Update global variables
            global ROMS_FOLDER
            ROMS_FOLDER = config['roms_root_directory']
            
            return jsonify({'success': True, 'message': 'Configuration updated', 'config': config})
        except Exception as e:
            return jsonify({'error': f'Failed to update configuration: {str(e)}'}), 500

@app.route('/api/similarity-config', methods=['GET', 'PUT'])
@login_required
def manage_similarity_config():
    """Get or update similarity algorithm configuration"""
    try:
        if request.method == 'GET':
            # Get available algorithms from config
            from game_utils import load_similarity_config
            similarity_config = load_similarity_config()
            
            # Get user's selected algorithm from cookie
            selected_algorithm = request.cookies.get('similarity_algorithm', similarity_config.get('algorithm', 'jaro_winkler'))
            
            return jsonify({
                'algorithm': selected_algorithm,
                'available_algorithms': similarity_config.get('available_algorithms', {})
            })
        elif request.method == 'PUT':
            new_config = request.get_json()
            if not new_config:
                return jsonify({'error': 'No configuration data provided'}), 400
            
            # Get available algorithms from config for validation
            from game_utils import load_similarity_config
            similarity_config = load_similarity_config()
            available_algorithms = list(similarity_config.get('available_algorithms', {}).keys())
            
            if 'algorithm' in new_config and new_config['algorithm'] not in available_algorithms:
                return jsonify({'error': f'Invalid algorithm. Must be one of: {", ".join(available_algorithms)}'}), 400
            
            # Create response with success message
            response_data = {
                'success': True, 
                'message': 'Similarity algorithm preference updated', 
                'algorithm': new_config.get('algorithm', 'jaro_winkler')
            }
            
            # Create response object to set cookie
            response = make_response(jsonify(response_data))
            response.set_cookie('similarity_algorithm', new_config.get('algorithm', 'jaro_winkler'), max_age=365*24*60*60)  # 1 year
            
            return response
    except Exception as e:
        return jsonify({'error': f'Failed to manage similarity configuration: {str(e)}'}), 500

