@app.route('/api/launchbox-refresh-media-types', methods=['POST'])
@login_required
def refresh_launchbox_media_types():
    """Refresh the LaunchBox media types cache by scanning the metadata"""
    try:
        import subprocess
        import sys
        
        # Run the media types scanner script
        result = subprocess.run([sys.executable, 'scan_launchbox_media_types.py'], 
                              capture_output=True, text=True, cwd=os.getcwd())
        
        if result.returncode == 0:
            # Reload the cache to get the updated data
            mediatype_cache_path = os.path.join('var', 'db', 'launchbox', 'mediatype.json')
            if os.path.exists(mediatype_cache_path):
                with open(mediatype_cache_path, 'r', encoding='utf-8') as f:
                    mediatype_cache = json.load(f)
                    media_types = mediatype_cache.get('media_types', [])
                    total_count = mediatype_cache.get('total_count', 0)
                
                return jsonify({
                    'success': True, 
                    'message': f'Media types cache refreshed successfully. Found {total_count} unique types.',
                    'media_types': media_types,
                    'total_count': total_count
                })
            else:
                return jsonify({'error': 'Cache file not found after refresh'}), 500
        else:
            return jsonify({
                'error': f'Failed to refresh media types cache: {result.stderr}'
            }), 500
            
    except Exception as e:
        return jsonify({'error': f'Failed to refresh media types cache: {str(e)}'}), 500

@app.route('/api/igdb-mappings', methods=['GET', 'PUT', 'POST'])
@login_required
def manage_igdb_mappings():
    """Manage IGDB image type mappings"""
    try:
        if request.method == 'GET':
            # Return current mappings and available media fields
            igdb_mappings = scrappers_config.get('igdb', {}).get('image_type_mappings', {})
            media_fields = config.get('media_fields', {})
            
            # Load IGDB media types from static file
            igdb_media_types = []
            try:
                with open('var/db/igdb/mediatype.txt', 'r') as f:
                    igdb_media_types = [line.strip() for line in f.readlines() if line.strip()]
            except FileNotFoundError:
                # Fallback to default values if file doesn't exist
                igdb_media_types = ['cover', 'screenshots', 'artworks', 'logos']
            
            return jsonify({
                'success': True, 
                'igdb_mappings': igdb_mappings,
                'media_fields': media_fields,
                'igdb_media_types': igdb_media_types
            })
        
        elif request.method == 'PUT':
            # Update existing mapping
            data = request.get_json()
            if not data or 'igdb_type' not in data or 'media_field' not in data:
                return jsonify({'error': 'IGDB type and media field are required'}), 400
            
            igdb_type = data['igdb_type']
            media_field = data['media_field']
            
            # Validate that the media field exists
            if media_field not in config.get('media_fields', {}):
                return jsonify({'error': 'Invalid media field'}), 400
            
            # Update the mapping (media_field -> igdb_type)
            if 'igdb' not in scrappers_config:
                scrappers_config['igdb'] = {}
            if 'image_type_mappings' not in scrappers_config['igdb']:
                scrappers_config['igdb']['image_type_mappings'] = {}
            
            # Update the mapping directly
            if igdb_type:
                scrappers_config['igdb']['image_type_mappings'][media_field] = igdb_type
            else:
                # Remove mapping if empty
                scrappers_config['igdb']['image_type_mappings'].pop(media_field, None)
            
            # Save to file
            with open('var/config/scrappers.json', 'w') as f:
                json.dump(scrappers_config, f, indent=4)
            
            return jsonify({'success': True, 'message': 'IGDB mapping updated successfully'})
        
        elif request.method == 'POST':
            # Reset mapping to default
            data = request.get_json()
            if not data or 'media_field' not in data or not data.get('reset'):
                return jsonify({'error': 'Reset operation requires media_field and reset flag'}), 400
            
            media_field = data['media_field']
            
            # Define default mappings (media_field -> igdb_type)
            default_mappings = {
                "boxart": "cover",
                "image": "screenshots", 
                "fanart": "artworks",
                "marquee": "logos"
            }
            
            # Reset to default value
            if 'igdb' not in scrappers_config:
                scrappers_config['igdb'] = {}
            if 'image_type_mappings' not in scrappers_config['igdb']:
                scrappers_config['igdb']['image_type_mappings'] = {}
            
            # Add default mapping if it exists
            default_igdb_type = default_mappings.get(media_field)
            if default_igdb_type:
                scrappers_config['igdb']['image_type_mappings'][media_field] = default_igdb_type
            
            # Save to file
            with open('var/config/scrappers.json', 'w') as f:
                json.dump(scrappers_config, f, indent=4)
            
            return jsonify({'success': True, 'message': 'IGDB mapping reset to default'})
    
    except Exception as e:
        return jsonify({'error': f'Failed to manage IGDB mappings: {str(e)}'}), 500

