@app.route('/api/rom-system/<system_name>/force-import-gamelist', methods=['POST'])
@login_required
def force_import_gamelist_endpoint(system_name):
    """Force import gamelist.xml from roms directory to var/gamelists directory"""
    try:
        import shutil
        import os
        
        # Define source and destination paths
        source_path = f"roms/{system_name}/gamelist.xml"
        dest_path = f"var/gamelists/{system_name}/gamelist.xml"
        
        # Check if source file exists
        if not os.path.exists(source_path):
            return jsonify({
                'success': False,
                'error': f'Source gamelist.xml not found at {source_path}'
            }), 404
        
        # Create destination directory if it doesn't exist
        os.makedirs(os.path.dirname(dest_path), exist_ok=True)
        
        # Copy the file
        shutil.copy2(source_path, dest_path)
        
        # Verify the copy was successful
        if os.path.exists(dest_path):
            return jsonify({
                'success': True,
                'message': f'Successfully imported gamelist.xml from {source_path} to {dest_path}',
                'source': source_path,
                'destination': dest_path
            })
        else:
            return jsonify({
                'success': False,
                'error': 'Failed to copy gamelist.xml file'
            }), 500
            
    except Exception as e:
        return jsonify({'error': f'Failed to force import gamelist: {str(e)}'}), 500

def load_launchbox_config():
    """Load Launchbox configuration from consolidated config.json"""
    global platform_metadata_cache, current_system_platform
    
    # Load from consolidated config
    mapping_config = scrappers_config.get('launchbox', {}).get('mapping', {})
    system_platform_mapping = load_systems_config()
    
    
    return mapping_config, system_platform_mapping


def parse_launchbox_metadata(metadata_path, target_platform, skip_global_cache=False):
    """Parse Launchbox Metadata.xml file using cached data"""
    global platform_metadata_cache
    
    # Check if we need to re-parse (system changed)
    if target_platform in platform_metadata_cache:
        print(f"Using cached metadata for platform: {target_platform}")
        return platform_metadata_cache[target_platform]
    
    print(f"Building metadata for platform: {target_platform} from cache...")
    
    try:
        # Use the comprehensive cache instead of parsing XML (unless skipped for worker processes)
        if not skip_global_cache and not global_metadata_cache_loaded:
            load_metadata_cache()
        
        games = []
        
        # Build games list from consolidated cache for the target platform
        for db_id, entry in global_metadata_cache.items():
            game_elem = entry.get('game')
            if game_elem is None:
                continue
            game_data = {}
            
            # Parse basic game fields from cached element
            # Get the fields to load from mapping configuration
            fields_to_load = set(['Name', 'Platform', 'DatabaseID'])  # Always load these core fields
            mapping_config = scrappers_config.get('launchbox', {}).get('mapping', {})
            if mapping_config:
                # Add all LaunchBox fields from the mapping configuration
                fields_to_load.update(mapping_config.keys())
            
            # Handle dictionary format
            for tag, text in game_elem.items():
                if isinstance(text, str) and tag in fields_to_load:
                    game_data[tag] = text.strip()
            
            # Only include games for the current platform
            if game_data.get('Platform') == target_platform:
                # Link alternate names to this game from cache
                alt_names = []
                for alt_elem in entry.get('alternate_names', []) or []:
                    # Handle dictionary format
                    alt_name_text = alt_elem.get('AlternateName')
                    if alt_name_text:
                        alt_names.append(alt_name_text.strip())
                game_data['AlternateNames'] = alt_names
                if alt_names:
                    print(f"DEBUG: Game '{game_data.get('Name')}' has alternate names: {alt_names}")
                games.append(game_data)
        
        # Cache the results
        platform_metadata_cache[target_platform] = games
        print(f"Cached {len(games)} games for platform: {target_platform}")
        
        # Log alternate names statistics
        total_alternate_names = sum(len(game.get('AlternateNames', [])) for game in games)
        print(f"Found {total_alternate_names} alternate names across {len(games)} games")
        
        return games
        
    except Exception as e:
        print(f"Error building metadata from cache: {e}")
        import traceback
        traceback.print_exc()
        return []

from game_utils import normalize_game_name

def normalize_igdb_url(image_id: str, media_type: str = 'default') -> str:
    """Normalize IGDB image URL - always use .png extension"""
    if not image_id:
        return ""
    
    # Use different templates for different media types
    if media_type == 'cover':
        template = 't_cover_big'
    elif media_type == 'artwork':
        template = 't_1080p'
    else:
        template = 't_720p'
    
    # Construct IGDB image URL using local image ID - always use .png
    return f"https://images.igdb.com/igdb/image/upload/{template}/{image_id}.png"

def find_best_match(game_name, metadata_games, target_platform, existing_launchboxid=None, platform_cache=None, mapping_config=None):
    """Find the best matching game in Launchbox metadata"""
    if not metadata_games:
        return None, 0
    
    # Use global partitioned indexes
    partition_index, partition_index_no_parens = load_launchbox_partitioned_indexes()
    if not partition_index or not partition_index_no_parens or target_platform not in partition_index:
        print(f"🔧 DEBUG: Global partitioned indexes not available for platform '{target_platform}'")
        return None, 0
    
    from game_utils import normalize_game_name
    
    # Try exact match with parentheses first
    normalized_with_parens = normalize_game_name(game_name, remove_paranthesis=False, remove_articles=False)
    if normalized_with_parens and normalized_with_parens in partition_index[target_platform]:
        launchboxid = partition_index[target_platform][normalized_with_parens]
        # Find the game in metadata_games
        for game in metadata_games:
            if str(game.get('DatabaseID', '')) == str(launchboxid):
                return game, 1.0
    
    # Try exact match without parentheses
    normalized_no_parens = normalize_game_name(game_name, remove_paranthesis=True, remove_articles=True)
    if normalized_no_parens and normalized_no_parens in partition_index_no_parens[target_platform]:
        launchboxid = partition_index_no_parens[target_platform][normalized_no_parens]
        # Find the game in metadata_games
        for game in metadata_games:
            if str(game.get('DatabaseID', '')) == str(launchboxid):
                return game, 1.0
    
    # If we have a launchboxid, try to find the exact match first via cache
    if existing_launchboxid:
        print(f"🔧 DEBUG: Looking up existing launchboxid: {existing_launchboxid}")
        try:
            # Use platform-specific cache if provided
            if platform_cache:
                # Convert existing_launchboxid to string for cache lookup
                launchboxid_str = str(existing_launchboxid)
                # Look up the game directly in platform_cache
                cache_entry = platform_cache.get(launchboxid_str)
                if cache_entry:
                    game_elem = cache_entry.get('game')
                    alt_names_elements = cache_entry.get('alternate_names', [])
                else:
                    game_elem = None
                    alt_names_elements = []
            else:
                # No platform cache available, cannot lookup by launchboxid
                print(f"🔧 DEBUG: No platform cache available for launchboxid lookup")
                game_elem = None
                alt_names_elements = []
            
            if game_elem is not None:
                print(f"🔧 DEBUG: Found game with launchboxid {existing_launchboxid}: {game_elem.get('Name', 'Unknown') if hasattr(game_elem, 'get') else 'XML Element'}")
                # Build a minimal game dict consistent with metadata_games entries
                game_data = {}
                
                # Get the fields to load from mapping configuration
                fields_to_load = set(['Name', 'Platform', 'DatabaseID'])  # Always load these core fields
                if mapping_config:
                    # Add all LaunchBox fields from the mapping configuration
                    fields_to_load.update(mapping_config.keys())
                
                # Handle dictionary-based game data (new format)
                for field_name, field_value in game_elem.items():
                    if field_name in fields_to_load and field_value:
                        game_data[field_name] = str(field_value).strip()
                
                # Attach alternate names from cache (platform check not required for unique DBIDs)
                alt_names = []
                for alt_elem in alt_names_elements:
                    # Handle dictionary-based alternate name data (new format)
                    alt_name = alt_elem.get('AlternateName', '')
                    if alt_name:
                        alt_names.append(str(alt_name).strip())
                game_data['AlternateNames'] = alt_names
                # Annotate match info for downstream logic
                game_data['_match_type'] = 'launchboxid'
                game_data['_matched_name'] = game_data.get('Name', '')
                print(f"🔧 DEBUG: Returning launchboxid match: {game_data.get('Name', 'Unknown')} (ID: {existing_launchboxid})")
                return game_data, 1.0
        except Exception as e:
            # Fall back to scanning metadata_games on any issue
            print(f"🔧 DEBUG: Error looking up launchboxid {existing_launchboxid}: {e}")
            pass
    
    # Create indexed lookups for O(1) exact matches instead of O(n) linear searches
    # Apply the same normalization as used later in the function
    
    normalized_search = normalize_game_name(game_name, remove_paranthesis=False, remove_articles=False)
    
    # Fallback version removes parentheses and brackets after normalization (including nested)
    
    normalized_search_no_parens = normalize_game_name(game_name)
    
    # Build two unified indexes on first call or when metadata_games changes (cached for subsequent calls)
    if not hasattr(find_best_match, '_unified_index') or find_best_match._metadata_games is not metadata_games:
        print(f"DEBUG: Building unified indexes for {len(metadata_games)} games...")
        find_best_match._unified_index = {}  # With parentheses and articles
        find_best_match._unified_index_no_parens = {}  # Without parentheses
        find_best_match._metadata_games = metadata_games
        
        # Build two simplified unified indexes for both main names and alternate names
        main_name_count = 0
        alt_name_count = 0
        for i, game in enumerate(metadata_games):
            # Index main name with both normalization methods
            name = game.get('Name', '')
            if name:
                # Index with parentheses and articles
                name_with_parens = normalize_game_name(name, remove_paranthesis=False, remove_articles=False)
                if name_with_parens:
                    find_best_match._unified_index[name_with_parens] = name
                
                # Index without parentheses
                name_no_parens = normalize_game_name(name, remove_paranthesis=True, remove_articles=True)
                if name_no_parens:
                    find_best_match._unified_index_no_parens[name_no_parens] = name
                
                main_name_count += 1
            
            # Index alternate names with both normalization methods
            alternate_names = game.get('AlternateNames', [])
            for alt_name in alternate_names:
                # Index with parentheses and articles
                alt_name_with_parens = normalize_game_name(alt_name, remove_paranthesis=False, remove_articles=False)
                if alt_name_with_parens:
                    find_best_match._unified_index[alt_name_with_parens] = alt_name
                
                # Index without parentheses
                alt_name_no_parens = normalize_game_name(alt_name, remove_paranthesis=True, remove_articles=True)
                if alt_name_no_parens:
                    find_best_match._unified_index_no_parens[alt_name_no_parens] = alt_name
                
                alt_name_count += 1
        
        print(f"DEBUG: Indexed {main_name_count} main names and {alt_name_count} alternate names")
        print(f"DEBUG: With parentheses index: {len(find_best_match._unified_index)} entries")
        print(f"DEBUG: No parentheses index: {len(find_best_match._unified_index_no_parens)} entries")
    

    # If no match found with no_parens version, try with parentheses and articles index
    if normalized_search in find_best_match._unified_index:
        matched_name = find_best_match._unified_index[normalized_search]
        # Find the game that contains this name (main or alternate)
        for game in metadata_games:
            if game.get('Name', '') == matched_name:
                game['_match_type'] = 'main'
                game['_matched_name'] = matched_name
                return game, 1.0
            # Check if it's an alternate name
            for alt_name in game.get('AlternateNames', []):
                if alt_name == matched_name:
                    game['_match_type'] = 'alternate'
                    game['_matched_name'] = matched_name
                    print(f"DEBUG: Found alternate name match for '{game_name}' → '{matched_name}' (via with_parens index)")
                    return game, 1.0


    # Try exact match using simplified unified indexes (O(1) lookup)
    # First try with normalized search (with parentheses removed) using no_parens index
    if normalized_search_no_parens in find_best_match._unified_index_no_parens:
        matched_name = find_best_match._unified_index_no_parens[normalized_search_no_parens]
        # Find the game that contains this name (main or alternate)
        for game in metadata_games:
            if game.get('Name', '') == matched_name:
                game['_match_type'] = 'main'
                game['_matched_name'] = matched_name
                return game, 1.0
            # Check if it's an alternate name
            for alt_name in game.get('AlternateNames', []):
                if alt_name == matched_name:
                    game['_match_type'] = 'alternate'
                    game['_matched_name'] = matched_name
                    print(f"DEBUG: Found alternate name match for '{game_name}' → '{matched_name}' (via no_parens index)")
                    return game, 1.0
    
    
    # No similarity matching - only exact matches are accepted
    best_match = None
    best_score = 0
    
    return best_match, best_score
def get_top_matches(game_name, metadata_games, target_platform, top_n=20, mapping_config=None):
    """Get top N matches for a game name using global partitioned indexes and Jaro-Winkler similarity"""
    print(f"🔍 DEBUG: get_top_matches called for '{game_name}' (platform: {target_platform}, top_n: {top_n})")
    
    if not metadata_games:
        print(f"🔍 DEBUG: No metadata games provided, returning empty list")
        return []
    
    normalized_name = normalize_game_name(game_name, remove_paranthesis=True, remove_articles=True)
    print(f"🔍 DEBUG: Normalized name: '{normalized_name}'")
    
    if not normalized_name:
        print(f"🔍 DEBUG: Normalized name is empty, returning empty list")
        return []
    
    matches = []
    
    # Use global partitioned indexes
    partition_index, partition_index_no_parens = load_launchbox_partitioned_indexes()
    if not partition_index_no_parens or target_platform not in partition_index_no_parens:
        print(f"🔍 DEBUG: Global partitioned indexes not available for platform '{target_platform}'")
        return []
    
    print(f"🔍 DEBUG: Using global partitioned indexes for platform '{target_platform}'")
    
    # Get the first character to search in the right partition
    first_char = normalized_name[0] if normalized_name else 'other'
    print(f"🔍 DEBUG: Searching in partition '{first_char}'")
    
    # Search through all games in the platform partition
    platform_partition = partition_index_no_parens[target_platform]
    print(f"🔍 DEBUG: Platform partition has {len(platform_partition)} entries")
    
    for normalized_game_name, launchboxid in platform_partition.items():
        # Only search games that start with the same character (partition optimization)
        if normalized_game_name.startswith(first_char):
            # Calculate similarity using configured algorithm
            from game_utils import calculate_similarity
            similarity = calculate_similarity(normalized_name, normalized_game_name)
            
            # Only consider good matches
            if similarity >= 0.7:
                # Find the game in metadata_games
                for game in metadata_games:
                    if str(game.get('DatabaseID', '')) == str(launchboxid):
                        # Get box image URL for this game
                        database_id = game.get('DatabaseID', '')
                        box_image_url = get_launchbox_box_image_url(database_id) if database_id else None
                        
                        # Create match info
                        match_info = {
                            'game': game,
                            'score': similarity,
                            'match_type': 'main',
                            'matched_name': game.get('Name', ''),
                            'database_id': database_id,
                            'name': game.get('Name', ''),
                            'overview': game.get('Overview', ''),
                            'developer': game.get('Developer', ''),
                            'publisher': game.get('Publisher', ''),
                            'box_image_url': box_image_url
                        }
                        
                        # Add mapped fields dynamically based on mapping configuration
                        if mapping_config:
                            for launchbox_field, gamelist_field in mapping_config.items():
                                match_info[gamelist_field] = game.get(launchbox_field, '')
                        
                        matches.append(match_info)
                        print(f"🔍 DEBUG: Found match: '{game.get('Name', '')}' -> similarity: {similarity:.4f}")
                        break
    
    print(f"🔍 DEBUG: Found {len(matches)} total matches before deduplication")
    
    # Deduplicate matches by DatabaseID, keeping the best score for each unique game
    seen_database_ids = {}
    deduplicated_matches = []
    
    for match in matches:
        database_id = match.get('database_id', '')
        if database_id and database_id in seen_database_ids:
            # Keep the match with the higher score
            existing_match = seen_database_ids[database_id]
            if match['score'] > existing_match['score']:
                # Replace the existing match with this better one
                deduplicated_matches.remove(existing_match)
                deduplicated_matches.append(match)
                seen_database_ids[database_id] = match
        elif database_id:
            # New unique game, add it
            deduplicated_matches.append(match)
            seen_database_ids[database_id] = match
        else:
            # No database_id, add it (shouldn't happen with LaunchBox data)
            deduplicated_matches.append(match)
    
    print(f"🔍 DEBUG: After deduplication: {len(deduplicated_matches)} unique matches")
    
    # Sort by score (highest first) and return top N
    deduplicated_matches.sort(key=lambda x: x['score'], reverse=True)
    result = deduplicated_matches[:top_n]
    print(f"🔍 DEBUG: Returning {len(result)} matches (requested: {top_n})")
    
    # Log the top matches for debugging
    for i, match in enumerate(result[:5]):  # Log top 5 matches
        print(f"🔍 DEBUG: Match {i+1}: '{match['matched_name']}' (score: {match['score']:.4f}, type: {match['match_type']}, ID: {match['database_id']})")
    
    return result

def _dedupe_games_by_path(games):
    """Return a new list with duplicates removed by 'path' (first occurrence wins)."""
    seen_paths = set()
    deduped = []
    for game in games:
        raw_path = (game.get('path') or '').strip()
        key = raw_path if raw_path else f"__no_path__::{(game.get('name') or '').strip().lower()}"
        if key in seen_paths:
            continue
        seen_paths.add(key)
        deduped.append(game)
    removed_count = max(0, len(games) - len(deduped))
    if removed_count:
        print(f"🧹 Deduped games by path: removed {removed_count} duplicate entries (kept first occurrence)")
    return deduped

def write_gamelist_xml(games, file_path):
    """Write games list to gamelist.xml file (deduped by path)."""
    try:
        games_to_write = _dedupe_games_by_path(games)
        root = ET.Element('gameList')
        
        for game in games_to_write:
            game_elem = ET.SubElement(root, 'game')
            
            # Add all game fields
            for field, value in game.items():
                # Format releasedate field to ISO 8601 format
                if field == 'releasedate' and value:
                    value = format_releasedate_to_iso8601(value)
                
                # Handle boolean fields - convert to lowercase string
                if field in ['favorite', 'kidgame']:
                    value = 'true' if value else 'false'
                
                # Add all fields from the game data
                field_elem = ET.SubElement(game_elem, field)
                field_elem.text = str(value) if value else ''
                
                # Debug logging for launchboxid
                if field == 'launchboxid':
                    print(f"🔧 DEBUG: Writing launchboxid field: '{value}' (type: {type(value)}) as text: '{str(value)}'")
        
        # Write to file with formatting
        tree = ET.ElementTree(root)
        save_formatted_gamelist_xml(tree, file_path)
        
    except Exception as e:
        print(f"Error writing gamelist.xml: {e}")

@app.route('/api/scrap-launchbox', methods=['POST'])
@login_required
def scrap_launchbox():
    """Start Launchbox scraping process"""
    global current_task_id
    
    try:
        data = request.get_json()
        if not data:
            return jsonify({'error': 'No data provided'}), 400
            
        system_name = data.get('system')
        selected_games = data.get('selectedGames', [])
        force_download = data.get('force_download', False)  # Add force download option
        enable_partial_match_modal = data.get('enable_partial_match_modal', False)  # Add partial match modal option
        selected_fields = data.get('selected_fields', None)
        overwrite_text_fields = data.get('overwrite_text_fields', False)
        
        if not system_name:
            return jsonify({'error': 'System name required'}), 400
        
        # Add task to queue instead of starting directly
        task = add_task_to_queue('scraping', {
            'system_name': system_name,
            'selected_games': selected_games,
            'force_download': force_download,
            'enable_partial_match_modal': enable_partial_match_modal
        })
        
        # Enqueue scraping in single worker process (sequential)
        _ensure_worker_started()
        payload = {
            'type': 'scraping',
            'task_id': task.id,
            'system_name': system_name,
            'selected_games': selected_games,
            'enable_partial_match_modal': enable_partial_match_modal,
            'force_download': force_download,
            'selected_fields': selected_fields,
            'overwrite_text_fields': overwrite_text_fields
        }
        _worker_task_queue.put(payload)
        
        return jsonify({
            'success': True,
            'message': 'Scraping started',
            'system': system_name
        })
        
    except Exception as e:
        print(f"Error in scrap_launchbox endpoint: {e}")
        return jsonify({'error': f'Internal server error: {str(e)}'}), 500

@app.route('/api/scrap-launchbox/<system_name>', methods=['GET', 'POST'])
@login_required
def scrap_launchbox_simple(system_name):
    """Start Launchbox scraping process with system name in URL (for easier testing)"""
    global current_task_id, scraping_in_progress, scraping_progress, scraping_stats
    
    try:
        if not system_name:
            return jsonify({'error': 'System name required'}), 400
        
        # Get selected games and partial match modal setting from POST body if available
        selected_games = None
        enable_partial_match_modal = False
        force_download = False  # Default force download to False
        selected_fields = None
        overwrite_text_fields = False  # Default overwrite text fields to False
        
        if request.method == 'POST':
            try:
                data = request.get_json()
                if data:
                    if 'selected_games' in data:
                        selected_games = data['selected_games']
                        scraping_progress.append(f"Processing {len(selected_games)} selected games")
                    else:
                        scraping_progress.append("Processing all games")
                    
                    if 'enable_partial_match_modal' in data:
                        enable_partial_match_modal = data['enable_partial_match_modal']
                        print(f"DEBUG: Received enable_partial_match_modal: {enable_partial_match_modal} (type: {type(enable_partial_match_modal)})")
                        if enable_partial_match_modal:
                            scraping_progress.append("Partial match modal enabled - will show modal for non-perfect matches")
                        else:
                            scraping_progress.append("Partial match modal disabled - only perfect matches will be applied")
                    
                    if 'force_download' in data:
                        force_download = data['force_download']
                        if force_download:
                            scraping_progress.append("Force download enabled - will overwrite existing media fields")
                        else:
                            scraping_progress.append("Force download disabled - will only update empty media fields")
                    
                    if 'selected_fields' in data:
                        selected_fields = data['selected_fields']
                        if selected_fields:
                            scraping_progress.append(f"Field selection enabled - will only scrape: {', '.join(selected_fields)}")
                        else:
                            scraping_progress.append("No fields selected - will scrape all fields")
                    
                    if 'overwrite_text_fields' in data:
                        overwrite_text_fields = data['overwrite_text_fields']
                        print(f"🔧 DEBUG: Received overwrite_text_fields: {overwrite_text_fields} (type: {type(overwrite_text_fields)})")
                        if overwrite_text_fields:
                            scraping_progress.append("Overwrite text fields enabled - will overwrite existing text fields")
                        else:
                            scraping_progress.append("Overwrite text fields disabled - will only update empty text fields")
                    else:
                        print(f"🔧 DEBUG: overwrite_text_fields not found in request data. Available keys: {list(data.keys())}")
            except Exception as e:
                scraping_progress.append(f"Error parsing POST data: {e}")
                pass  # Ignore JSON parsing errors
        
        # Add task to queue instead of starting directly
        task = add_task_to_queue('scraping', {
            'system_name': system_name,
            'selected_games': selected_games,
            'enable_partial_match_modal': enable_partial_match_modal,
            'force_download': force_download,
            'selected_fields': selected_fields,
            'overwrite_text_fields': overwrite_text_fields
        })
        
        # The task will be processed by process_next_queued_task() automatically
        
        return jsonify({
            'success': True,
            'message': 'Scraping started',
            'system': system_name
        })
        
    except Exception as e:
        if current_task_id and current_task_id in tasks:
            tasks[current_task_id].complete(False, str(e))
        print(f"Error in scrap_launchbox_simple endpoint: {e}")
        return jsonify({'error': f'Internal server error: {str(e)}'}), 500

