@app.route('/api/remap-media-fields/validate', methods=['POST'])
@login_required
def validate_remap_media_fields():
    """Validate and perform media field remapping"""
    try:
        data = request.get_json()
        if not data:
            return jsonify({'error': 'No data provided'}), 400
        
        system_name = data.get('system_name')
        source_field = data.get('source_field')
        target_field = data.get('target_field')
        
        if not all([system_name, source_field, target_field]):
            return jsonify({'error': 'System name, source field, and target field are required'}), 400
        
        if source_field == target_field:
            return jsonify({'error': 'Source and target fields cannot be the same'}), 400
        
        # Load gamelist
        gamelist_path = get_gamelist_path(system_name)
        if not os.path.exists(gamelist_path):
            return jsonify({'error': 'Gamelist not found'}), 404
        
        games = parse_gamelist_xml(gamelist_path)
        if not games:
            return jsonify({'error': 'No games found in gamelist'}), 400
        
        # Perform remapping
        games_updated = 0
        for game in games:
            if source_field in game and game[source_field]:
                # Copy source field value to target field
                game[target_field] = game[source_field]
                # Remove source field
                del game[source_field]
                games_updated += 1
        
        # Save updated gamelist
        write_gamelist_xml(games, gamelist_path)
        
        return jsonify({
            'success': True,
            'message': f'Successfully remapped {source_field} to {target_field} for {games_updated} games'
        })
        
    except Exception as e:
        print(f"Error validating remap: {e}")
        return jsonify({'error': f'Internal server error: {str(e)}'}), 500

@app.route('/api/move-medias/check-conflicts', methods=['POST'])
@login_required
def check_move_medias_conflicts():
    """Check for potential file conflicts when moving media files"""
    try:
        data = request.get_json()
        if not data:
            return jsonify({'error': 'No data provided'}), 400
        
        system_name = data.get('system_name')
        media_field = data.get('media_field')
        
        if not all([system_name, media_field]):
            return jsonify({'error': 'System name and media field are required'}), 400
        
        # Load configuration to get media field directory
        config_path = os.path.join('var', 'config', 'config.json')
        if not os.path.exists(config_path):
            return jsonify({'error': 'Configuration not found'}), 404
        
        with open(config_path, 'r', encoding='utf-8') as f:
            config = json.load(f)
        
        # Get media field configuration
        if 'media_fields' not in config or media_field not in config['media_fields']:
            return jsonify({'error': f'Media field {media_field} not found in configuration'}), 400
        
        media_config = config['media_fields'][media_field]
        target_dir = media_config.get('directory', f'media/{media_field}')
        
        # Ensure target directory includes 'media/' prefix if not already present
        if not target_dir.startswith('media/'):
            target_dir = f'media/{target_dir}'
        
        # Load gamelist
        gamelist_path = get_gamelist_path(system_name)
        if not os.path.exists(gamelist_path):
            return jsonify({'error': 'Gamelist not found'}), 404
        
        games = parse_gamelist_xml(gamelist_path)
        if not games:
            return jsonify({'error': 'No games found in gamelist'}), 400
        
        # Check for conflicts
        conflicts = []
        for game in games:
            if media_field in game and game[media_field]:
                current_path = game[media_field]
                
                # Convert relative path to full path
                if current_path.startswith('./'):
                    current_path = current_path[2:]  # Remove './' prefix
                
                filename = os.path.basename(current_path)
                target_path = os.path.join('roms', system_name, target_dir, filename)
                
                # Check if target file exists and is different from source
                if os.path.exists(target_path):
                    # Get full path to current file for comparison
                    full_current_path = os.path.join('roms', system_name, current_path)
                    
                    # Only consider it a conflict if it's a different file
                    if not os.path.samefile(full_current_path, target_path):
                        conflicts.append({
                            'game_name': game.get('name', 'Unknown'),
                            'filename': filename,
                            'current_path': current_path,
                            'target_path': target_path
                        })
        
        return jsonify({
            'success': True,
            'conflicts': conflicts
        })
        
    except Exception as e:
        print(f"Error checking move medias conflicts: {e}")
        return jsonify({'error': f'Internal server error: {str(e)}'}), 500

@app.route('/api/move-medias/dry-run', methods=['POST'])
@login_required
def dry_run_move_medias():
    """Dry run to show what files would be moved without actually moving them"""
    try:
        data = request.get_json()
        if not data:
            return jsonify({'error': 'No data provided'}), 400
        
        system_name = data.get('system_name')
        media_field = data.get('media_field')
        
        if not all([system_name, media_field]):
            return jsonify({'error': 'System name and media field are required'}), 400
        
        # Load configuration to get media field directory
        config_path = os.path.join('var', 'config', 'config.json')
        if not os.path.exists(config_path):
            return jsonify({'error': 'Configuration not found'}), 404
        
        with open(config_path, 'r', encoding='utf-8') as f:
            config = json.load(f)
        
        # Get media field configuration
        if 'media_fields' not in config or media_field not in config['media_fields']:
            return jsonify({'error': f'Media field {media_field} not found in configuration'}), 400
        
        media_config = config['media_fields'][media_field]
        target_dir = media_config.get('directory', f'media/{media_field}')
        
        # Ensure target directory includes 'media/' prefix if not already present
        if not target_dir.startswith('media/'):
            target_dir = f'media/{target_dir}'
        
        print(f"🔧 DEBUG: DRY RUN - Media field: {media_field}")
        print(f"🔧 DEBUG: DRY RUN - Target directory: {target_dir}")
        
        # Load gamelist
        gamelist_path = get_gamelist_path(system_name)
        if not os.path.exists(gamelist_path):
            return jsonify({'error': 'Gamelist not found'}), 404
        
        games = parse_gamelist_xml(gamelist_path)
        if not games:
            return jsonify({'error': 'No games found in gamelist'}), 400
        
        # Create target directory path for checking
        full_target_dir = os.path.join('roms', system_name, target_dir)
        print(f"🔧 DEBUG: DRY RUN - Full target directory: {full_target_dir}")
        
        # Process each game and create dry-run report
        would_move_files = []
        would_skip_files = []
        would_clear_fields = []
        
        for game in games:
            if media_field in game and game[media_field]:
                current_path = game[media_field]
                game_name = game.get('name', 'Unknown')
                
                print(f"🔧 DEBUG: DRY RUN - Processing game: {game_name}")
                print(f"🔧 DEBUG: DRY RUN - Current path: {current_path}")
                
                # Use the exact path from gamelist.xml as source
                if current_path.startswith('./'):
                    current_path = current_path[2:]  # Remove './' prefix
                
                # Construct the full source path exactly as specified in gamelist.xml
                full_source_path = os.path.join('roms', system_name, current_path)
                filename = os.path.basename(current_path)
                target_path = os.path.join(full_target_dir, filename)
                
                print(f"🔧 DEBUG: DRY RUN - Source path: {full_source_path}")
                print(f"🔧 DEBUG: DRY RUN - Target path: {target_path}")
                
                # Check if source file exists
                if os.path.exists(full_source_path):
                    # File exists, check if target file already exists
                    if os.path.exists(target_path):
                        # Target file already exists - would skip
                        would_skip_files.append({
                            'game_name': game_name,
                            'current_path': current_path,
                            'target_path': f"{target_dir}/{filename}",
                            'reason': 'Target file already exists'
                        })
                        print(f"🔧 DEBUG: DRY RUN - Would skip (target exists): {current_path}")
                    else:
                        # Target doesn't exist, would move
                        would_move_files.append({
                            'game_name': game_name,
                            'old_path': current_path,
                            'new_path': f"{target_dir}/{filename}",
                            'source_file_path': full_source_path
                        })
                        print(f"🔧 DEBUG: DRY RUN - Would move: {current_path} → {target_dir}/{filename}")
                else:
                    # File doesn't exist, would clear the field
                    would_clear_fields.append({
                        'game_name': game_name,
                        'old_path': current_path,
                        'reason': 'File not found'
                    })
                    print(f"🔧 DEBUG: DRY RUN - Would clear field (file not found): {current_path}")
        
        # Create dry-run results
        results = {
            'would_move_files': would_move_files,
            'would_skip_files': would_skip_files,
            'would_clear_fields': would_clear_fields,
            'summary': {
                'total_processed': len(would_move_files) + len(would_skip_files) + len(would_clear_fields),
                'would_move_count': len(would_move_files),
                'would_skip_count': len(would_skip_files),
                'would_clear_count': len(would_clear_fields)
            }
        }
        
        return jsonify({
            'success': True,
            'dry_run': True,
            'results': results
        })
        
    except Exception as e:
        print(f"Error in dry run move medias: {e}")
        return jsonify({'error': f'Internal server error: {str(e)}'}), 500

@app.route('/api/move-medias/validate', methods=['POST'])
@login_required
def validate_move_medias():
    """Move media files to their proper directories and update gamelist"""
    try:
        data = request.get_json()
        if not data:
            return jsonify({'error': 'No data provided'}), 400
        
        system_name = data.get('system_name')
        media_field = data.get('media_field')
        
        if not all([system_name, media_field]):
            return jsonify({'error': 'System name and media field are required'}), 400
        
        # Load configuration to get media field directory
        config_path = os.path.join('var', 'config', 'config.json')
        if not os.path.exists(config_path):
            return jsonify({'error': 'Configuration not found'}), 404
        
        with open(config_path, 'r', encoding='utf-8') as f:
            config = json.load(f)
        
        # Get media field configuration
        if 'media_fields' not in config or media_field not in config['media_fields']:
            return jsonify({'error': f'Media field {media_field} not found in configuration'}), 400
        
        media_config = config['media_fields'][media_field]
        target_dir = media_config.get('directory', f'media/{media_field}')
        
        # Ensure target directory includes 'media/' prefix if not already present
        if not target_dir.startswith('media/'):
            target_dir = f'media/{target_dir}'
        
        print(f"🔧 DEBUG: Media field: {media_field}")
        print(f"🔧 DEBUG: Target directory from config: {media_config.get('directory', f'media/{media_field}')}")
        print(f"🔧 DEBUG: Final target directory: {target_dir}")
        
        # Load gamelist
        gamelist_path = get_gamelist_path(system_name)
        if not os.path.exists(gamelist_path):
            return jsonify({'error': 'Gamelist not found'}), 404
        
        games = parse_gamelist_xml(gamelist_path)
        if not games:
            return jsonify({'error': 'No games found in gamelist'}), 400
        
        # Create target directory if it doesn't exist
        full_target_dir = os.path.join('roms', system_name, target_dir)
        print(f"🔧 DEBUG: Full target directory: {full_target_dir}")
        os.makedirs(full_target_dir, exist_ok=True)
        
        # Process each game and create comprehensive report
        moved_files = []
        unmoved_files = []
        cleared_fields = []
        
        for game in games:
            if media_field in game and game[media_field]:
                current_path = game[media_field]
                game_name = game.get('name', 'Unknown')
                
                print(f"🔧 DEBUG: Processing game: {game_name}")
                print(f"🔧 DEBUG: Current path: {current_path}")
                
                # Use the exact path from gamelist.xml as source
                if current_path.startswith('./'):
                    current_path = current_path[2:]  # Remove './' prefix
                
                # Construct the full source path exactly as specified in gamelist.xml
                full_source_path = os.path.join('roms', system_name, current_path)
                filename = os.path.basename(current_path)
                target_path = os.path.join(full_target_dir, filename)
                
                print(f"🔧 DEBUG: Source path from gamelist: {current_path}")
                print(f"🔧 DEBUG: Full source path: {full_source_path}")
                print(f"🔧 DEBUG: Target path: {target_path}")
                
                # Check if source file exists
                if os.path.exists(full_source_path):
                    # File exists, check if target file already exists
                    if os.path.exists(target_path):
                        # Target file already exists - conflict
                        unmoved_files.append({
                            'game_name': game_name,
                            'current_path': current_path,
                            'target_path': f"{target_dir}/{filename}",
                            'reason': 'Target file already exists'
                        })
                        print(f"🔧 DEBUG: Target file already exists - conflict")
                    else:
                        # Target doesn't exist, safe to move
                        try:
                            shutil.move(full_source_path, target_path)
                            
                            # Update gamelist with new path
                            new_relative_path = os.path.join(target_dir, filename)
                            game[media_field] = new_relative_path
                            
                            moved_files.append({
                                'game_name': game_name,
                                'old_path': current_path,
                                'new_path': new_relative_path,
                                'source_file_path': full_source_path
                            })
                            print(f"🔧 DEBUG: Successfully moved file: {current_path} → {new_relative_path}")
                        except Exception as e:
                            unmoved_files.append({
                                'game_name': game_name,
                                'current_path': current_path,
                                'target_path': f"{target_dir}/{filename}",
                                'reason': f'Error moving file: {str(e)}'
                            })
                            print(f"🔧 DEBUG: Error moving file: {str(e)}")
                else:
                    # File doesn't exist, clear the field
                    game[media_field] = ''
                    cleared_fields.append({
                        'game_name': game_name,
                        'old_path': current_path,
                        'reason': 'File not found'
                    })
                    print(f"🔧 DEBUG: File not found - cleared field")
        
        # Save updated gamelist
        write_gamelist_xml(games, gamelist_path)
        
        # Create comprehensive results
        results = {
            'moved_files': moved_files,
            'unmoved_files': unmoved_files,
            'cleared_fields': cleared_fields,
            'summary': {
                'total_processed': len(moved_files) + len(unmoved_files) + len(cleared_fields),
                'moved_count': len(moved_files),
                'unmoved_count': len(unmoved_files),
                'cleared_count': len(cleared_fields)
            }
        }
        
        return jsonify({
            'success': True,
            'results': results
        })
        
    except Exception as e:
        print(f"Error validating move medias: {e}")
        return jsonify({'error': f'Internal server error: {str(e)}'}), 500

@app.route('/api/multiscraper-search', methods=['POST'])
@login_required
def multiscraper_search_endpoint():
    """Search for media from multiple sources for a specific game and media type"""
    try:
        data = request.get_json()
        if not data:
            return jsonify({'error': 'No data provided'}), 400
        
        game_name = data.get('game_name')
        media_type = data.get('media_type')
        system_name = data.get('system_name')
        
        if not all([game_name, media_type, system_name]):
            return jsonify({'error': 'Game name, media type, and system name are required'}), 400
        
        print(f"🔧 DEBUG: Multiscraper search - Game: {game_name}, Media Type: {media_type}, System: {system_name}")
        
        import time
        total_start_time = time.time()
        
        # Find the game in the current system
        gamelist_start_time = time.time()
        gamelist_path = get_gamelist_path(system_name)
        if not os.path.exists(gamelist_path):
            return jsonify({'error': 'Gamelist not found'}), 404
        
        games = parse_gamelist_xml(gamelist_path)
        game = next((g for g in games if g.get('name') == game_name), None)
        gamelist_end_time = time.time()
        print(f"⏱️ Gamelist parsing took {gamelist_end_time - gamelist_start_time:.3f} seconds")
        
        if not game:
            return jsonify({'error': 'Game not found in gamelist'}), 404
        
        # Get system configuration
        config_start_time = time.time()
        systems_config = load_systems_config()
        sys_config = systems_config.get(system_name, {})
        config_end_time = time.time()
        print(f"⏱️ System config loading took {config_end_time - config_start_time:.3f} seconds")
        
        # Use manual scrap functionality for all scrapers
        import asyncio
        from datetime import datetime
        
        # Create a copy of the game for manual scrap
        current_game = game.copy()
        
        # Run manual scrap for all available scrapers
        scrap_results = {}
        
        print(f"🔧 DEBUG: Running scrapers for multiscraper search")
        
        # Execute IGDB scraper if game has igdbid and supports the media type
        if current_game.get('igdbid'):
            # Check if IGDB supports this media type
            igdb_image_mapping = scrappers_config.get('igdb', {}).get('image_type_mappings', {})
            if media_type in igdb_image_mapping:
                try:
                    print(f"🔧 DEBUG: Running igdb scraper...")
                    igdb_start_time = time.time()
                    result = run_async_safely(scrape_igdb_manual(current_game, system_name, sys_config, target_media_type=media_type))
                    igdb_end_time = time.time()
                    print(f"⏱️ IGDB scraper took {igdb_end_time - igdb_start_time:.3f} seconds")
                    if result:
                        print(f"🔧 DEBUG: igdb scraper returned data with keys: {list(result.keys())}")
                        scrap_results['igdb'] = result
                    else:
                        print(f"🔧 DEBUG: igdb scraper returned None")
                except Exception as e:
                    print(f"🔧 DEBUG: igdb scraper failed: {e}")
                    import traceback
                    print(f"🔧 DEBUG: igdb traceback: {traceback.format_exc()}")
            else:
                print(f"🔧 DEBUG: Skipping IGDB scraper - no mapping for media type '{media_type}'")
        
        # Execute Steam scraper if game has steamid and supports the media type
        if current_game.get('steamid'):
            # Check if Steam supports this media type
            steam_image_mapping = scrappers_config.get('steam', {}).get('image_type_mappings', {})
            if media_type in steam_image_mapping:
                try:
                    print(f"🔧 DEBUG: Running steam scraper...")
                    steam_start_time = time.time()
                    result = run_async_safely(scrape_steam_manual(current_game, system_name, target_media_type=media_type))
                    steam_end_time = time.time()
                    print(f"⏱️ Steam scraper took {steam_end_time - steam_start_time:.3f} seconds")
                    if result:
                        print(f"🔧 DEBUG: steam scraper returned data with keys: {list(result.keys())}")
                        scrap_results['steam'] = result
                    else:
                        print(f"🔧 DEBUG: steam scraper returned None")
                except Exception as e:
                    print(f"🔧 DEBUG: steam scraper failed: {e}")
                    import traceback
                    print(f"🔧 DEBUG: steam traceback: {traceback.format_exc()}")
            else:
                print(f"🔧 DEBUG: Skipping Steam scraper - no mapping for media type '{media_type}'")
        
        # Execute ScreenScraper if game has screenscraperid and supports the media type
        if current_game.get('screenscraperid'):
            # Check if ScreenScraper supports this media type
            screenscraper_image_mapping = scrappers_config.get('screenscraper', {}).get('image_type_mappings', {})
            if media_type in screenscraper_image_mapping:
                try:
                    print(f"🔧 DEBUG: Running screenscraper scraper...")
                    screenscraper_start_time = time.time()
                    result = run_async_safely(scrape_screenscraper_manual(current_game, system_name, sys_config, target_media_type=media_type))
                    screenscraper_end_time = time.time()
                    print(f"⏱️ ScreenScraper took {screenscraper_end_time - screenscraper_start_time:.3f} seconds")
                    if result:
                        print(f"🔧 DEBUG: screenscraper scraper returned data with keys: {list(result.keys())}")
                        scrap_results['screenscraper'] = result
                    else:
                        print(f"🔧 DEBUG: screenscraper scraper returned None")
                except Exception as e:
                    print(f"🔧 DEBUG: screenscraper scraper failed: {e}")
                    import traceback
                    print(f"🔧 DEBUG: screenscraper traceback: {traceback.format_exc()}")
            else:
                print(f"🔧 DEBUG: Skipping ScreenScraper - no mapping for media type '{media_type}'")
        
        # Execute SteamGridDB scraper if game has steamgridid and supports the media type
        if current_game.get('steamgridid'):
            # Check if SteamGridDB supports this media type
            steamgrid_image_mapping = scrappers_config.get('steamgriddb', {}).get('image_type_mappings', {})
            if media_type in steamgrid_image_mapping:
                try:
                    print(f"🔧 DEBUG: Running steamgriddb scraper...")
                    steamgrid_start_time = time.time()
                    result = run_async_safely(scrape_steamgriddb_manual(current_game, system_name, target_media_type=media_type))
                    steamgrid_end_time = time.time()
                    print(f"⏱️ SteamGridDB took {steamgrid_end_time - steamgrid_start_time:.3f} seconds")
                    if result:
                        print(f"🔧 DEBUG: steamgriddb scraper returned data with keys: {list(result.keys())}")
                        scrap_results['steamgriddb'] = result
                    else:
                        print(f"🔧 DEBUG: steamgriddb scraper returned None")
                except Exception as e:
                    print(f"🔧 DEBUG: steamgriddb scraper failed: {e}")
                    import traceback
                    print(f"🔧 DEBUG: steamgriddb traceback: {traceback.format_exc()}")
            else:
                print(f"🔧 DEBUG: Skipping SteamGridDB - no mapping for media type '{media_type}'")
        
        # Execute LaunchBox scraper if game has launchboxid and supports the media type
        if current_game.get('launchboxid'):
            # Check if LaunchBox supports this media type
            launchbox_image_mapping = scrappers_config.get('launchbox', {}).get('image_type_mappings', {})
            if media_type in launchbox_image_mapping:
                try:
                    print(f"🔧 DEBUG: Running launchbox scraper...")
                    launchbox_start_time = time.time()
                    result = run_async_safely(scrape_launchbox_manual(current_game, system_name, target_media_type=media_type))
                    launchbox_end_time = time.time()
                    print(f"⏱️ LaunchBox took {launchbox_end_time - launchbox_start_time:.3f} seconds")
                    if result:
                        print(f"🔧 DEBUG: launchbox scraper returned data with keys: {list(result.keys())}")
                        scrap_results['launchbox'] = result
                    else:
                        print(f"🔧 DEBUG: launchbox scraper returned None")
                except Exception as e:
                    print(f"🔧 DEBUG: launchbox scraper failed: {e}")
                    import traceback
                    print(f"🔧 DEBUG: launchbox traceback: {traceback.format_exc()}")
            else:
                print(f"🔧 DEBUG: Skipping LaunchBox - no mapping for media type '{media_type}'")
        
        # Execute MobyGames scraper if game has mobygamesid and supports the media type
        if current_game.get('mobygamesid'):
            # Check if MobyGames supports this media type
            mobygames_image_mapping = scrappers_config.get('mobygames', {}).get('image_type_mappings', {})
            if media_type in mobygames_image_mapping:
                try:
                    print(f"🔧 DEBUG: Running mobygames scraper...")
                    mobygames_start_time = time.time()
                    result = run_async_safely(scrape_mobygames_manual(current_game, system_name, sys_config, target_media_type=media_type))
                    mobygames_end_time = time.time()
                    print(f"⏱️ MobyGames took {mobygames_end_time - mobygames_start_time:.3f} seconds")
                    if result:
                        print(f"🔧 DEBUG: mobygames scraper returned data with keys: {list(result.keys())}")
                        scrap_results['mobygames'] = result
                    else:
                        print(f"🔧 DEBUG: mobygames scraper returned None")
                except Exception as e:
                    print(f"🔧 DEBUG: mobygames scraper failed: {e}")
                    import traceback
                    print(f"🔧 DEBUG: mobygames traceback: {traceback.format_exc()}")
            else:
                print(f"🔧 DEBUG: Skipping MobyGames - no mapping for media type '{media_type}'")
        
        # Filter results to only include the requested media type
        processing_start_time = time.time()
        results = []
        for scraper_name, scrap_data in scrap_results.items():
            print(f"🔧 DEBUG: Processing {scraper_name} scraper data")
            if scrap_data and 'media_fields' in scrap_data:
                media_fields = scrap_data['media_fields']
                print(f"🔧 DEBUG: {scraper_name} media_fields keys: {list(media_fields.keys())}")
                if media_type in media_fields and media_fields[media_type]:
                    print(f"🔧 DEBUG: {scraper_name} has {media_type} with {len(media_fields[media_type])} items")
                    # Handle both single URL strings and arrays of media objects
                    media_items = media_fields[media_type]
                    if isinstance(media_items, list):
                        # Multiple media items - add each one
                        for i, item in enumerate(media_items):
                            if isinstance(item, dict):
                                # Media object with url, region, type, etc.
                                url = item.get('url')
                                if url:
                                    results.append({
                                        'url': url,
                                        'source': scraper_name.title(),
                                        'type': media_type,
                                        'region': item.get('region', 'Unknown')
                                    })
                                    print(f"🔧 DEBUG: Added {scraper_name} result {i+1}: {url}")
                            elif isinstance(item, str):
                                # Simple URL string
                                if item:
                                    results.append({
                                        'url': item,
                                        'source': scraper_name.title(),
                                        'type': media_type
                                    })
                                    print(f"🔧 DEBUG: Added {scraper_name} result {i+1}: {item}")
                    elif isinstance(media_items, str):
                        # Single URL string
                        if media_items:
                            results.append({
                                'url': media_items,
                                'source': scraper_name.title(),
                                'type': media_type
                            })
                            print(f"🔧 DEBUG: Added {scraper_name} single result: {media_items}")
                else:
                    print(f"🔧 DEBUG: {scraper_name} has no {media_type} or empty {media_type}")
            else:
                print(f"🔧 DEBUG: {scraper_name} has no media_fields or scrap_data is None")
        
        processing_end_time = time.time()
        print(f"⏱️ Result processing took {processing_end_time - processing_start_time:.3f} seconds")
        
        total_end_time = time.time()
        print(f"⏱️ TOTAL multiscraper search took {total_end_time - total_start_time:.3f} seconds")
        
        print(f"🔧 DEBUG: Found {len(results)} results for media type '{media_type}' from {len(scrap_results)} scrapers")
        
        return jsonify({
            'success': True,
            'results': results
        })
        
    except Exception as e:
        print(f"Error in multiscraper search: {e}")
        return jsonify({'error': f'Internal server error: {str(e)}'}), 500

@app.route('/api/download-multiscraper-media', methods=['POST'])
@login_required
def download_multiscraper_media_endpoint():
    """Download media from multiscraper search results"""
    try:
        data = request.get_json()
        if not data:
            return jsonify({'error': 'No data provided'}), 400
        
        media_url = data.get('media_url')
        game_name = data.get('game_name')
        media_type = data.get('media_type')
        system_name = data.get('system_name')
        
        if not all([media_url, game_name, media_type, system_name]):
            return jsonify({'error': 'Media URL, game name, media type, and system name are required'}), 400
        
        print(f"🔧 DEBUG: Downloading multiscraper media - URL: {media_url}, Game: {game_name}, Type: {media_type}, System: {system_name}")
        
        # Find the game in the current system
        gamelist_path = get_gamelist_path(system_name)
        print(f"🔧 DEBUG: Gamelist path: {gamelist_path}")
        if not os.path.exists(gamelist_path):
            print(f"🔧 DEBUG: Gamelist not found at {gamelist_path}")
            return jsonify({'error': 'Gamelist not found'}), 404
        
        games = parse_gamelist_xml(gamelist_path)
        print(f"🔧 DEBUG: Parsed {len(games)} games from gamelist")
        game = next((g for g in games if g.get('name') == game_name), None)
        
        if not game:
            print(f"🔧 DEBUG: Game '{game_name}' not found in gamelist")
            return jsonify({'error': 'Game not found in gamelist'}), 404
        
        print(f"🔧 DEBUG: Found game: {game.get('name')} with path: {game.get('path')}")
        
        # Download the media
        success = download_and_save_media(media_url, game, media_type, system_name)
        
        if success:
            # Update the gamelist
            write_gamelist_xml(games, gamelist_path)
            
            # Notify all connected clients about the game update
            notify_game_updated(system_name, game.get('path', ''), [media_type])
            
            return jsonify({'success': True, 'message': 'Media downloaded successfully'})
        else:
            return jsonify({'error': 'Failed to download media'}), 500
        
    except Exception as e:
        print(f"Error downloading multiscraper media: {e}")
        return jsonify({'error': f'Internal server error: {str(e)}'}), 500

@app.route('/api/fanart-search', methods=['POST'])
@login_required
def fanart_search_endpoint():
    """Search for fanart images by game name similarity across scrapers"""
    global global_metadata_cache, global_metadata_cache_loaded
    try:
        data = request.get_json()
        if not data:
            return jsonify({'error': 'No data provided'}), 400
        
        game_name = data.get('game_name')
        system_name = data.get('system_name')
        selected_scraper = data.get('scraper', 'all')  # Default to 'all' if not specified
        direct_match = data.get('direct_match', True)  # Default to True (direct match)
        
        if not all([game_name, system_name]):
            return jsonify({'error': 'Game name and system name are required'}), 400
        
        print(f"🔧 DEBUG: Fanart search for game: {game_name}, system: {system_name}, scraper: {selected_scraper}, direct_match: {direct_match}")
        
        # Get scrapers that have fanart mapped
        scrapers_config = load_scrappers_config()
        print(f"🔧 DEBUG: Scrapers config: {type(scrapers_config)}")
        print(f"🔧 DEBUG: Scrapers config keys: {list(scrapers_config.keys()) if scrapers_config else 'None'}")
        
        fanart_scrapers = {}
        for scraper_name, scraper_config in scrapers_config.items():
            # Skip if specific scraper is selected and this isn't it
            if selected_scraper != 'all' and selected_scraper != scraper_name:
                continue
                
            print(f"🔧 DEBUG: Checking scraper: {scraper_name}")
            print(f"🔧 DEBUG: Scraper config type: {type(scraper_config)}")
            print(f"🔧 DEBUG: Scraper config keys: {list(scraper_config.keys()) if isinstance(scraper_config, dict) else 'Not a dict'}")
            
            image_mappings = scraper_config.get('image_type_mappings', {})
            print(f"🔧 DEBUG: Image mappings for {scraper_name}: {image_mappings}")
            print(f"🔧 DEBUG: 'fanart' in image_mappings: {'fanart' in image_mappings}")
            
            if 'fanart' in image_mappings:
                fanart_scrapers[scraper_name] = scraper_config
                print(f"🔧 DEBUG: Added {scraper_name} to fanart scrapers")
            else:
                print(f"🔧 DEBUG: {scraper_name} does not have fanart mapping")
        
        print(f"🔧 DEBUG: Found fanart scrapers: {list(fanart_scrapers.keys())}")
        print(f"🔧 DEBUG: Fanart scrapers count: {len(fanart_scrapers)}")
        
        # Search for fanart using each scraper - reuse existing search functions
        all_fanart_results = []
        
        for scraper_name, scraper_config in fanart_scrapers.items():
            try:
                print(f"🔧 DEBUG: Searching {scraper_name} for fanart...")
                
                if scraper_name == 'igdb':
                    # Use existing IGDB search function
                    igdb_service = load_igdb_service()
                    if igdb_service:
                        print(f"🔧 DEBUG: Searching IGDB for '{game_name}' using direct match: {direct_match}")
                        
                        if direct_match:
                            # For direct match, use the same logic as IGDB scraping task
                            from game_utils import normalize_game_name
                            normalized_name = normalize_game_name(game_name, remove_paranthesis=True, remove_articles=True)
                            print(f"🔧 DEBUG: IGDB direct match - normalized name: '{normalized_name}'")
                            
                            results = []
                            
                            # Search across all platforms using the same logic as scraping task
                            for platform_id in igdb_service.platform_index.keys():
                                if normalized_name and platform_id in igdb_service.platform_index:
                                    platform_data = igdb_service.platform_index[platform_id]
                                    first_char = normalized_name[0].lower()
                                    
                                    if first_char in platform_data:
                                        partition_games = platform_data[first_char]
                                        if normalized_name in partition_games:
                                            # Direct match found!
                                            game_id = partition_games[normalized_name]
                                            print(f"✅ IGDB Direct match found for '{game_name}' (normalized: '{normalized_name}') -> ID: {game_id} on platform {platform_id}")
                                            
                                            # Get the full game data from igdb_db dictionary
                                            if game_id in igdb_service.igdb_data:
                                                game_data = igdb_service.igdb_data[game_id].copy()
                                                game_data['_similarity_score'] = 1.0  # Exact match
                                                results.append(game_data)
                                                print(f"🔧 DEBUG: IGDB direct match - found game: '{game_data.get('name', '')}' (ID: {game_id})")
                                            else:
                                                print(f"🔧 DEBUG: IGDB direct match - game ID {game_id} not found in igdb_db")
                                            
                                            # Stop at first platform with exact match
                                            break
                                        else:
                                            print(f"❌ IGDB No direct match found for '{game_name}' (normalized: '{normalized_name}') in platform {platform_id}")
                                    else:
                                        print(f"❌ IGDB No games found for first character '{first_char}' in platform {platform_id}")
                                else:
                                    print(f"❌ IGDB Platform {platform_id} not found in index or empty normalized name")
                            
                            print(f"🔧 DEBUG: IGDB direct match - found {len(results)} exact matches")
                        else:
                            # For similarity search, search across all platforms and filter by similarity
                            results = []
                            for platform_id in igdb_service.platform_index.keys():
                                platform_results = igdb_service.search_games_by_name(game_name, platform_id, limit=50)
                                # Filter for high similarity matches (>90%) and log what we're filtering
                                for result in platform_results:
                                    similarity = result.get('_similarity_score', 0)
                                    if similarity > 0.9:
                                        results.append(result)
                                        print(f"🔧 DEBUG: IGDB similarity match: '{result.get('name', '')}' (ID: {result.get('id', '')}) with similarity {similarity:.2f}")
                                    else:
                                        print(f"🔧 DEBUG: IGDB filtered out: '{result.get('name', '')}' (ID: {result.get('id', '')}) with similarity {similarity:.2f} (too low)")
                            
                            # Sort by similarity score and take top 50
                            results.sort(key=lambda x: x.get('_similarity_score', 0), reverse=True)
                            results = results[:50]
                            print(f"🔧 DEBUG: Found {len(results)} similar matches (>90%) across all platforms")
                        
                        for game in results:
                            print(f"🔧 DEBUG: Processing IGDB game: '{game.get('name', '')}' (ID: {game.get('id', '')})")
                            print(f"🔧 DEBUG: Game keys: {list(game.keys())}")
                            print(f"🔧 DEBUG: Has artworks: {'artworks' in game}")
                            if 'artworks' in game:
                                print(f"🔧 DEBUG: Artworks value: {game['artworks']}")
                            
                            # Check if game has artworks (fanart)
                            if 'artworks' in game and game['artworks']:
                                artworks = game['artworks'] if isinstance(game['artworks'], list) else [game['artworks']]
                                fanart_urls = []
                                
                                # Convert IGDB artwork IDs to full URLs
                                for artwork in artworks:
                                    artwork_url = normalize_igdb_url(artwork)
                                    fanart_urls.append(artwork_url)
                                
                                # Get platform name for display
                                platform_name = 'Unknown'
                                if 'platform' in game and game['platform']:
                                    platform_name = game['platform'].get('name', 'Unknown')
                                
                                all_fanart_results.append({
                                    'scraper': 'igdb',
                                    'game_name': game.get('name', ''),
                                    'game_id': game.get('id', ''),
                                    'similarity_score': game.get('_similarity_score', 0.0),
                                    'fanart_urls': fanart_urls,
                                    'region': 'Unknown',
                                    'platform': platform_name
                                })
                                print(f"🔧 DEBUG: Found IGDB fanart for '{game.get('name', '')}' - {len(fanart_urls)} images, similarity: {game.get('_similarity_score', 0.0):.2f}")
                            else:
                                print(f"🔧 DEBUG: IGDB game '{game.get('name', '')}' has no artworks/fanart")
                    else:
                        print(f"🔧 DEBUG: IGDB service not available")
                
                elif scraper_name == 'steam':
                    # Use existing Steam search function
                    steam_service = load_steam_service()
                    if steam_service:
                        if direct_match:
                            # For direct match, search for exact matches using search_steam_apps
                            results = steam_service.search_steam_apps(game_name, limit=50)
                            # Add similarity score of 1.0 for exact matches
                            for result in results:
                                result['similarity_score'] = 1.0
                        else:
                            # For similarity search, use find_similarity_matches with higher limit
                            results = steam_service.find_similarity_matches(game_name, [], limit=50)
                        
                        print(f"🔧 DEBUG: Steam search found {len(results)} results")
                        
                        for game in results:
                            # Only include results with similarity score > 85%
                            similarity_score = game.get('similarity_score', 0.0)
                            if similarity_score > 0.85:
                                # Generate hero URL from Steam app ID
                                steam_id = game.get('appid')
                                if steam_id:
                                    hero_url = f"https://shared.steamstatic.com/store_item_assets/steam/apps/{steam_id}/library_hero.jpg"
                                    all_fanart_results.append({
                                        'scraper': 'steam',
                                        'game_name': game.get('name', ''),
                                        'game_id': steam_id,
                                        'similarity_score': similarity_score,
                                        'fanart_urls': [hero_url],
                                        'region': 'Unknown'
                                    })
                                    print(f"🔧 DEBUG: Found Steam fanart for '{game.get('name', '')}' - similarity: {similarity_score:.3f}")
                            else:
                                print(f"🔧 DEBUG: Skipped Steam game '{game.get('name', '')}' - similarity too low: {similarity_score:.3f}")
                    else:
                        print(f"🔧 DEBUG: Steam service not available")
                
                elif scraper_name == 'steamgriddb':
                    # Use existing SteamGridDB search function
                    from steamgrid_service import SteamGridService
                    sgdb_service = SteamGridService()
                    
                    # Check if API key is available
                    api_key = sgdb_service.get_api_key()
                    print(f"🔧 DEBUG: SteamGridDB API key check: {'Found' if api_key else 'Not found'}")
                    if api_key:
                        print(f"🔧 DEBUG: SteamGridDB API key: {api_key[:8]}...{api_key[-4:] if len(api_key) > 12 else '***'}")
                    if not api_key:
                        print(f"🔧 DEBUG: SteamGridDB API key not configured")
                        continue
                    
                    # Get SteamGridDB games by name with multiple variations
                    games = []
                    
                    # Search with original name
                    original_games = run_async_safely(sgdb_service.get_steamgrid_id_by_name(game_name, api_key=api_key, limit=50))
                    games.extend(original_games)
                    
                    # Search with cleaned name (remove parentheses)
                    import re
                    cleaned_name = re.sub(r'\s*\([^)]*\)', '', game_name).strip()
                    if cleaned_name != game_name:
                        cleaned_games = run_async_safely(sgdb_service.get_steamgrid_id_by_name(cleaned_name, api_key=api_key, limit=50))
                        games.extend(cleaned_games)
                    
                    # Remove duplicates based on game ID
                    seen_ids = set()
                    unique_games = []
                    for game in games:
                        game_id = game.get('id')
                        if game_id and game_id not in seen_ids:
                            seen_ids.add(game_id)
                            unique_games.append(game)
                    
                    games = unique_games
                    print(f"🔧 DEBUG: SteamGridDB found {len(games)} unique games after deduplication")
                    
                    for game in games:
                        steamgrid_id = game.get('id')
                        if steamgrid_id:
                            # Get media for this game
                            media = run_async_safely(sgdb_service.get_steamgrid_media(steamgrid_id, ['heroes'], api_key=api_key))
                            
                            if media and 'heroes' in media and media['heroes']:
                                # Add each hero image as a separate result
                                for hero in media['heroes']:
                                    all_fanart_results.append({
                                        'scraper': 'steamgriddb',
                                        'game_name': game.get('name', ''),
                                        'game_id': steamgrid_id,
                                        'similarity_score': 1.0,  # SteamGridDB doesn't provide similarity scores
                                        'fanart_urls': [hero.get('url', '')],
                                        'region': 'Unknown'
                                    })
                                print(f"🔧 DEBUG: Found SteamGridDB fanart for '{game.get('name', '')}' - {len(media['heroes'])} images")
                
                elif scraper_name == 'screenscraper':
                    # Use existing ScreenScraper search function
                    from screenscraper_service import ScreenScraperService
                    from credential_manager import credential_manager
                    config = load_config()
                    screenscraper_creds = credential_manager.get_screenscraper_credentials()
                    scrappers_config = load_scrappers_config()
                    systems_config = load_systems_config()
                    
                    ss_service = ScreenScraperService(config, screenscraper_creds, scrappers_config, systems_config)
                    results = run_async_safely(ss_service.search_games_by_name(game_name, system_name, limit=10, search_all_systems=True))
                    
                    # Collect all game IDs for parallel processing
                    game_ids_to_fetch = []
                    for game in results:
                        game_id = game.get('jeu_id')
                        if game_id:
                            game_ids_to_fetch.append((game_id, game))
                            print(f"🔧 DEBUG: Will fetch ScreenScraper game: '{game.get('name', '')}' (ID: {game_id})")
                        else:
                            print(f"🔧 DEBUG: ScreenScraper game has no ID")
                    
                    if game_ids_to_fetch:
                        # Fetch all game data in parallel
                        import asyncio
                        async def fetch_all_game_data():
                            tasks = []
                            for game_id, game in game_ids_to_fetch:
                                task = ss_service.get_game_by_id(game_id, system_name)
                                tasks.append((task, game))
                            
                            # Execute all tasks in parallel
                            results_data = await asyncio.gather(*[task for task, _ in tasks], return_exceptions=True)
                            
                            # Process results
                            for i, (result_data, original_game) in enumerate(zip(results_data, [game for _, game in game_ids_to_fetch])):
                                if isinstance(result_data, Exception):
                                    print(f"🔧 DEBUG: Error fetching game data for '{original_game.get('name', '')}': {result_data}")
                                    continue
                                
                                full_game_data = result_data
                                if full_game_data:
                                    print(f"🔧 DEBUG: Full game data keys for '{original_game.get('name', '')}': {list(full_game_data.keys())}")
                                    
                                    # Check if game has fanart in the medias array
                                    if 'medias' in full_game_data and full_game_data['medias']:
                                        medias = full_game_data['medias']
                                        if isinstance(medias, list):
                                            fanart_urls = []
                                            
                                            # Look for media items with type "fanart"
                                            for media in medias:
                                                if isinstance(media, dict) and media.get('type') == 'fanart':
                                                    if 'url' in media:
                                                        fanart_urls.append(media['url'])
                                                    print(f"🔧 DEBUG: Found fanart media: {media}")
                                            
                                            if fanart_urls:
                                                all_fanart_results.append({
                                                    'scraper': 'screenscraper',
                                                    'game_name': original_game.get('name', ''),
                                                    'game_id': original_game.get('jeu_id', ''),
                                                    'similarity_score': original_game.get('_similarity_score', 0.0),
                                                    'fanart_urls': fanart_urls,
                                                    'region': 'Unknown',
                                                    'platform': system_name
                                                })
                                                print(f"🔧 DEBUG: Found ScreenScraper fanart for '{original_game.get('name', '')}' - {len(fanart_urls)} images")
                                            else:
                                                print(f"🔧 DEBUG: ScreenScraper game '{original_game.get('name', '')}' has medias but no fanart type")
                                        else:
                                            print(f"🔧 DEBUG: ScreenScraper game '{original_game.get('name', '')}' medias is not a list")
                                    else:
                                        print(f"🔧 DEBUG: ScreenScraper game '{original_game.get('name', '')}' has no medias in full data")
                                else:
                                    print(f"🔧 DEBUG: Could not fetch full game data for ScreenScraper game ID {original_game.get('jeu_id', '')}")
                        
                        # Execute parallel fetch
                        run_async_safely(fetch_all_game_data())
                
                elif scraper_name == 'launchbox':
                    # Use global LaunchBox partitioned indexes for fast search (no parens only)
                    all_launchbox_results = []
                    
                    # Load global partitioned indexes
                    partition_index, partition_index_no_parens = load_launchbox_partitioned_indexes()
                    if not partition_index_no_parens:
                        print("🔧 DEBUG: LaunchBox partitioned index (no parens) not available")
                        continue
                    
                    print(f"🔧 DEBUG: Searching LaunchBox for '{game_name}' using direct match: {direct_match} (no parens index only)")
                    
                    # Load global metadata cache to get full game data (use raw cache, not derived view)
                    if not global_metadata_cache_loaded:
                        print("🔧 DEBUG: Global metadata cache not loaded yet")
                        continue
                    
                    if not global_metadata_cache:
                        print("🔧 DEBUG: Global metadata cache not available")
                        continue
                    
                    print(f"🔧 DEBUG: Global metadata cache type: {type(global_metadata_cache)}")
                    print(f"🔧 DEBUG: Global metadata cache keys count: {len(global_metadata_cache) if isinstance(global_metadata_cache, dict) else 'Not a dict'}")
                    if isinstance(global_metadata_cache, dict) and global_metadata_cache:
                        sample_keys = list(global_metadata_cache.keys())[:5]
                        print(f"🔧 DEBUG: Sample global metadata cache keys: {sample_keys}")
                        print(f"🔧 DEBUG: Sample key types: {[type(k) for k in sample_keys]}")
                    
                    # Normalize search query (no parens only)
                    from game_utils import normalize_game_name, calculate_similarity
                    
                    normalized_no_parens = normalize_game_name(game_name, remove_paranthesis=True, remove_articles=True)
                    print(f"🔧 DEBUG: Normalized without parentheses: '{normalized_no_parens}'")
                    
                    # Search through all platforms using no parens index only
                    for platform_name in partition_index_no_parens.keys():
                        try:
                            if direct_match:
                                # Use exact match with no parens normalization only
                                launchboxid = None
                                
                                if normalized_no_parens and platform_name in partition_index_no_parens:
                                    launchboxid = partition_index_no_parens[platform_name].get(normalized_no_parens)
                                
                                if launchboxid:
                                    # Convert to string for lookup in global metadata cache (cache uses string keys)
                                    launchboxid_str = str(launchboxid)
                                    print(f"🔧 DEBUG: Found game match in LaunchBox - ID: {launchboxid_str} (type: {type(launchboxid_str)}), Platform: {platform_name}")
                                    
                                    # Get full game data from global cache using string ID
                                    print(f"🔧 DEBUG: Checking if launchboxid {launchboxid_str} exists in global_metadata_cache...")
                                    
                                    found_entry = None
                                    if launchboxid_str in global_metadata_cache:
                                        found_entry = global_metadata_cache[launchboxid_str]
                                        print(f"🔧 DEBUG: Found entry in global_metadata_cache for ID {launchboxid_str}")
                                    else:
                                        print(f"🔧 DEBUG: launchboxid {launchboxid_str} NOT found in global_metadata_cache")
                                    
                                    if found_entry:
                                        entry = found_entry
                                        print(f"🔧 DEBUG: Entry keys: {list(entry.keys())}")
                                        game_elem = entry.get('game')
                                        if game_elem:
                                            print(f"🔧 DEBUG: Found game element for ID {launchboxid}")
                                            print(f"🔧 DEBUG: Game element type: {type(game_elem)}")
                                        else:
                                            print(f"🔧 DEBUG: No game element found for ID {launchboxid}")
                                    
                                    if found_entry and game_elem:
                                        # Extract game data - handle both XML element and dictionary formats
                                        game_data = {}
                                        if hasattr(game_elem, 'tag'):  # XML element
                                            for child in game_elem:
                                                if child.text:
                                                    game_data[child.tag] = child.text.strip()
                                        elif isinstance(game_elem, dict):  # Dictionary format
                                            game_data = game_elem
                                        
                                        game_name_found = game_data.get('Name', '')
                                        print(f"🔧 DEBUG: Processing game: '{game_name_found}' (ID: {launchboxid})")
                                        print(f"🔧 DEBUG: Game data structure: {game_data}")
                                        
                                        # Check if this game has fanart using the images field and scrappers.json mapping
                                        fanart_urls = []
                                        
                                        # Get fanart mapping from scrappers.json
                                        fanart_mappings = scraper_config.get('image_type_mappings', {}).get('fanart', [])
                                        print(f"🔧 DEBUG: Fanart mappings from scrappers.json: {fanart_mappings}")
                                        
                                        # Get images from the cache entry
                                        images = entry.get('images', [])
                                        print(f"🔧 DEBUG: Found {len(images)} images for '{game_name_found}'")
                                        
                                        # Look for fanart images using the mapped field names
                                        for image_data in images:
                                            if isinstance(image_data, dict):
                                                # Get the image type and filename from the dictionary
                                                image_type = image_data.get('Type', '')
                                                filename = image_data.get('FileName', '')
                                                
                                                print(f"🔧 DEBUG: Image type: '{image_type}', Filename: '{filename[:50]}...' if len(filename) > 50 else '{filename}'")
                                                
                                                # Check if this image type matches any fanart mapping
                                                if image_type in fanart_mappings and filename:
                                                    # Construct complete URL by prepending LaunchBox base URL
                                                    base_url = 'https://images.launchbox-app.com/'
                                                    full_url = base_url + filename
                                                    fanart_urls.append(full_url)
                                                    print(f"🔧 DEBUG: Added fanart URL for '{game_name_found}' - type: '{image_type}', URL: '{full_url}'")
                                        
                                        print(f"🔧 DEBUG: Total fanart URLs found for '{game_name_found}': {len(fanart_urls)}")
                                        
                                        # Only include games that have fanart
                                        if fanart_urls:
                                            all_launchbox_results.append({
                                                'scraper': 'launchbox',
                                                'game_name': game_name_found,
                                                'game_id': launchboxid,
                                                'similarity_score': 1.0,
                                                'fanart_urls': fanart_urls,
                                                'region': 'Unknown',
                                                'platform': platform_name
                                            })
                                            print(f"🔧 DEBUG: Added LaunchBox fanart result for '{game_name_found}' - {len(fanart_urls)} images")
                                        else:
                                            print(f"🔧 DEBUG: No fanart found for '{game_name_found}' (ID: {launchboxid})")
                            else:
                                # Use similarity search with no parens normalization
                                print(f"🔧 DEBUG: Performing similarity search for '{game_name}' on platform '{platform_name}'")
                                
                                if platform_name in partition_index_no_parens:
                                    platform_games = partition_index_no_parens[platform_name]
                                    
                                    # Calculate similarity for all games in this platform
                                    similarity_results = []
                                    for normalized_name, launchboxid in platform_games.items():
                                        similarity = calculate_similarity(normalized_no_parens, normalized_name)
                                        if similarity > 0.9:  # Only consider matches with >90% similarity
                                            similarity_results.append((similarity, launchboxid, normalized_name))
                                    
                                    # Sort by similarity score (highest first) and take top 5 per platform
                                    similarity_results.sort(key=lambda x: x[0], reverse=True)
                                    top_matches = similarity_results[:5]
                                    
                                    print(f"🔧 DEBUG: Found {len(top_matches)} similar games on platform '{platform_name}'")
                                    
                                    for similarity_score, launchboxid, matched_name in top_matches:
                                        # Convert to string for lookup in global metadata cache
                                        launchboxid_str = str(launchboxid)
                                        print(f"🔧 DEBUG: Similarity match - Score: {similarity_score:.2f}, ID: {launchboxid_str}, Name: '{matched_name}', Platform: {platform_name}")
                                        
                                        # Get full game data from global cache
                                        found_entry = None
                                        if launchboxid_str in global_metadata_cache:
                                            found_entry = global_metadata_cache[launchboxid_str]
                                            print(f"🔧 DEBUG: Found entry in global_metadata_cache for similarity match ID {launchboxid_str}")
                                        else:
                                            print(f"🔧 DEBUG: launchboxid {launchboxid_str} NOT found in global_metadata_cache for similarity match")
                                        
                                        if found_entry:
                                            entry = found_entry
                                            game_elem = entry.get('game')
                                            
                                            if game_elem:
                                                # Extract game data - handle dictionary format
                                                game_data = {}
                                                if isinstance(game_elem, dict):
                                                    game_data = game_elem
                                                
                                                game_name_found = game_data.get('Name', '')
                                                print(f"🔧 DEBUG: Processing similarity match game: '{game_name_found}' (ID: {launchboxid_str}, Score: {similarity_score:.2f})")
                                                
                                                # Check if this game has fanart using the images field and scrappers.json mapping
                                                fanart_urls = []
                                                
                                                # Get fanart mapping from scrappers.json
                                                fanart_mappings = scraper_config.get('image_type_mappings', {}).get('fanart', [])
                                                
                                                # Get images from the cache entry
                                                images = entry.get('images', [])
                                                
                                                # Look for fanart images using the mapped field names
                                                for image_data in images:
                                                    if isinstance(image_data, dict):
                                                        # Get the image type and filename from the dictionary
                                                        image_type = image_data.get('Type', '')
                                                        filename = image_data.get('FileName', '')
                                                        
                                                        # Check if this image type matches any fanart mapping
                                                        if image_type in fanart_mappings and filename:
                                                            # Construct complete URL by prepending LaunchBox base URL
                                                            base_url = 'https://images.launchbox-app.com/'
                                                            full_url = base_url + filename
                                                            fanart_urls.append(full_url)
                                                            print(f"🔧 DEBUG: Added similarity match fanart URL for '{game_name_found}' - type: '{image_type}', URL: '{full_url}'")
                                                
                                                # Only include games that have fanart
                                                if fanart_urls:
                                                    all_launchbox_results.append({
                                                        'scraper': 'launchbox',
                                                        'game_name': game_name_found,
                                                        'game_id': launchboxid_str,
                                                        'similarity_score': similarity_score,
                                                        'fanart_urls': fanart_urls,
                                                        'region': 'Unknown',
                                                        'platform': platform_name
                                                    })
                                                    print(f"🔧 DEBUG: Added LaunchBox similarity match fanart result for '{game_name_found}' - {len(fanart_urls)} images, score: {similarity_score:.2f}")
                                                else:
                                                    print(f"🔧 DEBUG: No fanart found for similarity match '{game_name_found}' (ID: {launchboxid_str})")
                                
                        except Exception as e:
                            print(f"🔧 DEBUG: Error searching LaunchBox platform {platform_name}: {e}")
                            continue
                    
                    # Sort all results by similarity score and take top 10
                    all_launchbox_results.sort(key=lambda x: x['similarity_score'], reverse=True)
                    all_fanart_results.extend(all_launchbox_results[:10])
                    print(f"🔧 DEBUG: Added {len(all_launchbox_results[:10])} LaunchBox fanart results (total found: {len(all_launchbox_results)})")
                    continue
                
            except Exception as e:
                print(f"🔧 DEBUG: Error searching {scraper_name}: {e}")
                import traceback
                print(f"🔧 DEBUG: Traceback: {traceback.format_exc()}")
                continue
        
        # Sort results by similarity score (highest first)
        all_fanart_results.sort(key=lambda x: x.get('similarity_score', 0.0), reverse=True)
        
        print(f"🔧 DEBUG: Found {len(all_fanart_results)} fanart results")
        
        return jsonify({
            'success': True,
            'results': all_fanart_results,
            'total_found': len(all_fanart_results)
        })
        
    except Exception as e:
        print(f"Error in fanart search: {e}")
        return jsonify({'error': f'Internal server error: {str(e)}'}), 500

def search_media_by_scraper(scraper_name, scraper_config, game_name, system_name, direct_match, media_type):
    """Common helper to search media by scraper for a given media_type ('fanart'|'marquee').
    Returns a list of standardized result dicts.
    """
    results = []

    try:
        if scraper_name == 'igdb':
            igdb_service = load_igdb_service()
            if not igdb_service:
                print(f"🔧 DEBUG: IGDB service not available")
                return results
            print(f"🔧 DEBUG: IGDB service loaded, searching for '{game_name}' with direct_match={direct_match}")

            from game_utils import normalize_game_name
            if direct_match:
                normalized_name = normalize_game_name(game_name, remove_paranthesis=True, remove_articles=True)
                print(f"🔧 DEBUG: IGDB normalized name: '{normalized_name}'")
                print(f"🔧 DEBUG: IGDB platform_index keys: {list(igdb_service.platform_index.keys())}")
                # platform_index structure: { platform_id -> { first_char -> { normalized_name -> id } } }
                for platform_id, platform_data in igdb_service.platform_index.items():
                    if not normalized_name:
                        continue
                    first_char = normalized_name[0].lower()
                    if first_char in platform_data:
                        partition_games = platform_data[first_char]
                        print(f"🔧 DEBUG: IGDB platform {platform_id}, first_char '{first_char}', partition_games keys: {list(partition_games.keys())[:5]}...")
                        if normalized_name in partition_games:
                            game_id = partition_games[normalized_name]
                            print(f"🔧 DEBUG: IGDB found game_id {game_id} for normalized name '{normalized_name}'")
                            if game_id in igdb_service.igdb_data:
                                game = igdb_service.igdb_data[game_id]
                                print(f"🔧 DEBUG: IGDB game data keys: {list(game.keys())}")
                                print(f"🔧 DEBUG: IGDB game has logos: {'logos' in game}")
                                if 'logos' in game:
                                    print(f"🔧 DEBUG: IGDB logos value: {game['logos']}")
                                if 'artworks' in game:
                                    print(f"🔧 DEBUG: IGDB artworks value: {game['artworks']}")
                                    if isinstance(game['artworks'], dict) and game['artworks']:
                                        first_artwork_id = next(iter(game['artworks'].keys()))
                                        print(f"🔧 DEBUG: IGDB first artwork: {first_artwork_id}")
                                    elif isinstance(game['artworks'], list) and game['artworks']:
                                        print(f"🔧 DEBUG: IGDB first artwork: {game['artworks'][0]}")
                                urls = []
                                seen_image_ids = set()  # Track seen image IDs to avoid duplicates
                                
                                if media_type == 'fanart':
                                    # For fanart, use artworks
                                    if 'artworks' in game and game['artworks']:
                                        if isinstance(game['artworks'], dict):
                                            # New format: dict with image_id as key
                                            for image_id in game['artworks'].keys():
                                                if image_id not in seen_image_ids:
                                                    seen_image_ids.add(image_id)
                                                    urls.append(normalize_igdb_url(image_id))
                                        elif isinstance(game['artworks'], list):
                                            # Old format: list of objects or strings
                                            for artwork in game['artworks']:
                                                if isinstance(artwork, dict):
                                                    image_id = artwork.get('id') or artwork.get('image_id')
                                                    if image_id and image_id not in seen_image_ids:
                                                        seen_image_ids.add(image_id)
                                                        urls.append(normalize_igdb_url(image_id))
                                                else:
                                                    # Fallback for old format (simple string)
                                                    if artwork and artwork not in seen_image_ids:
                                                        seen_image_ids.add(artwork)
                                                        urls.append(normalize_igdb_url(artwork))
                                else:  # marquee
                                    # For marquee, use logos field (not artworks)
                                    if 'logos' in game and game['logos']:
                                        if isinstance(game['logos'], dict):
                                            # New format: dict with image_id as key
                                            for image_id in game['logos'].keys():
                                                if image_id not in seen_image_ids:
                                                    seen_image_ids.add(image_id)
                                                    urls.append(normalize_igdb_url(image_id))
                                        elif isinstance(game['logos'], list):
                                            # Old format: list of objects or strings
                                            for logo in game['logos']:
                                                if isinstance(logo, dict):
                                                    image_id = logo.get('id') or logo.get('image_id')
                                                    if image_id and image_id not in seen_image_ids:
                                                        seen_image_ids.add(image_id)
                                                        urls.append(normalize_igdb_url(image_id))
                                                else:
                                                    # Fallback for old format (simple string)
                                                    if logo and logo not in seen_image_ids:
                                                        seen_image_ids.add(logo)
                                                        urls.append(normalize_igdb_url(logo))
                                if urls:
                                    platform_name = 'Unknown'
                                    if 'platform' in game and game['platform']:
                                        platform_name = game['platform'].get('name', 'Unknown')
                                    
                                    # Check if we already have this game in results to avoid duplicates
                                    game_id = game.get('id', '')
                                    existing_game = next((r for r in results if r.get('game_id') == game_id), None)
                                    
                                    if existing_game:
                                        # Merge URLs with existing game, avoiding duplicates
                                        existing_urls = existing_game.get(f'{media_type}_urls', [])
                                        existing_urls_set = set(existing_urls)
                                        new_urls = [url for url in urls if url not in existing_urls_set]
                                        existing_game[f'{media_type}_urls'].extend(new_urls)
                                        print(f"🔧 DEBUG: IGDB merged {len(new_urls)} additional {media_type} URLs for existing game '{game.get('name', '')}'")
                                    else:
                                        # Add new game to results
                                        results.append({
                                            'scraper': 'igdb',
                                            'game_name': game.get('name', ''),
                                            'game_id': game_id,
                                            'similarity_score': 1.0,
                                            f'{media_type}_urls': urls,
                                            'region': 'Unknown',
                                            'platform': platform_name
                                        })
                                        print(f"🔧 DEBUG: IGDB added {len(urls)} {media_type} URLs for game '{game.get('name', '')}'")
                                else:
                                    print(f"🔧 DEBUG: IGDB game '{game.get('name', '')}' found but no {media_type} URLs generated")
                            break
            else:
                # Similarity search across all platforms
                from game_utils import calculate_similarity
                similar_games = []
                for platform_id, platform_data in igdb_service.platform_index.items():
                    # Flatten normalized_name -> id
                    flat = []
                    for _, names_map in platform_data.items():
                        flat.extend(list(names_map.items()))
                    for normalized_name, gid in flat:
                        if gid in igdb_service.igdb_data:
                            game = igdb_service.igdb_data[gid]
                            similarity = calculate_similarity(game_name, game.get('name', ''))
                            if similarity > 0.9:
                                game = game.copy()
                                game['_similarity_score'] = similarity
                                similar_games.append(game)
                similar_games.sort(key=lambda x: x.get('_similarity_score', 0), reverse=True)
                for game in similar_games[:50]:
                    urls = []
                    seen_image_ids = set()  # Track seen image IDs to avoid duplicates
                    
                    if media_type == 'fanart':
                        # For fanart, use artworks
                        if 'artworks' in game and game['artworks']:
                            if isinstance(game['artworks'], dict):
                                # New format: dict with image_id as key
                                for image_id in game['artworks'].keys():
                                    if image_id not in seen_image_ids:
                                        seen_image_ids.add(image_id)
                                        urls.append(normalize_igdb_url(image_id))
                            elif isinstance(game['artworks'], list):
                                # Old format: list of objects or strings
                                for artwork in game['artworks']:
                                    if isinstance(artwork, dict):
                                        image_id = artwork.get('id') or artwork.get('image_id')
                                        if image_id and image_id not in seen_image_ids:
                                            seen_image_ids.add(image_id)
                                            urls.append(normalize_igdb_url(image_id))
                                    else:
                                        # Fallback for old format (simple string)
                                        if artwork and artwork not in seen_image_ids:
                                            seen_image_ids.add(artwork)
                                            urls.append(normalize_igdb_url(artwork))
                    else:  # marquee
                        # For marquee, use logos field (not artworks)
                        if 'logos' in game and game['logos']:
                            if isinstance(game['logos'], dict):
                                # New format: dict with image_id as key
                                for image_id in game['logos'].keys():
                                    if image_id not in seen_image_ids:
                                        seen_image_ids.add(image_id)
                                        urls.append(normalize_igdb_url(image_id))
                            elif isinstance(game['logos'], list):
                                # Old format: list of objects or strings
                                for logo in game['logos']:
                                    if isinstance(logo, dict):
                                        image_id = logo.get('id') or logo.get('image_id')
                                        if image_id and image_id not in seen_image_ids:
                                            seen_image_ids.add(image_id)
                                            urls.append(normalize_igdb_url(image_id))
                                    else:
                                        # Fallback for old format (simple string)
                                        if logo and logo not in seen_image_ids:
                                            seen_image_ids.add(logo)
                                            urls.append(normalize_igdb_url(logo))
                    if urls:
                        platform_name = 'Unknown'
                        if 'platform' in game and game['platform']:
                            platform_name = game['platform'].get('name', 'Unknown')
                        
                        # Check if we already have this game in results to avoid duplicates
                        game_id = game.get('id', '')
                        existing_game = next((r for r in results if r.get('game_id') == game_id), None)
                        
                        if existing_game:
                            # Merge URLs with existing game, avoiding duplicates
                            existing_urls = existing_game.get(f'{media_type}_urls', [])
                            existing_urls_set = set(existing_urls)
                            new_urls = [url for url in urls if url not in existing_urls_set]
                            existing_game[f'{media_type}_urls'].extend(new_urls)
                            print(f"🔧 DEBUG: IGDB similarity merged {len(new_urls)} additional {media_type} URLs for existing game '{game.get('name', '')}'")
                        else:
                            # Add new game to results
                            results.append({
                                'scraper': 'igdb',
                                'game_name': game.get('name', ''),
                                'game_id': game_id,
                                'similarity_score': game.get('_similarity_score', 0.0),
                                f'{media_type}_urls': urls,
                                'region': 'Unknown',
                                'platform': platform_name
                            })
                            print(f"🔧 DEBUG: IGDB similarity added {len(urls)} {media_type} URLs for game '{game.get('name', '')}'")

        elif scraper_name == 'steam':
            steam_service = load_steam_service()
            if not steam_service:
                return results
            if direct_match:
                games = steam_service.search_steam_apps(game_name, limit=50)
                for g in games:
                    g['similarity_score'] = 1.0
            else:
                games = steam_service.find_similarity_matches(game_name, [], limit=50)
            for g in games:
                similarity_score = g.get('similarity_score', 0.0)
                if similarity_score > 0.85:
                    steam_id = g.get('appid')
                    if steam_id:
                        if media_type == 'fanart':
                            url = f"https://shared.steamstatic.com/store_item_assets/steam/apps/{steam_id}/library_hero.jpg"
                        else:
                            url = f"https://cdn.akamai.steamstatic.com/steam/apps/{steam_id}/logo.png"
                        results.append({
                            'scraper': 'steam',
                            'game_name': g.get('name', ''),
                            'game_id': steam_id,
                            'similarity_score': similarity_score,
                            f'{media_type}_urls': [url],
                            'region': 'Unknown'
                        })

        elif scraper_name == 'steamgriddb':
            from steamgrid_service import SteamGridService
            sgdb_service = SteamGridService()
            api_key = sgdb_service.get_api_key()
            if not api_key:
                return results
            games = run_async_safely(sgdb_service.get_steamgrid_id_by_name(game_name, api_key=api_key, limit=50))
            # dedupe
            seen = set()
            unique_games = []
            for g in games:
                gid = g.get('id')
                if gid and gid not in seen:
                    seen.add(gid)
                    unique_games.append(g)
            media_key = 'heroes' if media_type == 'fanart' else 'logos'
            for g in unique_games:
                gid = g.get('id')
                if not gid:
                    continue
                media = run_async_safely(sgdb_service.get_steamgrid_media(gid, [media_key], api_key=api_key))
                if media and media_key in media and media[media_key]:
                    for item in media[media_key]:
                        url = item.get('url', '')
                        if url:
                            results.append({
                                'scraper': 'steamgriddb',
                                'game_name': g.get('name', ''),
                                'game_id': gid,
                                'similarity_score': 1.0,
                                f'{media_type}_urls': [url],
                                'region': 'Unknown'
                            })

        elif scraper_name == 'screenscraper':
            from screenscraper_service import ScreenScraperService
            from credential_manager import credential_manager
            config = load_config()
            screenscraper_creds = credential_manager.get_screenscraper_credentials()
            scrappers_config = load_scrappers_config()
            systems_config = load_systems_config()
            ss_service = ScreenScraperService(config, screenscraper_creds, scrappers_config, systems_config)
            search_results = run_async_safely(ss_service.search_games_by_name(game_name, system_name, limit=10, search_all_systems=True))
            to_fetch = []
            for g in search_results:
                gid = g.get('jeu_id')
                if gid:
                    to_fetch.append((gid, g))
            if to_fetch:
                import asyncio
                async def fetch_all():
                    tasks = [ss_service.get_game_by_id(gid, system_name) for gid, _ in to_fetch]
                    return await asyncio.gather(*tasks, return_exceptions=True)
                full_data = run_async_safely(fetch_all())
                for i, (_, og) in enumerate(to_fetch):
                    if i >= len(full_data):
                        continue
                    fd = full_data[i]
                    if isinstance(fd, Exception) or not fd:
                        continue
                    urls = []
                    if 'medias' in fd and fd['medias']:
                        for media in fd['medias']:
                            if not isinstance(media, dict):
                                continue
                            if media_type == 'fanart' and media.get('type') == 'fanart' and media.get('url'):
                                urls.append(media['url'])
                            if media_type == 'marquee' and media.get('type') == 'wheel' and media.get('url'):
                                urls.append(media['url'])
                    if urls:
                        results.append({
                            'scraper': 'screenscraper',
                            'game_name': og.get('name', ''),
                            'game_id': og.get('jeu_id', ''),
                            'similarity_score': og.get('_similarity_score', 0.0),
                            f'{media_type}_urls': urls,
                            'region': 'Unknown',
                            'platform': system_name
                        })

        elif scraper_name == 'launchbox':
            # Use partitioned index (no parens) and global cache
            all_lb = []
            partition_index, partition_index_no_parens = load_launchbox_partitioned_indexes()
            if not partition_index_no_parens:
                return results
            from game_utils import normalize_game_name, calculate_similarity
            normalized_no_parens = normalize_game_name(game_name, remove_paranthesis=True, remove_articles=True)
            global global_metadata_cache, global_metadata_cache_loaded
            if not global_metadata_cache_loaded or not global_metadata_cache:
                return results
            for platform_name in partition_index_no_parens.keys():
                try:
                    if direct_match:
                        launchboxid = None
                        if normalized_no_parens and platform_name in partition_index_no_parens:
                            launchboxid = partition_index_no_parens[platform_name].get(normalized_no_parens)
                        if launchboxid:
                            launchboxid_str = str(launchboxid)
                            entry = global_metadata_cache.get(launchboxid_str)
                            game_elem = entry.get('game') if entry else None
                            if entry and game_elem:
                                # Extract images via mapping
                                image_mappings = scraper_config.get('image_type_mappings', {}).get(media_type, [])
                                images = entry.get('images', [])
                                urls = []
                                for img in images:
                                    if not isinstance(img, dict):
                                        continue
                                    if img.get('Type', '') in image_mappings and img.get('FileName', ''):
                                        urls.append(f"https://images.launchbox-app.com/{img['FileName']}")
                                if urls:
                                    all_lb.append({
                                        'scraper': 'launchbox',
                                        'game_name': (game_elem.get('Name') if isinstance(game_elem, dict) else ''),
                                        'game_id': launchboxid,
                                        'similarity_score': 1.0,
                                        f'{media_type}_urls': urls,
                                        'region': 'Unknown',
                                        'platform': platform_name
                                    })
                    else:
                        platform_games = partition_index_no_parens.get(platform_name, {})
                        if platform_games:
                            sim_list = []
                            for norm_name, lbid in platform_games.items():
                                sim = calculate_similarity(normalized_no_parens, norm_name)
                                if sim > 0.9:
                                    sim_list.append((sim, lbid, norm_name))
                            sim_list.sort(key=lambda x: x[0], reverse=True)
                            for sim, lbid, norm in sim_list[:5]:
                                entry = global_metadata_cache.get(str(lbid))
                                if not entry:
                                    continue
                                game_elem = entry.get('game')
                                image_mappings = scraper_config.get('image_type_mappings', {}).get(media_type, [])
                                images = entry.get('images', [])
                                urls = []
                                for img in images:
                                    if not isinstance(img, dict):
                                        continue
                                    if img.get('Type', '') in image_mappings and img.get('FileName', ''):
                                        urls.append(f"https://images.launchbox-app.com/{img['FileName']}")
                                if urls:
                                    all_lb.append({
                                        'scraper': 'launchbox',
                                        'game_name': (game_elem.get('Name') if isinstance(game_elem, dict) else ''),
                                        'game_id': lbid,
                                        'similarity_score': sim,
                                        f'{media_type}_urls': urls,
                                        'region': 'Unknown',
                                        'platform': platform_name
                                    })
                except Exception:
                    continue
            results.extend(all_lb)

    except Exception as e:
        print(f"🔧 DEBUG: Error in search_media_by_scraper for {scraper_name}: {e}")
        import traceback
        print(f"🔧 DEBUG: Traceback: {traceback.format_exc()}")
        return results

    return results

