@app.route('/api/cache/refresh-steam', methods=['POST'])
@login_required
def refresh_steam_cache_endpoint():
    """Refresh Steam cache by downloading latest data and rebuilding partitioned index"""
    try:
        from steam_service import SteamService
        import asyncio
        
        # Create a new Steam service instance
        steam_service = SteamService()
        
        print("🔄 Refreshing Steam cache - downloading latest data...")
        
        # Force download the latest Steam app index from API
        apps = asyncio.run(steam_service.fetch_app_index())
        
        if not apps:
            return jsonify({'error': 'Failed to download Steam app data from API'}), 500
        
        # Save the fresh data to cache
        steam_service.save_app_index(apps)
        print(f"✅ Downloaded {len(apps)} Steam apps from API")
        
        # Build partitioned index from the fresh data
        print("🔧 Building partitioned index from fresh Steam data...")
        steam_service._build_partitioned_index(apps)
        steam_service._save_partitioned_index_to_cache()
        
        # Update the global Steam service instance with the new partitioned index
        global global_steam_service
        if global_steam_service is not None:
            print("🔄 Updating global Steam service with new partitioned index...")
            global_steam_service._partitioned_index = steam_service._partitioned_index
            global_steam_service._partitioned_index_loaded_from_cache = True
            print("✅ Global Steam service updated with new partitioned index")
        
        return jsonify({
            'success': True,
            'message': f'Steam cache refreshed successfully - downloaded {len(apps)} apps and rebuilt partitioned index'
        })
        
    except Exception as e:
        return jsonify({'error': f'Failed to refresh Steam cache: {str(e)}'}), 500

@app.route('/api/cache/update-metadata', methods=['POST'])
@login_required
def update_metadata_endpoint():
    """Update metadata.xml to the latest version from Launchbox"""
    try:
        import zipfile
        import tempfile
        
        # Get absolute path and ensure directory exists
        metadata_path = get_launchbox_metadata_path()
        metadata_dir = os.path.dirname(metadata_path)
        
        os.makedirs(metadata_dir, exist_ok=True)
        
        # Download the latest metadata
        metadata_url = 'http://gamesdb.launchbox-app.com/Metadata.zip'
        
        # Create temporary directory for download
        with tempfile.TemporaryDirectory() as temp_dir:
            zip_path = os.path.join(temp_dir, 'Metadata.zip')
            
            # Download the zip file
            response = requests.get(metadata_url, stream=True)
            response.raise_for_status()
            
            with open(zip_path, 'wb') as f:
                for chunk in response.iter_content(chunk_size=8192):
                    f.write(chunk)
            
            # Extract the zip file
            with zipfile.ZipFile(zip_path, 'r') as zip_ref:
                print(f"DEBUG: Zip contents: {zip_ref.namelist()}")
                zip_ref.extractall(temp_dir)
                print(f"DEBUG: Extracted files in temp_dir: {os.listdir(temp_dir)}")
            
            # Look specifically for Metadata.xml file
            metadata_xml_path = os.path.join(temp_dir, 'Metadata.xml')
            if not os.path.exists(metadata_xml_path):
                # Fallback: look for any XML file if Metadata.xml not found
                metadata_files = [f for f in os.listdir(temp_dir) if f.endswith('.xml')]
                if not metadata_files:
                    return jsonify({'error': 'No Metadata.xml or XML file found in downloaded zip'}), 400
                extracted_metadata = os.path.join(temp_dir, metadata_files[0])
                print(f"DEBUG: Using fallback XML file: {metadata_files[0]}")
            else:
                extracted_metadata = metadata_xml_path
                print(f"DEBUG: Found Metadata.xml file")
            
            # Backup existing metadata if it exists
            if os.path.exists(metadata_path):
                backup_path = f"{metadata_path}.backup.{int(time.time())}"
                shutil.copy2(metadata_path, backup_path)
                # Clean up old backups, keeping only the last 10
                cleanup_old_backups(metadata_path, max_backups=10)
            
            # Copy the new metadata file
            shutil.copy2(extracted_metadata, metadata_path)
            
            # Clear all LaunchBox-related caches since metadata was updated
            flush_launchbox_caches()
            
            # Reload the global metadata cache with new metadata
            print("🔄 Reloading global metadata cache with new metadata...")
            load_metadata_cache()
            
            # Regenerate LaunchBox partitioned indexes with new metadata
            print("🔄 Regenerating LaunchBox partitioned indexes after metadata update...")
            load_launchbox_partitioned_indexes()
            
            return jsonify({
                'success': True,
                'message': 'Metadata.xml updated successfully and LaunchBox partitioned indexes regenerated',
                'backup_created': os.path.exists(backup_path) if 'backup_path' in locals() else False
            })
            
    except Exception as e:
        app.logger.error(f'Error updating metadata: {str(e)}')
        return jsonify({'error': f'Failed to update metadata: {str(e)}'}), 500

@app.route('/api/delete-file', methods=['POST'])
@login_required
def delete_file():
    """Delete a file from the filesystem"""
    app.logger.info(f'Delete file endpoint called with data: {request.get_json()}')
    try:
        data = request.get_json()
        if not data or 'file_path' not in data:
            return jsonify({'error': 'file_path is required'}), 400
        
        file_path = data['file_path']
        
        # Convert relative path to absolute path relative to app root
        if not os.path.isabs(file_path):
            file_path = os.path.join(app.root_path, file_path)
        
        # Security check: ensure the file path is within the allowed directories
        allowed_dirs = [
            os.path.abspath(os.path.join(app.root_path, 'roms')),
            os.path.abspath(os.path.join(app.root_path, 'media'))
        ]
        
        file_abs_path = os.path.abspath(file_path)
        is_allowed = False
        
        for allowed_dir in allowed_dirs:
            if file_abs_path.startswith(allowed_dir):
                is_allowed = True
                break
        
        if not is_allowed:
            return jsonify({'error': 'Access denied: file path not in allowed directories'}), 403
        
        # Check if file exists using the absolute path
        if not os.path.exists(file_abs_path):
            return jsonify({'error': f'File not found: {file_abs_path}'}), 404
        
        # Delete the file using the absolute path
        os.remove(file_abs_path)
        
        # Log the deletion
        app.logger.info(f'Deleted file: {file_abs_path}')
        
        return jsonify({'success': True, 'message': f'File deleted: {file_abs_path}'})
        
    except Exception as e:
        app.logger.error(f'Error deleting file: {str(e)}')
        return jsonify({'error': f'Failed to delete file: {str(e)}'}), 500

@app.route('/api/delete-files', methods=['POST'])
@login_required
def delete_files_batch():
    """Delete multiple files from the filesystem in a single request"""
    app.logger.info(f'Delete files batch endpoint called with data: {request.get_json()}')
    try:
        data = request.get_json()
        if not data or 'file_paths' not in data:
            return jsonify({'error': 'file_paths is required'}), 400
        
        file_paths = data['file_paths']
        if not isinstance(file_paths, list):
            return jsonify({'error': 'file_paths must be a list'}), 400
        
        if not file_paths:
            return jsonify({'error': 'file_paths cannot be empty'}), 400
        
        # Security check: ensure all file paths are within allowed directories
        allowed_dirs = [
            os.path.abspath(os.path.join(app.root_path, 'roms')),
            os.path.abspath(os.path.join(app.root_path, 'media'))
        ]
        
        deleted_files = []
        failed_deletions = []
        
        for file_path in file_paths:
            try:
                # Convert relative path to absolute path relative to app root
                if not os.path.isabs(file_path):
                    file_path = os.path.join(app.root_path, file_path)
                
                file_abs_path = os.path.abspath(file_path)
                is_allowed = False
                
                for allowed_dir in allowed_dirs:
                    if file_abs_path.startswith(allowed_dir):
                        is_allowed = True
                        break
                
                if not is_allowed:
                    failed_deletions.append({'file_path': file_path, 'error': 'Access denied: file path not in allowed directories'})
                    continue
                
                # Check if file exists using the absolute path
                if not os.path.exists(file_abs_path):
                    failed_deletions.append({'file_path': file_path, 'error': f'File not found: {file_abs_path}'})
                    continue
                
                # Delete the file using the absolute path
                os.remove(file_abs_path)
                deleted_files.append(file_abs_path)
                
                # Log the deletion
                app.logger.info(f'Deleted file: {file_abs_path}')
                
            except Exception as e:
                failed_deletions.append({'file_path': file_path, 'error': f'Failed to delete: {str(e)}'})
                app.logger.error(f'Error deleting file {file_path}: {str(e)}')
        
        # Return results
        result = {
            'success': len(failed_deletions) == 0,
            'deleted_count': len(deleted_files),
            'failed_count': len(failed_deletions),
            'deleted_files': deleted_files
        }
        
        if failed_deletions:
            result['failed_deletions'] = failed_deletions
        
        if len(failed_deletions) == 0:
            return jsonify(result)
        else:
            return jsonify(result), 207  # Multi-status response
        
    except Exception as e:
        app.logger.error(f'Error in batch delete: {str(e)}')
        return jsonify({'error': f'Failed to delete files: {str(e)}'}), 500



@app.route('/api/rom-system/<system_name>/game/upload-media', methods=['POST'])
@login_required
def upload_game_media(system_name):
    """Upload a media file for a specific game"""
    try:
        # Check if system exists
        system_path = os.path.join(ROMS_FOLDER, system_name)
        if not os.path.exists(system_path):
            return jsonify({'error': 'System not found'}), 404
        
        # Check if game exists in gamelist (use var/gamelists, not roms)
        gamelist_path = get_gamelist_path(system_name)
        if not os.path.exists(gamelist_path):
            return jsonify({'error': 'Gamelist not found'}), 404
        
        # Parse gamelist to find the game
        games = parse_gamelist_xml(gamelist_path)
        
        # Get ROM path from form data
        rom_path = request.form.get('rom_path')
        if not rom_path:
            return jsonify({'error': 'ROM path not provided'}), 400
        
        # Find game by ROM path
        game = next((g for g in games if g.get('path') == rom_path), None)
        if not game:
            return jsonify({'error': f'Game not found with ROM path: {rom_path}'}), 404
        
        # Check if file was uploaded
        if 'media_file' not in request.files:
            return jsonify({'error': 'No file uploaded'}), 400
        
        file = request.files['media_file']
        if file.filename == '':
            return jsonify({'error': 'No file selected'}), 400
        
        # Get media field from form data
        media_field = request.form.get('media_field')
        if not media_field:
            return jsonify({'error': 'Media field not specified'}), 400
        
        # Load media config to get media mappings
        media_config = load_media_config()
        
        # Find the media directory for this field
        media_directory = get_media_directory(media_field)
        
        if not media_directory:
            return jsonify({'error': f'No media mapping found for field: {media_field}. Available fields: {list(media_config.get("media_fields", {}).keys())}'}), 400
        
        # Get the ROM filename without extension for use as media filename
        rom_path = game.get('path', '')
        rom_filename = os.path.splitext(os.path.basename(rom_path))[0] if rom_path else game.get('name', 'unknown')
        
        # Create category-specific media directory using the mapped directory name
        category_dir = os.path.join(system_path, 'media', media_directory)
        if not os.path.exists(category_dir):
            os.makedirs(category_dir)
        
        # Generate filename using ROM name and original extension
        file_extension = os.path.splitext(file.filename)[1].lower()
        new_filename = create_media_filename(rom_path, file_extension)
        file_path = os.path.join(category_dir, new_filename)
        
        # Remove existing file if it exists (replace instead of creating _1 suffix)
        if os.path.exists(file_path):
            try:
                os.remove(file_path)
                print(f"🗑️ Removed existing media file: {new_filename}")
            except Exception as e:
                print(f"⚠️ Warning: Could not remove existing file {file_path}: {e}")
        
        # Save the uploaded file
        file.save(file_path)
        
        # Convert image if field has target_extension configured
        from game_utils import should_convert_field, convert_image_replace, needs_conversion
        should_convert, target_extension = should_convert_field(media_field, config)
        
        if should_convert and needs_conversion(file_path, target_extension):
            new_path, status = convert_image_replace(file_path, target_extension)
            if status == "converted":
                # Conversion successful, update paths and filename
                file_path = new_path
                new_filename = os.path.basename(file_path)
                print(f"✅ Converted uploaded image to {target_extension}: {new_filename}")
            elif status == "already_target":
                # File was already in target format, no conversion needed
                print(f"✅ Uploaded image already {target_extension} format: {new_filename}")
            else:
                # Conversion failed
                print(f"⚠️ Failed to convert uploaded image to {target_extension}, keeping original: {new_filename}")
        elif should_convert:
            # Field should be converted but file is already in target format
            print(f"✅ Uploaded image already {target_extension} format: {new_filename}")
        else:
            # No conversion needed for this field
            print(f"✅ No conversion needed for uploaded field: {media_field}")
        
        # Update the game object in memory with relative path
        relative_path = f"./media/{media_directory}/{new_filename}"
        game[media_field] = relative_path
        
        # Update the gamelist.xml file
        write_gamelist_xml(games, gamelist_path)
        
        # Notify all connected clients about the gamelist update
        notify_gamelist_updated(system_name, len(games))
        notify_game_updated(system_name, game.get('path', ''), [media_field])
        
        # Log the upload
        app.logger.info(f'Uploaded media file: {file_path} for game {rom_path} field {media_field}')
        
        return jsonify({
            'success': True,
            'message': f'Media uploaded successfully for {media_field}',
            'media_path': relative_path,
            'filename': new_filename
        })
        
    except Exception as e:
        app.logger.error(f'Error uploading media: {str(e)}')
        return jsonify({'error': f'Failed to upload media: {str(e)}'}), 500

@app.route('/api/extract-first-frame', methods=['POST'])
@login_required
def extract_first_frame():
    """Extract first frame from video for manual cropping"""
    try:
        data = request.get_json()
        video_path = data.get('video_path')
        
        if not video_path:
            return jsonify({'error': 'Video path is required'}), 400
        
        # Convert web path to file system path if needed
        if video_path.startswith('/roms/'):
            # Convert /roms/system/path to actual file system path
            video_path = os.path.join(ROMS_FOLDER, video_path[6:])  # Remove '/roms/' prefix
        
        print(f"Extracting frame from video path: {video_path}")
        
        # Check if video file exists
        if not os.path.exists(video_path):
            return jsonify({'error': f'Video file not found: {video_path}'}), 404
        
        # Create frames directory if it doesn't exist
        frames_dir = os.path.join(os.path.dirname(video_path), 'frames')
        os.makedirs(frames_dir, exist_ok=True)
        
        # Generate frame filename
        video_basename = os.path.splitext(os.path.basename(video_path))[0]
        frame_filename = f"{video_basename}_frame.jpg"
        frame_path = os.path.join(frames_dir, frame_filename)
        
        # Extract first frame using ffmpeg
        cmd = [
            'ffmpeg',
            '-i', video_path,
            '-vframes', '1',
            '-q:v', '2',  # High quality
            '-y',  # Overwrite output file
            frame_path
        ]
        
        result = subprocess.run(cmd, capture_output=True, text=True, timeout=30)
        
        if result.returncode != 0:
            return jsonify({'error': f'Failed to extract frame: {result.stderr}'}), 500
        
        if not os.path.exists(frame_path):
            return jsonify({'error': 'Frame extraction failed - no output file'}), 500
        
        # Return relative path for web access
        relative_frame_path = os.path.relpath(frame_path, ROMS_FOLDER)
        
        return jsonify({
            'success': True,
            'frame_path': relative_frame_path
        })
        
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Frame extraction timed out'}), 500
    except Exception as e:
        print(f"Error extracting first frame: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({'error': str(e)}), 500

