@app.route('/api/apply-manual-crop', methods=['POST'])
@login_required
def apply_manual_crop():
    """Apply manual crop to video"""
    try:
        data = request.get_json()
        video_path = data.get('video_path')
        crop_dimensions = data.get('crop_dimensions')
        game_id = data.get('game_id')
        system_name = data.get('system_name')
        rom_file = data.get('rom_file')
        
        # Debug: Log received parameters
        print(f"Manual crop API received data: {data}")
        print(f"video_path: {video_path}")
        print(f"crop_dimensions: {crop_dimensions}")
        print(f"game_id: {game_id}")
        print(f"system_name: {system_name}")
        print(f"rom_file: {rom_file}")
        
        if not all([video_path, crop_dimensions, game_id, system_name, rom_file]):
            missing_params = []
            if not video_path: missing_params.append('video_path')
            if not crop_dimensions: missing_params.append('crop_dimensions')
            if not game_id: missing_params.append('game_id')
            if not system_name: missing_params.append('system_name')
            if not rom_file: missing_params.append('rom_file')
            return jsonify({'error': f'Missing required parameters: {missing_params}'}), 400
        
        # Convert web path to file system path if needed
        if video_path.startswith('/roms/'):
            # Convert /roms/system/path to actual file system path
            video_path = os.path.join(ROMS_FOLDER, video_path[6:])  # Remove '/roms/' prefix
        
        print(f"Applying manual crop to video path: {video_path}")
        
        # Check if video file exists
        if not os.path.exists(video_path):
            return jsonify({'error': f'Video file not found: {video_path}'}), 404
        
        # Create and start the crop task
        task_data = {
            'video_path': video_path,
            'crop_dimensions': crop_dimensions,
            'game_id': game_id,
            'system_name': system_name,
            'rom_file': rom_file
        }
        
        task = create_task('manual_crop', task_data)
        current_task_id = task.id
        task.start()
        
        # Start manual crop in background thread
        thread = threading.Thread(target=run_manual_crop_task, args=(task.id, task_data))
        thread.daemon = True
        thread.start()
        
        return jsonify({
            'success': True,
            'message': 'Manual crop started',
            'task_id': task.id,
            'status': 'running'
        })
        
    except Exception as e:
        print(f"Manual crop error: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({'error': str(e)}), 500

@app.route('/api/rom-system/<system_name>/game/delete-media', methods=['POST'])
@login_required
def delete_game_media(system_name):
    """Delete a media file for a specific game"""
    try:
        # Check if system exists
        system_path = os.path.join(ROMS_FOLDER, system_name)
        if not os.path.exists(system_path):
            return jsonify({'error': 'System not found'}), 404
        
        # Check if game exists in gamelist (use var/gamelists, not roms)
        gamelist_path = get_gamelist_path(system_name)
        if not os.path.exists(gamelist_path):
            return jsonify({'error': 'Gamelist not found'}), 404
        
        # Get request data first
        data = request.get_json()
        if not data:
            return jsonify({'error': 'No JSON data provided'}), 400
        
        # Parse gamelist to find the game
        games = parse_gamelist_xml(gamelist_path)
        
        # Use ROM path as primary identifier (more reliable than ID)
        rom_path = data.get('rom_path')
        if not rom_path:
            return jsonify({'error': 'ROM path not provided'}), 400
        
        # Find game by ROM path
        game = next((g for g in games if g.get('path') == rom_path), None)
        if not game:
            return jsonify({'error': f'Game not found with ROM path: {rom_path}'}), 404
        
        media_field = data.get('media_field')
        if not media_field:
            return jsonify({'error': 'Media field not specified'}), 400
        
        # Check if the media field exists for this game
        if media_field not in game or not game[media_field]:
            return jsonify({'error': f'No {media_field} media found for this game'}), 404
        
        # Get the current media path
        media_path = game[media_field]
        
        # Construct full path to the media file
        full_media_path = os.path.join(system_path, media_path)
        
        # Delete the physical file if it exists
        if os.path.exists(full_media_path):
            try:
                os.remove(full_media_path)
                app.logger.info(f'Deleted media file: {full_media_path}')
            except Exception as e:
                app.logger.warning(f'Could not delete physical file {full_media_path}: {str(e)}')
        
        # Clear the media field in the game object
        game[media_field] = ''
        
        # Update the gamelist.xml file
        write_gamelist_xml(games, gamelist_path)
        
        # Notify all connected clients about the gamelist update
        notify_gamelist_updated(system_name, len(games))
        notify_game_updated(system_name, game.get('path', ''), [media_field])
        
        # Log the deletion
        app.logger.info(f'Deleted media field {media_field} for game {rom_path}')
        
        return jsonify({
            'success': True,
            'message': f'Media deleted successfully for {media_field}'
        })
        
    except Exception as e:
        app.logger.error(f'Error deleting media: {str(e)}')
        return jsonify({'error': f'Failed to delete media: {str(e)}'}), 500
@app.route('/api/rom-system/<system_name>/game/delete-media-batch', methods=['POST'])
@login_required
def delete_game_media_batch(system_name):
    """Delete multiple media files for a specific game in one operation"""
    try:
        # Check if system exists
        system_path = os.path.join(ROMS_FOLDER, system_name)
        if not os.path.exists(system_path):
            return jsonify({'error': 'System not found'}), 404
        
        # Check if game exists in gamelist (use var/gamelists, not roms)
        gamelist_path = get_gamelist_path(system_name)
        if not os.path.exists(gamelist_path):
            return jsonify({'error': 'Gamelist not found'}), 404
        
        # Get request data
        data = request.get_json()
        if not data:
            return jsonify({'error': 'No JSON data provided'}), 400
        
        # Parse gamelist to find the game
        games = parse_gamelist_xml(gamelist_path)
        
        # Use ROM path as primary identifier
        rom_path = data.get('rom_path')
        if not rom_path:
            return jsonify({'error': 'ROM path not provided'}), 400
        
        # Find game by ROM path
        game = next((g for g in games if g.get('path') == rom_path), None)
        if not game:
            return jsonify({'error': f'Game not found with ROM path: {rom_path}'}), 404
        
        # Get media fields to delete
        media_fields = data.get('media_fields', [])
        if not media_fields:
            return jsonify({'error': 'No media fields specified'}), 400
        
        # Process each media field
        deleted_fields = []
        failed_fields = []
        
        for media_field in media_fields:
            # Check if the media field exists for this game
            if media_field not in game or not game[media_field]:
                failed_fields.append(f'{media_field}: No media found')
                continue
            
            # Get the current media path
            media_path = game[media_field]
            
            # Construct full path to the media file
            full_media_path = os.path.join(system_path, media_path)
            
            # Delete the physical file if it exists
            if os.path.exists(full_media_path):
                try:
                    os.remove(full_media_path)
                    app.logger.info(f'Deleted media file: {full_media_path}')
                except Exception as e:
                    app.logger.warning(f'Could not delete physical file {full_media_path}: {str(e)}')
                    failed_fields.append(f'{media_field}: Could not delete file')
                    continue
            
            # Clear the media field in the game object
            game[media_field] = ''
            deleted_fields.append(media_field)
        
        # Update the gamelist.xml file only once after all deletions
        write_gamelist_xml(games, gamelist_path)
        
        # Notify all connected clients about the gamelist update
        notify_gamelist_updated(system_name, len(games))
        notify_game_updated(system_name, game.get('path', ''), deleted_fields)
        
        # Log the deletion
        app.logger.info(f'Deleted media fields {deleted_fields} for game {rom_path}')
        
        return jsonify({
            'success': True,
            'message': f'Media deleted successfully for {len(deleted_fields)} fields',
            'deleted_fields': deleted_fields,
            'failed_fields': failed_fields
        })
        
    except Exception as e:
        app.logger.error(f'Error deleting media batch: {str(e)}')
        return jsonify({'error': f'Failed to delete media batch: {str(e)}'}), 500

@app.route('/api/rom-system/<system_name>/game/manual-scrap', methods=['POST'])
@login_required
def manual_scrap_game(system_name):
    """Manually scrape a single game from all available sources"""
    try:
        # Check if system exists
        system_path = os.path.join(ROMS_FOLDER, system_name)
        if not os.path.exists(system_path):
            return jsonify({'error': 'System not found'}), 404
        
        # Get request data
        data = request.get_json()
        if not data:
            return jsonify({'error': 'No JSON data provided'}), 400
        
        rom_path = data.get('rom_path')
        if not rom_path:
            return jsonify({'error': 'ROM path is required'}), 400
        
        # Get current game data from gamelist
        gamelist_path = get_gamelist_path(system_name)
        if not os.path.exists(gamelist_path):
            return jsonify({'error': 'Gamelist not found'}), 404
        
        games = parse_gamelist_xml(gamelist_path)
        current_game = None
        
        # Debug: Print all game paths to see what we're working with
        print(f"DEBUG: Looking for rom_path: '{rom_path}'")
        print(f"DEBUG: Available game paths:")
        for i, game in enumerate(games[:5]):  # Show first 5 games
            print(f"  {i}: '{game.get('path')}'")
        
        # Try exact match first
        for game in games:
            if game.get('path') == rom_path:
                current_game = game
                break
        
        # If no exact match, try to find by filename
        if not current_game:
            rom_filename = os.path.basename(rom_path)
            print(f"DEBUG: No exact match, trying to find by filename: '{rom_filename}'")
            for game in games:
                game_filename = os.path.basename(game.get('path', ''))
                if game_filename == rom_filename:
                    current_game = game
                    print(f"DEBUG: Found game by filename: '{game.get('path')}'")
                    break
        
        if not current_game:
            return jsonify({'error': f'Game not found in gamelist. Looking for: {rom_path}'}), 404
        
        # Debug: Print current game data
        print(f"DEBUG: Current game data: {current_game}")
        
        # Initialize results structure
        # Text fields are fixed set
        scrap_results = {
            'text_fields': {
                'name': {'current': current_game.get('name', ''), 'sources': {}},
                'desc': {'current': current_game.get('desc', ''), 'sources': {}},
                'developer': {'current': current_game.get('developer', ''), 'sources': {}},
                'publisher': {'current': current_game.get('publisher', ''), 'sources': {}},
                'genre': {'current': current_game.get('genre', ''), 'sources': {}},
                'releasedate': {'current': current_game.get('releasedate', ''), 'sources': {}}
            },
            'media_fields': {}
        }
        
        # Get system configuration and media fields mapping
        config = load_config()
        systems_config = load_systems_config()
        system_config = systems_config.get(system_name, {})
        # Initialize media_fields for ALL configured media fields
        for media_field_name in config.get('media_fields', {}).keys():
            scrap_results['media_fields'][media_field_name] = {
                'current': current_game.get(media_field_name, ''),
                'sources': {}
            }
        
        # Debug: Print system config and game IDs
        print(f"DEBUG: System config: {system_config}")
        print(f"DEBUG: Game has screenscraperid: {current_game.get('screenscraperid')}")
        print(f"DEBUG: Game has launchboxid: {current_game.get('launchboxid')}")
        print(f"DEBUG: Game has igdbid: {current_game.get('igdbid')}")
        
        # Scrape from each available source
        import asyncio
        
        def scrape_all_sources(sys_config):
            import time
            import threading
            from datetime import datetime
            from concurrent.futures import ThreadPoolExecutor, as_completed
            
            # Create list of scraper tasks to run in parallel
            scraper_tasks = []
            
            # IGDB scraping - only if game has IGDB ID
            if sys_config.get('igdb') and current_game.get('igdbid'):
                scraper_tasks.append(('igdb', lambda: asyncio.run(scrape_igdb_manual(current_game, system_name, sys_config))))
            
            # Steam scraping
            if current_game.get('steamid'):
                scraper_tasks.append(('steam', lambda: asyncio.run(scrape_steam_manual(current_game, system_name))))
            
            # ScreenScraper scraping
            if sys_config.get('screenscraper') and current_game.get('screenscraperid'):
                print(f"DEBUG: Adding ScreenScraper scraper for game: {current_game.get('name')} with ID: {current_game.get('screenscraperid')}")
                scraper_tasks.append(('screenscraper', lambda: asyncio.run(scrape_screenscraper_manual(current_game, system_name, sys_config))))
            else:
                print(f"DEBUG: ScreenScraper not enabled or no ID found. Config: {sys_config.get('screenscraper')}, Game ID: {current_game.get('screenscraperid')}")
            
            # SteamGridDB scraping (support steamgridid or steamid)
            if current_game.get('steamgridid') or current_game.get('steamid'):
                scraper_tasks.append(('steamgriddb', lambda: asyncio.run(scrape_steamgriddb_manual(current_game, system_name))))
            
            # LaunchBox scraping
            if current_game.get('launchboxid'):
                print(f"DEBUG: Adding LaunchBox scraper for game: {current_game.get('name')} with ID: {current_game.get('launchboxid')}")
                scraper_tasks.append(('launchbox', lambda: asyncio.run(scrape_launchbox_manual(current_game, system_name))))
            else:
                print(f"DEBUG: No LaunchBox ID found for game: {current_game.get('name')}")
            
            # MobyGames scraping
            if sys_config.get('mobygames') and current_game.get('mobygamesid'):
                print(f"DEBUG: Adding MobyGames scraper for game: {current_game.get('name')} with ID: {current_game.get('mobygamesid')}")
                scraper_tasks.append(('mobygames', lambda: asyncio.run(scrape_mobygames_manual(current_game, system_name, sys_config))))
            else:
                print(f"DEBUG: MobyGames not enabled or no ID found. Config: {sys_config.get('mobygames')}, Game ID: {current_game.get('mobygamesid')}")
            
            # Run all scrapers in parallel using ThreadPoolExecutor
            if scraper_tasks:
                print(f"🚀 MANUAL SCRAP: Starting {len(scraper_tasks)} scrapers in parallel threads at {datetime.now().strftime('%H:%M:%S.%f')[:-3]}")
                
                # Log each scraper start time
                start_times = {}
                for scraper_name, _ in scraper_tasks:
                    start_times[scraper_name] = time.time()
                    print(f"⏰ MANUAL SCRAP: {scraper_name.upper()} scraper STARTED at {datetime.now().strftime('%H:%M:%S.%f')[:-3]}")
                
                # Execute all scrapers in parallel using ThreadPoolExecutor
                parallel_start = time.time()
                results = {}
                
                def run_scraper(scraper_name, scraper_func):
                    try:
                        result = scraper_func()
                        completion_time = time.time()
                        duration = completion_time - start_times[scraper_name]
                        
                        if isinstance(result, Exception):
                            print(f"❌ MANUAL SCRAP: {scraper_name.upper()} scraper FAILED after {duration:.3f}s - Error: {result}")
                            return scraper_name, result
                        
                        if not result:
                            print(f"⚠️ MANUAL SCRAP: {scraper_name.upper()} scraper COMPLETED after {duration:.3f}s - No data returned")
                            return scraper_name, result
                        
                        print(f"✅ MANUAL SCRAP: {scraper_name.upper()} scraper COMPLETED after {duration:.3f}s - Data returned")
                        return scraper_name, result
                    except Exception as e:
                        completion_time = time.time()
                        duration = completion_time - start_times[scraper_name]
                        print(f"❌ MANUAL SCRAP: {scraper_name.upper()} scraper FAILED after {duration:.3f}s - Error: {e}")
                        return scraper_name, e
                
                # Use ThreadPoolExecutor for true parallel execution
                with ThreadPoolExecutor(max_workers=len(scraper_tasks)) as executor:
                    # Submit all tasks
                    future_to_scraper = {
                        executor.submit(run_scraper, scraper_name, scraper_func): scraper_name 
                        for scraper_name, scraper_func in scraper_tasks
                    }
                    
                    # Collect results as they complete
                    for future in as_completed(future_to_scraper):
                        scraper_name, result = future.result()
                        results[scraper_name] = result
                
                parallel_end = time.time()
                parallel_duration = parallel_end - parallel_start
                
                print(f"🏁 MANUAL SCRAP: All scrapers completed in {parallel_duration:.3f}s (parallel threads)")
                
                # Process results
                for scraper_name, result in results.items():
                    if isinstance(result, Exception) or not result:
                        continue
                    
                    # Update text fields
                    for field, value in result.get('text_fields', {}).items():
                        if value and field in scrap_results['text_fields']:
                            scrap_results['text_fields'][field]['sources'][scraper_name] = value
                    
                    # Update media fields (collect multiple options per source)
                    for field, value in result.get('media_fields', {}).items():
                        if value and field in scrap_results['media_fields']:
                            const_val = value if isinstance(value, list) else [value]
                            scrap_results['media_fields'][field]['sources'].setdefault(scraper_name, [])
                            scrap_results['media_fields'][field]['sources'][scraper_name].extend(const_val)
                
                # Summary
                total_sequential_time = sum(time.time() - start_times[name] for name in results.keys())
                print(f"📊 MANUAL SCRAP SUMMARY:")
                print(f"   - Scrapers run: {len(scraper_tasks)}")
                print(f"   - Parallel execution time: {parallel_duration:.3f}s")
                print(f"   - Estimated sequential time: {total_sequential_time:.3f}s")
                print(f"   - Time saved: {total_sequential_time - parallel_duration:.3f}s ({((total_sequential_time - parallel_duration) / total_sequential_time * 100):.1f}% faster)")
            else:
                print("DEBUG: No scrapers to run")
        
        # Run the parallel scraping
        print(f"DEBUG: About to call scrape_all_sources with system_config: {system_config}")
        scrape_all_sources(system_config)
        
        # Debug: Print the final results
        print(f"DEBUG: Final manual scrap results: {scrap_results}")
        
        return jsonify({
            'success': True,
            'results': scrap_results,
            'message': 'Manual scrap completed successfully'
        })

    except Exception as e:
        app.logger.error(f'Error in manual scrap: {str(e)}')
        return jsonify({'error': f'Failed to perform manual scrap: {str(e)}'}), 500

@app.route('/api/rom-system/<system_name>/explore-directory', methods=['GET'])
@login_required
def explore_directory(system_name):
    """Explore directory contents within the system's ROM directory"""
    try:
        path = request.args.get('path', '/')
        
        # Ensure path is within the system's ROM directory
        system_rom_dir = os.path.join(ROMS_FOLDER, system_name)
        if not os.path.exists(system_rom_dir):
            return jsonify({'error': f'System ROM directory not found: {system_rom_dir}'}), 404
        
        # Resolve the full path
        if path == '/':
            full_path = system_rom_dir
        else:
            # Remove leading slash and join with system directory
            clean_path = path.lstrip('/')
            full_path = os.path.join(system_rom_dir, clean_path)
        
        # Security check: ensure path is within system directory
        if not os.path.abspath(full_path).startswith(os.path.abspath(system_rom_dir)):
            return jsonify({'error': 'Access denied: path outside system directory'}), 403
        
        if not os.path.exists(full_path):
            return jsonify({'error': 'Directory not found'}), 404
        
        if not os.path.isdir(full_path):
            return jsonify({'error': 'Path is not a directory'}), 400
        
        # Read directory contents
        directories = []
        files = []
        
        try:
            for item in os.listdir(full_path):
                item_path = os.path.join(full_path, item)
                relative_path = os.path.relpath(item_path, system_rom_dir)
                # Convert to forward slashes for consistency
                relative_path = relative_path.replace('\\', '/')
                if not relative_path.startswith('/'):
                    relative_path = '/' + relative_path
                
                if os.path.isdir(item_path):
                    directories.append({
                        'name': item,
                        'path': relative_path
                    })
                else:
                    files.append({
                        'name': item,
                        'path': relative_path,
                        'size': os.path.getsize(item_path)
                    })
        except PermissionError:
            return jsonify({'error': 'Permission denied'}), 403
        
        # Sort directories and files
        directories.sort(key=lambda x: x['name'].lower())
        files.sort(key=lambda x: x['name'].lower())
        
        return jsonify({
            'success': True,
            'contents': {
                'directories': directories,
                'files': files
            }
        })
        
    except Exception as e:
        print(f"Error in explore_directory: {e}")
        return jsonify({'error': f'Internal server error: {str(e)}'}), 500

@app.route('/api/rom-system/<system_name>/create-directory', methods=['POST'])
@login_required
def create_directory(system_name):
    """Create a new directory within the system's ROM directory"""
    try:
        data = request.get_json()
        if not data:
            return jsonify({'error': 'No data provided'}), 400
        
        path = data.get('path', '/')
        name = data.get('name', '')
        
        if not name or not name.strip():
            return jsonify({'error': 'Directory name is required'}), 400
        
        # Sanitize directory name
        name = name.strip()
        if '/' in name or '\\' in name or name in ['.', '..']:
            return jsonify({'error': 'Invalid directory name'}), 400
        
        # Ensure path is within the system's ROM directory
        system_rom_dir = os.path.join(ROMS_FOLDER, system_name)
        if not os.path.exists(system_rom_dir):
            return jsonify({'error': f'System ROM directory not found: {system_rom_dir}'}), 404
        
        # Resolve the full path
        if path == '/':
            full_path = system_rom_dir
        else:
            # Remove leading slash and join with system directory
            clean_path = path.lstrip('/')
            full_path = os.path.join(system_rom_dir, clean_path)
        
        # Security check: ensure path is within system directory
        if not os.path.abspath(full_path).startswith(os.path.abspath(system_rom_dir)):
            return jsonify({'error': 'Access denied: path outside system directory'}), 403
        
        if not os.path.exists(full_path):
            return jsonify({'error': 'Parent directory not found'}), 404
        
        if not os.path.isdir(full_path):
            return jsonify({'error': 'Parent path is not a directory'}), 400
        
        # Create the new directory
        new_dir_path = os.path.join(full_path, name)
        
        if os.path.exists(new_dir_path):
            return jsonify({'error': 'Directory already exists'}), 400
        
        try:
            os.makedirs(new_dir_path)
            return jsonify({'success': True, 'message': f'Directory "{name}" created successfully'})
        except PermissionError:
            return jsonify({'error': 'Permission denied'}), 403
        except Exception as e:
            return jsonify({'error': f'Failed to create directory: {str(e)}'}), 500
        
    except Exception as e:
        print(f"Error in create_directory: {e}")
        return jsonify({'error': f'Internal server error: {str(e)}'}), 500

@app.route('/api/rom-system/<system_name>/move-rom', methods=['POST'])
@login_required
def move_rom(system_name):
    """Move a ROM file/directory within the system's ROM directory"""
    try:
        data = request.get_json()
        if not data:
            return jsonify({'error': 'No data provided'}), 400
        
        game_path = data.get('game_path', '')
        destination_path = data.get('destination_path', '')
        
        if not game_path or not destination_path:
            return jsonify({'error': 'Game path and destination path are required'}), 400
        
        # Ensure paths are within the system's ROM directory
        system_rom_dir = os.path.join(ROMS_FOLDER, system_name)
        if not os.path.exists(system_rom_dir):
            return jsonify({'error': f'System ROM directory not found: {system_rom_dir}'}), 404
        
        # Resolve full paths
        if game_path.startswith('./'):
            # Remove './' prefix for file system operations
            game_path_for_filesystem = game_path[2:]
        else:
            game_path_for_filesystem = game_path
        
        full_game_path = os.path.join(system_rom_dir, game_path_for_filesystem)
        
        if destination_path == '/':
            full_destination_path = system_rom_dir
        else:
            clean_dest_path = destination_path.lstrip('/')
            full_destination_path = os.path.join(system_rom_dir, clean_dest_path)
        
        # Security checks
        if not os.path.abspath(full_game_path).startswith(os.path.abspath(system_rom_dir)):
            return jsonify({'error': 'Access denied: game path outside system directory'}), 403
        
        if not os.path.abspath(full_destination_path).startswith(os.path.abspath(system_rom_dir)):
            return jsonify({'error': 'Access denied: destination path outside system directory'}), 403
        
        if not os.path.exists(full_game_path):
            return jsonify({'error': 'Game file/directory not found'}), 404
        
        if not os.path.exists(full_destination_path):
            return jsonify({'error': 'Destination directory not found'}), 404
        
        if not os.path.isdir(full_destination_path):
            return jsonify({'error': 'Destination is not a directory'}), 400
        
        # Get the filename/dirname for the destination
        game_name = os.path.basename(full_game_path)
        new_path = os.path.join(full_destination_path, game_name)
        
        if os.path.exists(new_path):
            return jsonify({'error': 'A file/directory with that name already exists in the destination'}), 400
        
        try:
            # Move the file/directory
            print(f"Moving file from {full_game_path} to {new_path}")
            shutil.move(full_game_path, new_path)
            print(f"File moved successfully")
            
            # Update the gamelist
            print(f"Updating gamelist for {system_name}")
            print(f"  Original game_path: {game_path}")
            print(f"  New path: {new_path}")
            update_gamelist_after_move(system_name, game_path, new_path, system_rom_dir)
            print(f"Gamelist update completed")
            
            return jsonify({
                'success': True,
                'message': f'ROM moved successfully to {destination_path}',
                'new_path': os.path.relpath(new_path, system_rom_dir).replace('\\', '/')
            })
            
        except PermissionError:
            return jsonify({'error': 'Permission denied'}), 403
        except Exception as e:
            return jsonify({'error': f'Failed to move ROM: {str(e)}'}), 500
        
    except Exception as e:
        print(f"Error in move_rom: {e}")
        return jsonify({'error': f'Internal server error: {str(e)}'}), 500

def update_gamelist_after_move(system_name, old_path, new_path, system_rom_dir):
    """Update gamelist after moving a ROM file"""
    try:
        # Load gamelist from var/gamelists
        gamelist_path = get_gamelist_path(system_name)
        if not os.path.exists(gamelist_path):
            return
        
        games = parse_gamelist_xml(gamelist_path)
        
        # Handle the old_path - it might already be relative or absolute
        if old_path.startswith('./'):
            # It's already a relative path from the gamelist perspective
            old_relative = old_path
        else:
            # It's an absolute path, convert to relative
            old_relative = os.path.relpath(old_path, system_rom_dir).replace('\\', '/')
            if not old_relative.startswith('./'):
                old_relative = './' + old_relative
        
        # Calculate new relative path
        new_relative = os.path.relpath(new_path, system_rom_dir).replace('\\', '/')
        if not new_relative.startswith('./'):
            new_relative = './' + new_relative
        
        print(f"Updating gamelist: {old_relative} -> {new_relative}")
        
        # Update game paths in gamelist
        updated = False
        print(f"Checking {len(games)} games for path matching...")
        for i, game in enumerate(games):
            current_path = game.get('path', '')
            print(f"  Game {i}: path='{current_path}', name='{game.get('name', 'NO_NAME')}'")
            
            if current_path == old_relative:
                game['path'] = new_relative
                updated = True
                print(f"  ✅ MATCH FOUND! Updated game path: {current_path} -> {new_relative}")
            elif current_path and current_path.startswith('./') and old_relative.startswith('./'):
                # Also check if the path matches without the './' prefix
                current_without_prefix = current_path[2:] if current_path.startswith('./') else current_path
                old_without_prefix = old_relative[2:] if old_relative.startswith('./') else old_relative
                if current_without_prefix == old_without_prefix:
                    game['path'] = new_relative
                    updated = True
                    print(f"  ✅ MATCH FOUND (without prefix)! Updated game path: {current_path} -> {new_relative}")
        
        if updated:
            # Save updated gamelist to var/gamelists
            print(f"Saving updated gamelist to: {gamelist_path}")
            write_gamelist_xml(games, gamelist_path)
            
            # Sync to roms directory
            print(f"Syncing gamelist to roms directory for {system_name}")
            save_gamelist_to_roms(system_name)
            
            # Notify clients
            notify_gamelist_updated(system_name, len(games))
            print(f"Gamelist updated successfully for {system_name} - both var/gamelists and roms directories")
        else:
            print(f"No matching game found for path: {old_relative}")
            print(f"Available paths in gamelist:")
            for i, game in enumerate(games[:5]):  # Show first 5 games
                print(f"  {i}: {game.get('path', 'NO_PATH')}")
            
    except Exception as e:
        print(f"Error updating gamelist after move: {e}")

@app.route('/api/rom-system/<system_name>/move-roms-bulk', methods=['POST'])
@login_required
def move_roms_bulk(system_name):
    """Move multiple ROM files/directories within the system's ROM directory"""
    try:
        data = request.get_json()
        if not data:
            return jsonify({'error': 'No data provided'}), 400
        
        games = data.get('games', [])
        destination_path = data.get('destination_path', '')
        
        if not games or not destination_path:
            return jsonify({'error': 'Games and destination path are required'}), 400
        
        # Ensure destination is within the system's ROM directory
        system_rom_dir = os.path.join(ROMS_FOLDER, system_name)
        if not os.path.exists(system_rom_dir):
            return jsonify({'error': f'System ROM directory not found: {system_rom_dir}'}), 404
        
        # Resolve destination path
        if destination_path == '/':
            full_destination_path = system_rom_dir
        else:
            clean_dest_path = destination_path.lstrip('/')
            full_destination_path = os.path.join(system_rom_dir, clean_dest_path)
        
        # Security check: ensure destination is within system directory
        if not os.path.abspath(full_destination_path).startswith(os.path.abspath(system_rom_dir)):
            return jsonify({'error': 'Access denied: destination path outside system directory'}), 403
        
        if not os.path.exists(full_destination_path):
            return jsonify({'error': 'Destination directory not found'}), 404
        
        if not os.path.isdir(full_destination_path):
            return jsonify({'error': 'Destination is not a directory'}), 400
        
        # Process each game
        moved_games = []
        failed_games = []
        
        for game_data in games:
            game_path = game_data.get('path', '')
            game_name = game_data.get('name', 'Unknown')
            
            if not game_path:
                failed_games.append({'name': game_name, 'error': 'No path provided'})
                continue
            
            try:
                # Resolve full paths
                if game_path.startswith('./'):
                    game_path_for_filesystem = game_path[2:]
                else:
                    game_path_for_filesystem = game_path
                
                full_game_path = os.path.join(system_rom_dir, game_path_for_filesystem)
                new_path = os.path.join(full_destination_path, os.path.basename(full_game_path))
                
                # Security checks
                if not os.path.abspath(full_game_path).startswith(os.path.abspath(system_rom_dir)):
                    failed_games.append({'name': game_name, 'error': 'Path outside system directory'})
                    continue
                
                if not os.path.exists(full_game_path):
                    failed_games.append({'name': game_name, 'error': 'File not found'})
                    continue
                
                if os.path.exists(new_path):
                    failed_games.append({'name': game_name, 'error': 'File already exists in destination'})
                    continue
                
                # Move the file/directory
                print(f"Moving file from {full_game_path} to {new_path}")
                shutil.move(full_game_path, new_path)
                
                # Update the gamelist for this game
                print(f"Updating gamelist for {game_name}")
                update_gamelist_after_move(system_name, game_path, new_path, system_rom_dir)
                
                moved_games.append({
                    'name': game_name,
                    'old_path': game_path,
                    'new_path': os.path.relpath(new_path, system_rom_dir).replace('\\', '/')
                })
                
            except Exception as e:
                print(f"Error moving {game_name}: {e}")
                failed_games.append({'name': game_name, 'error': str(e)})
        
        # Prepare response
        response_data = {
            'success': True,
            'moved_count': len(moved_games),
            'failed_count': len(failed_games),
            'moved_games': moved_games,
            'failed_games': failed_games
        }
        
        if failed_games:
            response_data['message'] = f'Moved {len(moved_games)} games, {len(failed_games)} failed'
        else:
            response_data['message'] = f'Successfully moved {len(moved_games)} games'
        
        return jsonify(response_data)
        
    except Exception as e:
        print(f"Error in move_roms_bulk: {e}")
        return jsonify({'error': f'Internal server error: {str(e)}'}), 500

@app.route('/api/rom-system/<system_name>/games/update-hidden', methods=['POST'])
@login_required
def update_games_hidden(system_name):
    """Update hidden field for multiple games"""
    try:
        data = request.get_json(force=True) or {}
        rom_paths = data.get('rom_paths', [])
        hidden_value = data.get('hidden', False)
        
        if not rom_paths:
            return jsonify({'error': 'rom_paths is required'}), 400
        
        # Load gamelist from var/gamelists
        gamelist_path = get_gamelist_path(system_name)
        if not os.path.exists(gamelist_path):
            return jsonify({'error': 'Gamelist not found'}), 404
            
        games = parse_gamelist_xml(gamelist_path)
        
        # Update hidden field for selected games
        updated_count = 0
        for game in games:
            if game.get('path') in rom_paths:
                game['hidden'] = 'true' if hidden_value else 'false'
                updated_count += 1
        
        if updated_count == 0:
            return jsonify({'error': 'No matching games found'}), 404
        
        # Save the updated gamelist
        write_gamelist_xml(games, gamelist_path)
        
        # Sync to roms directory
        save_gamelist_to_roms(system_name)
        
        # Notify all connected clients about the gamelist update
        notify_gamelist_updated(system_name, len(games))
        
        return jsonify({
            'success': True,
            'message': f'Updated hidden field for {updated_count} games',
            'updated_count': updated_count
        })
        
    except Exception as e:
        print(f"Error in update_games_hidden endpoint: {e}")
        return jsonify({'error': f'Internal server error: {str(e)}'}), 500

@app.route('/api/rom-system/<system_name>/game/manual-scrap/apply', methods=['POST'])
@login_required
def apply_manual_scrap(system_name):
    """Apply selected manual scrap changes: update text fields and download selected media."""
    try:
        data = request.get_json(force=True) or {}
        rom_path = data.get('rom_path')
        selections = data.get('selections', {})
        if not rom_path:
            return jsonify({'error': 'rom_path is required'}), 400

        # Load gamelist from var/gamelists and find the game
        gamelist_path = get_gamelist_path(system_name)
        games = parse_gamelist_xml(gamelist_path)
        game = next((g for g in games if g.get('path') == rom_path or os.path.basename(g.get('path','')) == os.path.basename(rom_path)), None)
        if not game:
            return jsonify({'error': 'Game not found'}), 404

        # Update text fields
        text_fields = ['name','desc','developer','publisher','genre','releasedate']
        updated_text_fields = {}
        for field in text_fields:
            selected_source = selections.get(field)
            selected_value = selections.get(f'{field}_value')
            # Apply any provided value (even empty string) when a non-current source was chosen
            if selected_value is not None and selected_source and selected_source != 'current':
                game[field] = selected_value
                updated_text_fields[field] = selected_value

        # Handle media downloads: selections may include e.g. image_url, marquee_url
        media_updates = {}
        download_stats = {'success': 0, 'failed': 0, 'skipped': 0}
        media_fields = config.get('media_fields', {})
        # System directory for media files under ROMS_FOLDER
        system_dir = os.path.join(ROMS_FOLDER, system_name)
        for media_field in media_fields.keys():
            selected_url = selections.get(f'{media_field}_url')
            if not selected_url:
                continue
            # Determine target directory
            directory = media_fields[media_field].get('directory', f'{media_field}s')
            ext = media_fields[media_field].get('target_extension', None)
            # Build filename from rom filename
            rom_filename = os.path.splitext(os.path.basename(rom_path))[0]
            target_dir = os.path.join(system_dir, 'media', directory)
            os.makedirs(target_dir, exist_ok=True)

            # If the selection is a local path (current value), don't attempt download
            if selected_url.startswith('./') or selected_url.startswith('/roms/'):
                # Normalize to gamelist relative path
                if selected_url.startswith('/roms/'):
                    # Convert absolute /roms/<system>/media/... to ./media/...
                    try:
                        parts = selected_url.split('/roms/')[1].split('/')
                        # parts[0] is system_name
                        rel = '/' + '/'.join(parts[2:]) if len(parts) > 2 else ''
                        rel_path = f'.{rel}' if rel.startswith('/media/') else f'./media{rel}'
                    except Exception:
                        rel_path = selected_url
                else:
                    rel_path = selected_url
                game[media_field] = rel_path
                media_updates[media_field] = rel_path
                download_stats['skipped'] += 1
                continue

            # Remote URL: download
            from urllib.parse import urlparse
            parsed = urlparse(selected_url)
            guessed_ext = os.path.splitext(parsed.path)[1] or '.png'
            target_ext = ext or guessed_ext
            target_filename = create_media_filename(rom_path, target_ext)
            target_path = os.path.join(target_dir, target_filename)

            try:
                # Check if this is a MobyGames page URL - if so, use the special download function
                if 'mobygames.com' in selected_url and ('/cover/' in selected_url or '/screenshots/' in selected_url):
                    # This is a MobyGames page URL, use the special download function for full-size images
                    success = download_mobygames_media_from_url(selected_url, target_path)
                    if success:
                        # Update game field with relative path
                        rel_path = f'./media/{directory}/{target_filename}'
                        game[media_field] = rel_path
                        media_updates[media_field] = rel_path
                        download_stats['success'] += 1
                        print(f'✅ Downloaded MobyGames {media_field} from {selected_url}')
                    else:
                        download_stats['failed'] += 1
                        print(f'❌ Error downloading MobyGames media {media_field} from {selected_url}')
                else:
                    # Regular URL download
                    resp = requests.get(selected_url, timeout=30)
                    if resp.status_code == 200:
                        with open(target_path, 'wb') as f:
                            f.write(resp.content)
                        # Update game field with relative path
                        rel_path = f'./media/{directory}/{target_filename}'
                        game[media_field] = rel_path
                        media_updates[media_field] = rel_path
                        download_stats['success'] += 1
                        print(f'✅ Downloaded {media_field} from {selected_url}')
                    else:
                        download_stats['failed'] += 1
                        print(f'❌ Error downloading media {media_field} from {selected_url}: HTTP {resp.status_code}')
            except Exception as e:
                download_stats['failed'] += 1
                print(f'❌ Error downloading media {media_field} from {selected_url}: {e}')

        # Save gamelist back
        write_gamelist_xml(games, gamelist_path)

        return jsonify({
            'success': True, 
            'updated_text_fields': updated_text_fields, 
            'updated_media': media_updates,
            'downloads': download_stats
        })
    except Exception as e:
        app.logger.error(f'Error applying manual scrap: {e}')
        return jsonify({'error': str(e)}), 500
        
    except Exception as e:
        app.logger.error(f'Error in manual scrap: {str(e)}')
        return jsonify({'error': f'Failed to perform manual scrap: {str(e)}'}), 500

async def scrape_igdb_manual(game, system_name, system_config, target_media_type=None):
    """Scrape IGDB data for manual scrap using local database (no API calls)"""
    try:
        import time
        
        # Check if local IGDB service is available
        if not global_igdb_service or not global_igdb_service.is_loaded():
            print("❌ IGDB local database not available for manual scrap")
            return None
        
        # Get IGDB configuration (still needed for field mappings)
        igdb_config = get_igdb_config()
        
        # Get IGDB ID (required for manual scrap)
        existing_igdb_id = game.get('igdbid')
        if not existing_igdb_id:
            print("❌ No IGDB ID found for manual scrap")
            return None
        
        print(f"✅ Using local IGDB database for manual scrap (no API calls)")
        
        # Get IGDB game data from local database
        game_fetch_start_time = time.time()
        igdb_game = global_igdb_service.get_game_by_id(int(existing_igdb_id))
        game_fetch_end_time = time.time()
        print(f"⏱️ IGDB local game data fetch took {game_fetch_end_time - game_fetch_start_time:.3f} seconds")
        
        if not igdb_game:
            print(f"❌ No IGDB game data found for ID: {existing_igdb_id}")
            return None
        
        # Add the ID back since it was removed from consolidated data
        igdb_game['id'] = int(existing_igdb_id)
        
        # Get field mappings
        config = load_config()
        igdb_mapping = scrappers_config.get('igdb', {}).get('mapping', {})
        igdb_image_mapping = scrappers_config.get('igdb', {}).get('image_type_mappings', {})
        
        # Helper function to get gamelist field from IGDB type
        def get_gamelist_field_for_igdb_type(igdb_type, default_field):
            for gamelist_field, mapped_igdb_type in igdb_image_mapping.items():
                if mapped_igdb_type == igdb_type:
                    return gamelist_field
            return default_field
        
        # Extract text fields from local database
        text_fields = {}
        if not target_media_type:
            import time
            text_start_time = time.time()
            
            # Basic text fields from local database
            if igdb_game.get('name'):
                text_fields['name'] = igdb_game['name']
            if igdb_game.get('summary'):
                text_fields['desc'] = igdb_game['summary']
            if igdb_game.get('first_release_date'):
                # Convert timestamp to ISO 8601 format
                text_fields['releasedate'] = format_releasedate_to_iso8601(igdb_game['first_release_date'])
            
            # Get genres (local database has genre IDs)
            if igdb_game.get('genres'):
                try:
                    genre_ids = igdb_game['genres']
                    genre_names = []
                    for genre_id in genre_ids:
                        genre_name = global_igdb_service.get_genre_name(genre_id)
                        if genre_name:
                            genre_names.append(genre_name)
                        else:
                            genre_names.append(f"Genre {genre_id}")
                    
                    if genre_names:
                        text_fields['genre'] = ', '.join(genre_names)
                        print(f"✅ Found genres: {text_fields['genre']}")
                except Exception as e:
                    print(f"Error getting genres: {e}")
            
            # Get publisher and developer information from consolidated database
            try:
                # Get publisher information
                if igdb_game.get('publisher'):
                    publisher_ids = igdb_game['publisher']
                    if not isinstance(publisher_ids, list):
                        publisher_ids = [publisher_ids]
                    
                    publisher_names = []
                    for publisher_id in publisher_ids:
                        publisher_name = global_igdb_service.get_company_name(publisher_id)
                        if publisher_name:
                            publisher_names.append(publisher_name)
                        else:
                            publisher_names.append(f"Company {publisher_id}")
                    
                    if publisher_names:
                        text_fields['publisher'] = ', '.join(publisher_names)
                        print(f"✅ Found publisher: {text_fields['publisher']}")
                
                # Get developer information
                if igdb_game.get('developer'):
                    developer_ids = igdb_game['developer']
                    if not isinstance(developer_ids, list):
                        developer_ids = [developer_ids]
                    
                    developer_names = []
                    for developer_id in developer_ids:
                        developer_name = global_igdb_service.get_company_name(developer_id)
                        if developer_name:
                            developer_names.append(developer_name)
                        else:
                            developer_names.append(f"Company {developer_id}")
                    
                    if developer_names:
                        text_fields['developer'] = ', '.join(developer_names)
                        print(f"✅ Found developer: {text_fields['developer']}")
                        
            except Exception as e:
                print(f"Error getting publisher/developer information: {e}")
            
            text_end_time = time.time()
            print(f"⏱️ IGDB text field extraction took {text_end_time - text_start_time:.2f} seconds")
        
        # Extract media fields from local database
        media_fields: Dict[str, List[str]] = {}


        def add_media(mapped_field: str, image_id: str):
            if not mapped_field or not image_id:
                return
            normalized_url = normalize_igdb_url(image_id)
            media_fields.setdefault(mapped_field, []).append(normalized_url)

        # Process media fields from local database
        if target_media_type:
            # Only process the specific media type needed
            print(f"🚀 IGDB MANUAL SCRAP: Processing only {target_media_type} for game {igdb_game['id']}")
            
            # Determine which IGDB field to use based on target media type
            target_igdb_type = None
            for field, igdb_type in igdb_image_mapping.items():
                if field == target_media_type:
                    target_igdb_type = igdb_type
                    break
            
            # If no mapping found, use heuristics
            if not target_igdb_type:
                if target_media_type in ['image', 'boxart']:
                    target_igdb_type = 'cover'
                elif target_media_type in ['fanart']:
                    target_igdb_type = 'artworks'
                elif target_media_type in ['marquee']:
                    target_igdb_type = 'logos'
                elif target_media_type in ['screenshot']:
                    target_igdb_type = 'screenshots'
            
            # Process only the needed media type from local database
            if target_igdb_type == 'cover' and igdb_game.get('cover'):
                try:
                    import time
                    start_time = time.time()
                    cover_id = igdb_game['cover']
                    add_media(get_gamelist_field_for_igdb_type('cover', 'image'), cover_id)
                    end_time = time.time()
                    print(f"⏱️ IGDB local cover processing took {end_time - start_time:.2f} seconds")
                except Exception as e:
                    print(f"Error processing IGDB cover: {e}")
            elif target_igdb_type == 'screenshots' and igdb_game.get('screenshots'):
                try:
                    import time
                    start_time = time.time()
                    screenshots = igdb_game['screenshots']
                    if isinstance(screenshots, dict):
                        # New format: dict with image_id as key
                        for screenshot_id in screenshots.keys():
                            add_media(get_gamelist_field_for_igdb_type('screenshots', 'image'), screenshot_id)
                    elif isinstance(screenshots, list):
                        # Old format: list
                        for screenshot_id in screenshots:
                            add_media(get_gamelist_field_for_igdb_type('screenshots', 'image'), screenshot_id)
                    else:
                        # Fallback: single value
                        add_media(get_gamelist_field_for_igdb_type('screenshots', 'image'), screenshots)
                    end_time = time.time()
                    print(f"⏱️ IGDB local screenshots processing took {end_time - start_time:.2f} seconds")
                except Exception as e:
                    print(f"Error processing IGDB screenshots: {e}")
            elif target_igdb_type == 'artworks' and igdb_game.get('artworks'):
                try:
                    import time
                    start_time = time.time()
                    artworks = igdb_game['artworks']
                    if isinstance(artworks, dict):
                        # New format: dict with image_id as key
                        for artwork_id in artworks.keys():
                            add_media(get_gamelist_field_for_igdb_type('artworks', 'fanart'), artwork_id)
                    elif isinstance(artworks, list):
                        # Old format: list
                        for artwork_id in artworks:
                            add_media(get_gamelist_field_for_igdb_type('artworks', 'fanart'), artwork_id)
                    else:
                        # Fallback: single value
                        add_media(get_gamelist_field_for_igdb_type('artworks', 'fanart'), artworks)
                    end_time = time.time()
                    print(f"⏱️ IGDB local artworks processing took {end_time - start_time:.2f} seconds")
                except Exception as e:
                    print(f"Error processing IGDB artworks: {e}")
            elif target_igdb_type == 'logos' and igdb_game.get('logos'):
                try:
                    import time
                    start_time = time.time()
                    logos = igdb_game['logos']
                    if isinstance(logos, dict):
                        # New format: dict with image_id as key
                        for logo_id in logos.keys():
                            logo_field = get_gamelist_field_for_igdb_type('logos', 'marquee')
                            add_media(logo_field, logo_id)
                    elif isinstance(logos, list):
                        # Old format: list
                        for logo_id in logos:
                            logo_field = get_gamelist_field_for_igdb_type('logos', 'marquee')
                            add_media(logo_field, logo_id)
                    else:
                        # Fallback: single value
                        logo_field = get_gamelist_field_for_igdb_type('logos', 'marquee')
                        add_media(logo_field, logos)
                    end_time = time.time()
                    print(f"⏱️ IGDB local logos processing took {end_time - start_time:.2f} seconds")
                except Exception as e:
                    print(f"Error processing IGDB logos: {e}")
        else:
            # Process all media types from local database
            print(f"🚀 IGDB MANUAL SCRAP: Processing all media types from local database for game {igdb_game['id']}")
            
            import time
            parallel_start_time = time.time()
            
            # Process cover from local database
            if igdb_game.get('cover'):
                try:
                    cover_id = igdb_game['cover']
                    add_media(get_gamelist_field_for_igdb_type('cover', 'image'), cover_id)
                    print(f"✅ Processed cover: {cover_id}")
                except Exception as e:
                    print(f"Error processing cover: {e}")
            
            # Process screenshots from local database
            if igdb_game.get('screenshots'):
                try:
                    screenshots = igdb_game['screenshots']
                    if isinstance(screenshots, dict):
                        # New format: dict with image_id as key
                        for screenshot_id in screenshots.keys():
                            add_media(get_gamelist_field_for_igdb_type('screenshots', 'image'), screenshot_id)
                        print(f"✅ Processed {len(screenshots)} screenshot(s)")
                    elif isinstance(screenshots, list):
                        # Old format: list
                        for screenshot_id in screenshots:
                            add_media(get_gamelist_field_for_igdb_type('screenshots', 'image'), screenshot_id)
                        print(f"✅ Processed {len(screenshots)} screenshot(s)")
                    else:
                        # Fallback: single value
                        add_media(get_gamelist_field_for_igdb_type('screenshots', 'image'), screenshots)
                        print(f"✅ Processed 1 screenshot")
                except Exception as e:
                    print(f"Error processing screenshots: {e}")
            
            # Process artworks from local database
            if igdb_game.get('artworks'):
                try:
                    artworks = igdb_game['artworks']
                    if isinstance(artworks, dict):
                        # New format: dict with image_id as key
                        for artwork_id in artworks.keys():
                            add_media(get_gamelist_field_for_igdb_type('artworks', 'fanart'), artwork_id)
                        print(f"✅ Processed {len(artworks)} artwork(s)")
                    elif isinstance(artworks, list):
                        # Old format: list
                        for artwork_id in artworks:
                            add_media(get_gamelist_field_for_igdb_type('artworks', 'fanart'), artwork_id)
                        print(f"✅ Processed {len(artworks)} artwork(s)")
                    else:
                        # Fallback: single value
                        add_media(get_gamelist_field_for_igdb_type('artworks', 'fanart'), artworks)
                        print(f"✅ Processed 1 artwork")
                except Exception as e:
                    print(f"Error processing artworks: {e}")
            
            # Process logos from local database
            if igdb_game.get('logos'):
                try:
                    logos = igdb_game['logos']
                    if isinstance(logos, dict):
                        # New format: dict with image_id as key
                        for logo_id in logos.keys():
                            logo_field = get_gamelist_field_for_igdb_type('logos', 'marquee')
                            add_media(logo_field, logo_id)
                        print(f"✅ Processed {len(logos)} logo(s)")
                    elif isinstance(logos, list):
                        # Old format: list
                        for logo_id in logos:
                            logo_field = get_gamelist_field_for_igdb_type('logos', 'marquee')
                            add_media(logo_field, logo_id)
                        print(f"✅ Processed {len(logos)} logo(s)")
                    else:
                        # Fallback: single value
                        logo_field = get_gamelist_field_for_igdb_type('logos', 'marquee')
                        add_media(logo_field, logos)
                        print(f"✅ Processed 1 logo")
                except Exception as e:
                    print(f"Error processing logos: {e}")
            
            parallel_end_time = time.time()
            print(f"✅ IGDB MANUAL SCRAP: Local database media processing completed for game {igdb_game['id']} in {parallel_end_time - parallel_start_time:.2f} seconds")
        
        return {
            'text_fields': text_fields,
            'media_fields': media_fields
        }
        
    except Exception as e:
        print(f"Error in IGDB manual scraping: {e}")
        return None

async def scrape_steam_manual(game, system_name, target_media_type=None):
    """Scrape Steam data for manual scrap (returns data without writing files)"""
    try:
        steam_id = game.get('steamid')
        print(f"DEBUG: Steam manual scrap - steam_id: {steam_id}")
        if not steam_id:
            print("DEBUG: Steam manual scrap - No steam_id found")
            return None
        
        # Get Steam service
        steam_service = SteamService()
        
        # Get Steam game data (only if we need text fields)
        steam_data = None
        if not target_media_type:
            # Only fetch game data if we need text fields
            steam_data = await steam_service.get_steam_game_data(steam_id)
            if not steam_data:
                return None
        else:
            # For media-only requests, create minimal steam_data with just the steam_id
            print(f"🚀 Steam MANUAL SCRAP: Skipping API call for {target_media_type}, using steam_id directly")
            steam_data = {'steam_id': steam_id}
        
        # Extract text fields (skip if target_media_type is specified for speed)
        text_fields = {}
        if not target_media_type:
            if steam_data.get('name'):
                text_fields['name'] = steam_data['name']
            if steam_data.get('short_description'):
                text_fields['desc'] = steam_data['short_description']
            if steam_data.get('release_date', {}).get('date'):
                # Convert Steam date format to ISO 8601 format
                release_date = steam_data['release_date']['date']
                if release_date:
                    text_fields['releasedate'] = format_releasedate_to_iso8601(release_date)
            
            # Get developers and publishers
            if steam_data.get('developers'):
                text_fields['developer'] = ', '.join(steam_data['developers'])
            if steam_data.get('publishers'):
                text_fields['publisher'] = ', '.join(steam_data['publishers'])
            
            # Get genres
            if steam_data.get('genres'):
                genre_names = [genre.get('description', '') for genre in steam_data['genres'] if genre.get('description')]
                if genre_names:
                    text_fields['genre'] = ', '.join(genre_names)
        
        # Extract media fields (arrays), using config mapping if present
        media_fields: Dict[str, List[str]] = {}
        steam_image_mapping = scrappers_config.get('steam', {}).get('image_type_mappings', {})

        # Build known Steam CDN URLs by steam_id (optimize based on target_media_type)
        if target_media_type:
            # Only build URLs for the target media type
            print(f"🚀 Steam MANUAL SCRAP: Building URLs only for {target_media_type}")
            
            # Find the Steam type that maps to the target media type
            target_steam_type = None
            print(f"🔧 DEBUG: Steam image mapping: {steam_image_mapping}")
            print(f"🔧 DEBUG: Looking for target media type: {target_media_type}")
            
            for field, steam_type in steam_image_mapping.items():
                if field == target_media_type:
                    target_steam_type = steam_type
                    print(f"🔧 DEBUG: Found mapping: {field} -> {steam_type}")
                    break
            
            # If no mapping found, use heuristics
            if not target_steam_type:
                print(f"🔧 DEBUG: No mapping found, using heuristics for {target_media_type}")
                if target_media_type in ['image', 'boxart']:
                    target_steam_type = 'capsule'
                elif target_media_type in ['marquee']:
                    target_steam_type = 'logo'
                elif target_media_type in ['fanart']:
                    target_steam_type = 'hero'
                print(f"🔧 DEBUG: Heuristic mapping: {target_media_type} -> {target_steam_type}")
            else:
                print(f"🔧 DEBUG: Using configured mapping: {target_media_type} -> {target_steam_type}")
            
            # Build only the needed URL (optimized for speed)
            if target_steam_type == 'capsule':
                # Primary capsule image
                capsule_url = f"https://shared.steamstatic.com/store_item_assets/steam/apps/{steam_id}/library_600x900_2x.jpg"
                media_fields.setdefault(target_media_type, []).append(capsule_url)
                # Alternative header image (if we have full steam_data)
                if steam_data.get('header_image'):
                    media_fields.setdefault(target_media_type, []).append(steam_data['header_image'])
                # Additional Steam CDN alternative
                header_url = f"https://shared.akamai.steamstatic.com/store_item_assets/steam/apps/{steam_id}/header.jpg?t=1682004272"
                media_fields.setdefault(target_media_type, []).append(header_url)
            elif target_steam_type == 'logo':
                logo_url = f"https://cdn.akamai.steamstatic.com/steam/apps/{steam_id}/logo.png"
                print(f"🔧 DEBUG: Building logo URL: {logo_url}")
                media_fields.setdefault(target_media_type, []).append(logo_url)
                print(f"🔧 DEBUG: Added logo URL to media_fields[{target_media_type}]: {media_fields[target_media_type]}")
            elif target_steam_type == 'hero':
                hero_url = f"https://shared.steamstatic.com/store_item_assets/steam/apps/{steam_id}/library_hero.jpg"
                media_fields.setdefault(target_media_type, []).append(hero_url)
        else:
            # Build all URLs (original behavior)
            print(f"🚀 Steam MANUAL SCRAP: Building all URLs")
            capsule_url = f"https://shared.steamstatic.com/store_item_assets/steam/apps/{steam_id}/library_600x900_2x.jpg"
            logo_url = f"https://cdn.akamai.steamstatic.com/steam/apps/{steam_id}/logo.png"
            hero_url = f"https://shared.steamstatic.com/store_item_assets/steam/apps/{steam_id}/library_hero.jpg"

            # Map and append as arrays
            capsule_field = None
            logo_field = None
            hero_field = None
            
            # Find the gamelist fields that map to these Steam types
            for field, steam_type in steam_image_mapping.items():
                if steam_type == 'capsule':
                    capsule_field = field
                elif steam_type == 'logo':
                    logo_field = field
                elif steam_type == 'hero':
                    hero_field = field
            
            # Use defaults if not found
            if not capsule_field:
                capsule_field = 'boxart'
            if not logo_field:
                logo_field = 'marquee'
            if not hero_field:
                hero_field = 'fanart'

            media_fields.setdefault(capsule_field, []).append(capsule_url)
            media_fields.setdefault(logo_field, []).append(logo_url)
            media_fields.setdefault(hero_field, []).append(hero_url)

            # Also include header_image from API if present
            if steam_data.get('header_image'):
                # Use capsule field for header image as fallback
                media_fields.setdefault(capsule_field, []).append(steam_data['header_image'])
        
        return {
            'text_fields': text_fields,
            'media_fields': media_fields
        }
        
    except Exception as e:
        print(f"Error in Steam manual scraping: {e}")
        return None

async def scrape_screenscraper_manual(game, system_name, system_config, target_media_type=None):
    """Scrape ScreenScraper data for manual scrap (returns data without writing files)"""
    try:
        # Get existing ScreenScraper ID from game data
        screenscraper_id = game.get('screenscraperid')
        if not screenscraper_id:
            return None
        
        # Get ScreenScraper configuration
        screenscraper_config = system_config.get('screenscraper', {})
        if isinstance(screenscraper_config, int):
            # If it's just an integer (system_id), it's enabled
            pass
        else:
            # Check if ScreenScraper credentials are configured
            from credential_manager import CredentialManager
            credential_manager = CredentialManager()
            screenscraper_credentials = credential_manager.get_screenscraper_credentials()
            if not (screenscraper_credentials.get('ssid') and screenscraper_credentials.get('sspassword')):
                return None
        
        # Get ScreenScraper service with proper initialization
        from credential_manager import CredentialManager
        credential_manager = CredentialManager()
        screenscraper_credentials = credential_manager.get_screenscraper_credentials()
        
        # Get the full config (needed for systems mapping)
        config = load_config()
        
        # Handle case where screenscraper config is just an integer (system_id)
        if isinstance(screenscraper_config, int):
            system_id = screenscraper_config
        else:
            system_id = screenscraper_config.get('system_id')
        
        systems_config = load_systems_config()
        screenscraper_service = ScreenScraperService(config, screenscraper_credentials, scrappers_config, systems_config)
        
        if not system_id:
            return None
        
        # Get game data directly using the existing ScreenScraper ID
        # Use system_name for system resolution inside the service
        game_data = await screenscraper_service.get_game_by_id(screenscraper_id, system_name)
        if not game_data:
            return None
        
        # Use the game data directly
        detailed_data = game_data
        
        # Extract text fields (skip if target_media_type is specified for speed)
        text_fields = {}
        if not target_media_type:
            if detailed_data.get('noms'):
                # Get first name
                names = detailed_data['noms']
                if names and len(names) > 0:
                    if isinstance(names[0], dict):
                        text_fields['name'] = names[0].get('text', '')
                    else:
                        # If names[0] is not a dict, it might be a string or int
                        text_fields['name'] = str(names[0])
            
            if detailed_data.get('synopsis'):
                synopsis = detailed_data['synopsis']
                if isinstance(synopsis, list) and len(synopsis) > 0:
                    # Get the first synopsis entry (usually English)
                    if isinstance(synopsis[0], dict) and 'text' in synopsis[0]:
                        text_fields['desc'] = synopsis[0]['text']
                    else:
                        text_fields['desc'] = str(synopsis[0])
                else:
                    text_fields['desc'] = str(synopsis)
            
            if detailed_data.get('dates'):
                # Get first date
                dates = detailed_data['dates']
                if dates and len(dates) > 0:
                    if isinstance(dates[0], dict):
                        date_text = dates[0].get('text', '')
                    else:
                        date_text = str(dates[0])
                    if date_text:
                        # Convert various date formats to ISO 8601 format
                        text_fields['releasedate'] = format_releasedate_to_iso8601(date_text)
            
            # Extract publisher from editeur.text
            if detailed_data.get('editeur') and isinstance(detailed_data['editeur'], dict):
                if 'text' in detailed_data['editeur']:
                    text_fields['publisher'] = detailed_data['editeur']['text']
            
            # Extract developer from developpeur.text
            if detailed_data.get('developpeur') and isinstance(detailed_data['developpeur'], dict):
                if 'text' in detailed_data['developpeur']:
                    text_fields['developer'] = detailed_data['developpeur']['text']
            
            # Extract genres from genres[noms[text]] with langue='en', concatenate with '/'
            if detailed_data.get('genres') and isinstance(detailed_data['genres'], list):
                genre_names = []
                for genre in detailed_data['genres']:
                    if isinstance(genre, dict) and 'noms' in genre and isinstance(genre['noms'], list):
                        for nom in genre['noms']:
                            if isinstance(nom, dict) and nom.get('langue') == 'en' and 'text' in nom:
                                genre_names.append(nom['text'])
                                break
                if genre_names:
                    text_fields['genre'] = '/'.join(genre_names)
        
        # Extract media fields grouped by configured gamelist media fields
        media_fields: Dict[str, List[Dict]] = {}
        ss_image_mapping = scrappers_config.get('screenscraper', {}).get('image_type_mappings', {})
        if detailed_data.get('medias'):
            for media in detailed_data['medias']:
                media_type = media.get('type')
                media_url = media.get('url')
                if not media_url:
                    continue
                
                # Find the gamelist field that this media type maps to
                mapped_field = None
                for gamelist_field, screenscraper_types in ss_image_mapping.items():
                    if media_type in screenscraper_types:
                        mapped_field = gamelist_field
                        break
                
                # Fallback heuristics if no mapping found
                if not mapped_field:
                    if media_type in ['ss', 'sstitle']:
                        mapped_field = 'image'
                    elif media_type in ['screenmarquee', 'fanart']:
                        mapped_field = 'marquee'
                    elif media_type in ['video', 'video-normalized']:
                        mapped_field = 'video'
                
                # Skip if target_media_type is specified and this doesn't match
                if target_media_type and mapped_field != target_media_type:
                    continue
                
                if mapped_field:
                    # Extract region information from ScreenScraper media
                    region_code = media.get('region', '')
                    region_name = 'Unknown'
                    if region_code:
                        # Import the region mapping from screenscraper_service
                        from screenscraper_service import REGION_MAPPING
                        region_name = REGION_MAPPING.get(region_code, region_code.upper())
                    
                    media_fields.setdefault(mapped_field, []).append({
                        'url': media_url,
                        'region': region_name,
                        'type': media_type
                    })
        
        return {
            'text_fields': text_fields,
            'media_fields': media_fields
        }
        
    except Exception as e:
        print(f"Error in ScreenScraper manual scraping: {e}")
        return None

async def scrape_steamgriddb_manual(game, system_name, target_media_type=None):
    """Scrape SteamGridDB data for manual scrap (returns data without writing files)"""
    try:
        steamgrid_id = game.get('steamgridid')
        if not steamgrid_id:
            print(f"🔧 DEBUG: SteamGridDB manual scrap - No steamgridid found, skipping")
            return None
        
        # Get SteamGridDB service
        steamgrid_service = SteamGridService()
        
        # Get API key
        api_key = steamgrid_service.get_api_key()
        if not api_key:
            return None
        
        # Get media data (optimize based on target_media_type)
        if target_media_type:
            # Determine which SteamGridDB media type to fetch
            sgd_image_mapping = scrappers_config.get('steamgriddb', {}).get('image_type_mappings', {})
            target_sgd_type = None
            
            # Find the SteamGridDB type that maps to the target media type
            for field, sgd_mapped_type in sgd_image_mapping.items():
                if field == target_media_type:
                    target_sgd_type = sgd_mapped_type
                    break
            
            # If no mapping found, use heuristics
            if not target_sgd_type:
                if target_media_type in ['image', 'boxart']:
                    target_sgd_type = 'grids'
                elif target_media_type in ['fanart']:
                    target_sgd_type = 'heroes'
                elif target_media_type in ['marquee']:
                    target_sgd_type = 'logos'
            
            # Only fetch the specific media type needed
            if target_sgd_type:
                print(f"🚀 SteamGridDB MANUAL SCRAP: Fetching only {target_sgd_type} for game {steamgrid_id}")
                media_types = [target_sgd_type]
            else:
                print(f"🚀 SteamGridDB MANUAL SCRAP: Unknown target media type {target_media_type}, fetching all")
                media_types = ['grids', 'heroes', 'logos']
        else:
            # Fetch all media types (original behavior)
            print(f"🚀 SteamGridDB MANUAL SCRAP: Fetching all media types for game {steamgrid_id}")
            media_types = ['grids', 'heroes', 'logos']
        
        media_data = await steamgrid_service.get_steamgrid_media(steamgrid_id, media_types, api_key)
        
        # Extract media fields as arrays, using mapping
        media_fields: Dict[str, List[Dict]] = {}
        sgd_image_mapping = scrappers_config.get('steamgriddb', {}).get('image_type_mappings', {})

        def map_and_append(items: List[Dict], sgd_type: str, default_field: str):
            if not items:
                return
            # Find the gamelist field that maps to this SteamGridDB type
            target_field = None
            for field, sgd_mapped_type in sgd_image_mapping.items():
                if sgd_mapped_type == sgd_type:
                    target_field = field
                    break
            if not target_field:
                target_field = default_field
            for item in items:
                if item.get('url'):
                    media_fields.setdefault(target_field, []).append({
                        'url': item.get('url'),
                        'region': 'Unknown',  # SteamGridDB doesn't provide region info
                        'type': sgd_type
                    })

        map_and_append(media_data.get('grids', []), 'grids', 'boxart')
        map_and_append(media_data.get('heroes', []), 'heroes', 'fanart')
        map_and_append(media_data.get('logos', []), 'logos', 'marquee')
        
        return {
            'text_fields': {},  # SteamGridDB doesn't provide text data
            'media_fields': media_fields
        }
        
    except Exception as e:
        print(f"Error in SteamGridDB manual scraping: {e}")
        return None
def extract_launchbox_text_fields(game_data, mapping_config):
    """Extract text fields from LaunchBox game data using common logic"""
    text_fields = {}
    
    # Always extract these standard fields regardless of mapping config
    standard_fields = ['Name', 'Description', 'Overview', 'Developer', 'Publisher', 'Genre', 'Genres', 'ReleaseDate', 'Platform', 'DatabaseID']
    
    # Extract text from dictionary data
    for field_name, field_value in game_data.items():
        if field_name in standard_fields and field_value:
            text = str(field_value).strip()
            
            # Debug: Print all fields found
            print(f"DEBUG: Found LaunchBox field: {field_name}='{text[:100] if text else 'None'}'")
            
            # Map LaunchBox fields to our internal field names
            if field_name == 'Name':
                text_fields['name'] = text
            elif field_name in ['Description', 'Overview']:
                # Handle both Description and Overview fields for description
                if 'desc' not in text_fields or not text_fields['desc']:
                    text_fields['desc'] = text
                    print(f"DEBUG: Set desc field from {field_name}: '{text[:100] if text else 'None'}'")
            elif field_name == 'Developer':
                text_fields['developer'] = text
            elif field_name == 'Publisher':
                text_fields['publisher'] = text
            elif field_name in ['Genre', 'Genres']:
                # Handle both Genre and Genres fields for genre
                if 'genre' not in text_fields or not text_fields['genre']:
                    text_fields['genre'] = text
                    print(f"DEBUG: Set genre field from {field_name}: '{text[:100] if text else 'None'}'")
            elif field_name == 'ReleaseDate':
                if text:
                    # Convert to ISO 8601 format
                    text_fields['releasedate'] = format_releasedate_to_iso8601(text)
    
    return text_fields

async def scrape_mobygames_manual(game, system_name, system_config, target_media_type=None):
    """Scrape MobyGames data for manual scrap (returns data without writing files)"""
    try:
        # Get MobyGames configuration
        mobygames_config = load_scrappers_config().get('mobygames', {})
        if not mobygames_config:
            return None
        
        # Get MobyGames service
        service = load_mobygames_service()
        if not service:
            return None
        
        # Get MobyGames system name
        mobygames_system = system_config.get('mobygames')
        if not mobygames_system:
            return None
        
        # Get game data
        mobygames_game = get_mobygames_game_data(game, system_name, service)
        if not mobygames_game:
            return None
        
        # Add ROM path for parentheses extraction
        mobygames_game['rom_path'] = game.get('path', '')
        # Add system information for text field scraping
        mobygames_game['system_name'] = system_name
        mobygames_game['system'] = mobygames_system
        
        # Get field mappings
        text_field_mapping = mobygames_config.get('mapping', {})
        image_type_mappings = mobygames_config.get('image_type_mappings', {})
        
        # Extract text fields (skip if target_media_type is specified for speed)
        text_fields = {}
        if not target_media_type:
            text_fields = extract_mobygames_text_fields(mobygames_game, text_field_mapping)
            print(f"🚀 MobyGames MANUAL SCRAP: Extracted text fields")
        else:
            print(f"🚀 MobyGames MANUAL SCRAP: Skipping text field extraction for {target_media_type}")
        
        # Extract media fields
        platform_mapping = load_mobygames_platform_mapping()
        media_fields = extract_mobygames_media_fields(mobygames_game, system_name, image_type_mappings, platform_mapping, service)
        
        return {
            'text_fields': text_fields,
            'media_fields': media_fields
        }
        
    except Exception as e:
        logger.error(f"Error in MobyGames manual scraping: {e}")
        import traceback
        logger.error(f"Traceback: {traceback.format_exc()}")
        return None

async def scrape_launchbox_manual(game, system_name, target_media_type=None):
    """Scrape LaunchBox data for manual scrap (returns data without writing files)"""
    try:
        launchbox_id = game.get('launchboxid')
        if not launchbox_id:
            return None
        
        # Get LaunchBox game data from cache
        # Try both str and int keys since cache keys may be stringified
        game_metadata = global_metadata_cache.get(launchbox_id)
        if not game_metadata:
            game_metadata = global_metadata_cache.get(str(launchbox_id)) or global_metadata_cache.get(int(launchbox_id))
        if not game_metadata:
            return None
        
        game_elem = game_metadata.get('game')
        if not game_elem:
            return None
        
        # Get mapping configuration
        config = load_config()
        mapping_config = scrappers_config.get('launchbox', {}).get('mapping', {})
        
        # Extract text fields using common logic (skip if target_media_type is specified for speed)
        text_fields = {}
        if not target_media_type:
            text_fields = extract_launchbox_text_fields(game_elem, mapping_config)
            # Debug: Print what fields were extracted
            print(f"DEBUG: LaunchBox manual scrap extracted text_fields: {text_fields}")
        else:
            print(f"🚀 LaunchBox MANUAL SCRAP: Skipping text field extraction for {target_media_type}")
        
        # Extract media fields from the images in the metadata (arrays per field)
        media_fields: Dict[str, List[Dict]] = {}
        
        # Get media URLs from LaunchBox images in the metadata
        if 'images' in game_metadata and game_metadata['images']:
            images = game_metadata['images']
            
            # Get LaunchBox image base URL from config
            image_config = load_image_mappings()
            base_url = 'https://images.launchbox-app.com/'
            
            for image in images:
                # Handle dictionary-based image data (new format)
                image_type = image.get('Type', '')  # LaunchBox uses 'Type' (capital T)
                filename = image.get('FileName', '')
                region = image.get('Region', 'Unknown')
                
                if image_type and filename:
                    # Construct full URL from base URL + filename
                    image_url = base_url + filename
                    
                    lb_map = image_config.get('image_type_mappings', {})
                    
                    # Check all fields to see if this image type maps to any of them
                    for gamelist_field, launchbox_types in lb_map.items():
                        if image_type in launchbox_types:
                            # Skip if target_media_type is specified and this doesn't match
                            if target_media_type and gamelist_field != target_media_type:
                                continue
                            
                            media_fields.setdefault(gamelist_field, []).append({
                                'url': image_url,
                                'region': region,
                                'type': image_type
                            })
        
        return {
            'text_fields': text_fields,
            'media_fields': media_fields
        }
        
    except Exception as e:
        print(f"Error in LaunchBox manual scraping: {e}")
        return None

