@app.route('/api/tasks/<task_id>/reconstruct', methods=['GET'])
@login_required
def reconstruct_task_from_log(task_id):
    """Reconstruct key task fields (system, steps, progress) from its log file."""
    try:
        log_path = os.path.join(LOGS_DIR, f"{task_id}.log")
        if not os.path.exists(log_path):
            return jsonify({'error': 'Log file not found'}), 404
        system_name = None
        progress_percentage = 0
        current_step = 0
        total_steps = 0
        stats = {}
        status = None
        with open(log_path, 'r', encoding='utf-8') as f:
            for line in f:
                line = line.strip()
                if not line.startswith('JSON: '):
                    continue
                try:
                    obj = json.loads(line[6:])
                except Exception:
                    continue
                system_name = obj.get('system_name') or system_name
                progress_percentage = obj.get('progress_percentage', progress_percentage)
                current_step = obj.get('current_step', current_step)
                total_steps = obj.get('total_steps', total_steps)
                if obj.get('stats'):
                    stats.update(obj['stats'])
                status = obj.get('status', status)
        return jsonify({
            'success': True,
            'task_id': task_id,
            'system_name': system_name,
            'progress_percentage': progress_percentage,
            'current_step': current_step,
            'total_steps': total_steps,
            'stats': stats,
            'status': status,
        })
    except Exception as e:
        return jsonify({'error': f'Failed to reconstruct task: {str(e)}'}), 500

@app.route('/api/tasks/history', methods=['GET'])
@login_required
def get_task_history():
    """Return reconstructed summaries for all tasks found in task_logs to repopulate the task grid after restart."""
    try:
        results = {}
        if not os.path.exists(LOGS_DIR):
            return jsonify(results)
        for fname in os.listdir(LOGS_DIR):
            if not fname.endswith('.log'):
                continue
            task_id = fname[:-4]
            log_path = os.path.join(LOGS_DIR, fname)
            type_hint = None
            system_name = None
            progress_percentage = 0
            current_step = 0
            total_steps = 0
            stats = {}
            status = None
            start_ts = None
            end_ts = None
            try:
                with open(log_path, 'r', encoding='utf-8') as f:
                    for line in f:
                        if line.startswith('Type: '):
                            type_hint = line.split('Type: ', 1)[1].strip()
                        if not line.startswith('JSON: '):
                            continue
                        try:
                            obj = json.loads(line[6:])
                        except Exception:
                            continue
                        # times
                        ts = obj.get('ts')
                        if ts:
                            if start_ts is None:
                                start_ts = ts
                            end_ts = ts
                        # core fields
                        system_name = obj.get('system_name') or system_name
                        progress_percentage = obj.get('progress_percentage', progress_percentage)
                        current_step = obj.get('current_step', current_step)
                        total_steps = obj.get('total_steps', total_steps)
                        if obj.get('stats'):
                            try:
                                stats.update(obj['stats'])
                            except Exception:
                                pass
                        status = obj.get('status', status)
                results[task_id] = {
                    'id': task_id,
                    'type': type_hint,
                    'status': status or 'completed',
                    'data': {'system_name': system_name} if system_name else {},
                    'progress_percentage': progress_percentage,
                    'current_step': current_step,
                    'total_steps': total_steps,
                    'stats': stats,
                    'start_time': start_ts,
                    'end_time': end_ts,
                }
            except Exception:
                continue
        return jsonify(results)
    except Exception as e:
        return jsonify({'error': f'Failed to read task history: {str(e)}'}), 500

@app.route('/api/tasks/<task_id>/stop', methods=['POST'])
@login_required
def stop_task_endpoint(task_id):
    """Stop a running task"""
    global tasks, current_task_id
    
    if task_id not in tasks:
        return jsonify({'error': 'Task not found'}), 404
    
    task = tasks[task_id]
    
    if task.status not in [TASK_STATUS_RUNNING, TASK_STATUS_WAITING_CONFIRMATION]:
        return jsonify({'error': 'Task is not running or waiting for confirmation'}), 400
    
    try:
        # Handle tasks in waiting confirmation status
        if task.status == TASK_STATUS_WAITING_CONFIRMATION:
            task.update_progress("🛑 Task cancelled by user")
            task.complete(True, "Task cancelled by user")
            return jsonify({
                'success': True,
                'message': 'Task cancelled successfully'
            })
        
        # Do not write from the main process; the worker will save partial changes
        task.update_progress("🛑 Stop requested - worker will save partial changes if needed")

        # Set the global stop event to signal all running tasks
        task_stop_event.set()
        # Also signal the worker process cooperatively via shared cancel map
        try:
            if '_worker_cancel_map' in globals() and _worker_cancel_map is not None:
                _worker_cancel_map[task_id] = True
        except Exception as _e:
            print(f"Warning: could not set worker cancel flag: {_e}")
        
        # For Steam tasks, set the cancellation event
        if task.type == 'steam_scraping':
            try:
                global _steam_cancel_events
                if '_steam_cancel_events' in globals() and task_id in _steam_cancel_events:
                    _steam_cancel_events[task_id].set()
            except Exception as e:
                print(f"Warning: could not set Steam cancellation event: {e}")
        
        # For image download tasks, immediately stop the download manager
        if task.type == 'image_download':
            try:
                from download_manager import get_download_manager
                download_manager = get_download_manager()
                if download_manager:
                    task.update_progress("🛑 Stopping download manager immediately")
                    download_manager.stop()
            except Exception as e:
                task.update_progress(f"⚠️  Warning: Could not stop download manager: {e}")
        
        # For IGDB scraping tasks, we need to handle cancellation differently
        # since they use their own separate process and cancel map
        if task.type == 'igdb_scraping':
            task.update_progress("🛑 IGDB scraping task stop requested - worker will save gamelist and exit")
            # Set the cancel flag in the IGDB-specific cancel map
            try:
                global _igdb_cancel_maps
                if task_id in _igdb_cancel_maps:
                    _igdb_cancel_maps[task_id][task_id] = True
                    print(f"DEBUG: Set IGDB cancel flag for task {task_id}")
                else:
                    print(f"DEBUG: IGDB cancel map not found for task {task_id}")
            except Exception as e:
                print(f"Warning: could not set IGDB cancel flag: {e}")
        
        # For ScreenScraper scraping tasks, we need to handle cancellation
        # since they use async operations and httpx connections
        if task.type == 'screenscraper_scraping':
            task.update_progress("🛑 ScreenScraper task stop requested - worker will save partial changes and exit")
            # Set the cancel flag for ScreenScraper tasks
            try:
                global _screenscraper_cancel_maps
                if '_screenscraper_cancel_maps' not in globals():
                    _screenscraper_cancel_maps = {}
                _screenscraper_cancel_maps[task_id] = True
                print(f"DEBUG: Set ScreenScraper cancel flag for task {task_id}")
            except Exception as e:
                print(f"Warning: could not set ScreenScraper cancel flag: {e}")
        
        # For SteamGridDB tasks, we need to handle cancellation
        # since they use async operations and httpx connections
        if task.type == 'steamgrid_scraping':
            task.update_progress("🛑 SteamGridDB task stop requested - worker will save partial changes and exit")
            # Set the cancel flag for SteamGridDB tasks
            try:
                global _steamgrid_cancel_maps
                if '_steamgrid_cancel_maps' not in globals():
                    _steamgrid_cancel_maps = {}
                _steamgrid_cancel_maps[task_id] = True
            except Exception as e:
                print(f"Warning: could not set SteamGridDB cancel flag: {e}")
        
        # For ROM scan tasks, we need to handle cancellation
        # since they run in background threads
        if task.type == 'rom_scan':
            task.update_progress("🛑 ROM scan task stop requested - worker will save partial changes and exit")
            # Set the cancel flag for ROM scan tasks
            try:
                global _rom_scan_cancel_maps
                if '_rom_scan_cancel_maps' not in globals():
                    _rom_scan_cancel_maps = {}
                _rom_scan_cancel_maps[task_id] = True
                print(f"DEBUG: Set ROM scan cancel flag for task {task_id}")
            except Exception as e:
                print(f"Warning: could not set ROM scan cancel flag: {e}")
        
        # For Steam tasks, we need to handle cancellation
        if task.type == 'steam_scraping':
            task.update_progress("🛑 Steam task stop requested - worker will save partial changes and exit")
            # Set the cancel flag for Steam tasks
            try:
                global _steam_cancel_maps
                if '_steam_cancel_maps' not in globals():
                    _steam_cancel_maps = {}
                _steam_cancel_maps[task_id] = True
                print(f"DEBUG: Set Steam cancel flag for task {task_id}")
            except Exception as e:
                print(f"Warning: could not set Steam cancel flag: {e}")
        
        # For SteamGridDB tasks (new separate task), we need to handle cancellation
        if task.type == 'steamgriddb_scraping':
            task.update_progress("🛑 SteamGridDB task stop requested - worker will save partial changes and exit")
            # Set the cancel flag for SteamGridDB tasks
            try:
                global _steamgriddb_cancel_maps
                if '_steamgriddb_cancel_maps' not in globals():
                    _steamgriddb_cancel_maps = {}
                _steamgriddb_cancel_maps[task_id] = True
            except Exception as e:
                print(f"Warning: could not set SteamGridDB cancel flag: {e}")
        
        # For MobyGames tasks, we need to handle cancellation
        if task.type == 'mobygames':
            task.update_progress("🛑 MobyGames task stop requested - worker will save partial changes and exit")
            # Set the cancel flag for MobyGames tasks
            try:
                global _mobygames_cancel_maps
                if '_mobygames_cancel_maps' not in globals():
                    _mobygames_cancel_maps = {}
                _mobygames_cancel_maps[task_id] = True
                print(f"DEBUG: Set MobyGames cancel flag for task {task_id}")
            except Exception as e:
                print(f"Warning: could not set MobyGames cancel flag: {e}")
        
        # Stop the task (except for YouTube batch download which handles its own completion)
        if task.type != 'youtube_download_batch':
            task.stop()
        else:
            # For YouTube batch download, just set the stop event - the task will handle completion itself
            task.update_progress("🛑 Stop requested - task will complete gracefully")
        
        # If this was the current running task, clear it
        if current_task_id == task_id:
            current_task_id = None
        
        # Clean up any stuck tasks
        cleanup_stuck_tasks()
        
        # Process next queued task if any
        process_next_queued_task()
        
        # Indicate that the grid should be reloaded if gamelist was saved
        grid_reload_needed = False
        if task.type in ['scraping', 'media_scan', 'image_download', 'youtube_download'] and task.data:
            system_name = task.data.get('system_name')
            if system_name:
                # For these task types, always indicate grid reload is needed
                # because they modify gamelist data, even if stopped prematurely
                grid_reload_needed = True
        
        return jsonify({
            'success': True, 
            'message': 'Task stopped successfully',
            'grid_reload_needed': grid_reload_needed,
            'system_name': task.data.get('system_name') if task.data else None
        })
    except Exception as e:
        return jsonify({'error': f'Failed to stop task: {str(e)}'}), 500

@app.route('/api/tasks/<task_id>/delete', methods=['DELETE'])
@login_required
def delete_task_endpoint(task_id):
    """Delete a queued task from the queue"""
    global task_queue
    
    # Find the task in the queue
    task_index = None
    for i, task_info in enumerate(task_queue):
        if task_info['task_id'] == task_id:
            task_index = i
            break
    
    if task_index is None:
        return jsonify({'error': 'Task not found in queue'}), 404
    
    # Check if task is queued (not running)
    task_info = task_queue[task_index]
    task_id = task_info['task_id']
    
    # Check if the task exists in the tasks dictionary and is queued
    if task_id not in tasks:
        return jsonify({'error': 'Task not found in tasks dictionary'}), 404
    
    task = tasks[task_id]
    if task.status != TASK_STATUS_QUEUED:
        return jsonify({'error': 'Only queued tasks can be deleted'}), 400
    
    try:
        # Remove the task from the queue
        deleted_task = task_queue.pop(task_index)
        
        # Also remove from the tasks dictionary
        if task_id in tasks:
            del tasks[task_id]
        
        return jsonify({
            'success': True,
            'message': f'Task "{deleted_task.get("type", "unknown")}" deleted from queue',
            'deleted_task_id': task_id
        })
    except Exception as e:
        return jsonify({'error': f'Failed to delete task: {str(e)}'}), 500

@app.route('/api/youtube/search', methods=['POST'])
@login_required
def youtube_search():
    """Search YouTube using YouTube Data API v3"""
    try:
        data = request.get_json()
        search_query = data.get('query', '').strip()
        
        if not search_query:
            return jsonify({'error': 'Search query is required'}), 400
        
        print(f"Searching YouTube API for: {search_query}")
        
        # Get YouTube API key from credentials
        youtube_api_key = get_youtube_api_key()
        if not youtube_api_key:
            print("YouTube API key not configured, falling back to web scraping")
            return search_youtube_with_web_scraping(search_query)
        
        # Search using YouTube Data API v3
        try:
            # Add "gameplay" to the search query for better results
            api_query = f"{search_query} gameplay"
            search_url = "https://www.googleapis.com/youtube/v3/search"
            
            params = {
                'part': 'snippet',
                'q': api_query,
                'type': 'video',
                'maxResults': 10,
                'order': 'date',  # Sort by date with most recent videos first
                'key': youtube_api_key
            }
            
            print(f"Making API request to: {search_url}")
            response = requests.get(search_url, params=params, timeout=15)
            response.raise_for_status()
            
            print(f"API response status: {response.status_code}")
            api_data = response.json()
            
            if 'items' not in api_data:
                print(f"Unexpected API response: {api_data}")
                return jsonify({
                    'success': False,
                    'error': 'Unexpected response from YouTube API',
                    'query': search_query
                })
            
            videos = []
            for item in api_data['items']:
                video_id = item['id']['videoId']
                snippet = item['snippet']
                
                # Format duration (we'll get this from video details)
                duration = "Unknown"
                
                # Format view count (we'll get this from video details)
                view_count = "Unknown"
                
                # Format published time
                published_time = format_youtube_published_time(snippet['publishedAt'])
                
                video_data = {
                    'id': video_id,
                    'title': snippet['title'],
                    'thumbnail': snippet['thumbnails'].get('high', {}).get('url', snippet['thumbnails'].get('medium', {}).get('url', '')),
                    'duration': duration,
                    'channel': snippet['channelTitle'],
                    'view_count': view_count,
                    'published_time': published_time,
                    'url': f"https://www.youtube.com/watch?v={video_id}"
                }
                videos.append(video_data)
            
            # Get additional details for each video (duration, view count)
            if videos:
                videos = get_youtube_video_details(videos, youtube_api_key)
            
            print(f"Successfully retrieved {len(videos)} videos from YouTube API")
            return jsonify({
                'success': True,
                'results': videos,
                'query': search_query
            })
            
        except requests.RequestException as e:
            print(f"YouTube API request error: {e}")
            return jsonify({
                'success': False,
                'error': f'YouTube API request failed: {str(e)}',
                'query': search_query
            })
        except Exception as e:
            print(f"Unexpected error during YouTube API search: {e}")
            import traceback
            traceback.print_exc()
            return jsonify({
                'success': False,
                'error': f'YouTube API error: {str(e)}',
                    'query': search_query
                })
            
    except Exception as e:
        print(f"YouTube search error: {e}")
        return jsonify({'error': str(e)}), 500

def get_youtube_api_key():
    """Get YouTube API key from credentials"""
    try:
        credentials_path = 'var/config/credentials.json'
        if os.path.exists(credentials_path):
            with open(credentials_path, 'r') as f:
                credentials = json.load(f)
            return credentials.get('youtube_api_key')
        return None
    except Exception as e:
        print(f"Error loading YouTube API key: {e}")
        return None

def save_youtube_api_key(api_key):
    """Save YouTube API key to credentials"""
    try:
        credentials_path = 'var/config/credentials.json'
        
        # Load existing credentials or create new dict
        credentials = {}
        if os.path.exists(credentials_path):
            with open(credentials_path, 'r') as f:
                credentials = json.load(f)
        
        # Update YouTube API key
        credentials['youtube_api_key'] = api_key
        
        # Ensure directory exists
        os.makedirs(os.path.dirname(credentials_path), exist_ok=True)
        
        # Save credentials
        with open(credentials_path, 'w') as f:
            json.dump(credentials, f, indent=2)
        
        return True
    except Exception as e:
        print(f"Error saving YouTube API key: {e}")
        return False

def format_youtube_published_time(published_at):
    """Format YouTube published time to human readable format"""
    try:
        from datetime import datetime, timezone
        import dateutil.parser
        
        # Parse the ISO 8601 datetime
        dt = dateutil.parser.parse(published_at)
        now = datetime.now(timezone.utc)
        
        # Calculate time difference
        diff = now - dt
        
        if diff.days > 0:
            if diff.days == 1:
                return "1 day ago"
            elif diff.days < 7:
                return f"{diff.days} days ago"
            elif diff.days < 30:
                weeks = diff.days // 7
                return f"{weeks} week{'s' if weeks > 1 else ''} ago"
            elif diff.days < 365:
                months = diff.days // 30
                return f"{months} month{'s' if months > 1 else ''} ago"
            else:
                years = diff.days // 365
                return f"{years} year{'s' if years > 1 else ''} ago"
        else:
            hours = diff.seconds // 3600
            if hours > 0:
                return f"{hours} hour{'s' if hours > 1 else ''} ago"
            else:
                minutes = (diff.seconds % 3600) // 60
                if minutes > 0:
                    return f"{minutes} minute{'s' if minutes > 1 else ''} ago"
                else:
                    return "Just now"
    except Exception as e:
        print(f"Error formatting published time: {e}")
        return "Unknown"

def get_youtube_video_details(videos, api_key):
    """Get additional details (duration, view count) for YouTube videos"""
    try:
        if not videos:
            return videos
        
        # Extract video IDs
        video_ids = [video['id'] for video in videos]
        
        # Make API request for video details
        details_url = "https://www.googleapis.com/youtube/v3/videos"
        params = {
            'part': 'contentDetails,statistics',
            'id': ','.join(video_ids),
            'key': api_key
        }
        
        response = requests.get(details_url, params=params, timeout=15)
        response.raise_for_status()
        
        details_data = response.json()
        
        if 'items' not in details_data:
            print(f"No video details found: {details_data}")
            return videos
        
        # Create a mapping of video ID to details
        details_map = {}
        for item in details_data['items']:
            video_id = item['id']
            content_details = item.get('contentDetails', {})
            statistics = item.get('statistics', {})
            
            # Parse duration (ISO 8601 format like PT4M13S)
            duration = "Unknown"
            if 'duration' in content_details:
                duration = parse_youtube_duration(content_details['duration'])
            
            # Format view count
            view_count = "Unknown"
            if 'viewCount' in statistics:
                try:
                    views = int(statistics['viewCount'])
                    if views >= 1000000:
                        view_count = f"{views/1000000:.1f}M views"
                    elif views >= 1000:
                        view_count = f"{views/1000:.1f}K views"
                    else:
                        view_count = f"{views:,} views"
                except (ValueError, TypeError):
                    pass
            
            details_map[video_id] = {
                'duration': duration,
                'view_count': view_count
            }
        
        # Update videos with details
        for video in videos:
            video_id = video['id']
            if video_id in details_map:
                video['duration'] = details_map[video_id]['duration']
                video['view_count'] = details_map[video_id]['view_count']
        
        return videos
        
    except Exception as e:
        print(f"Error getting YouTube video details: {e}")
        return videos

def parse_youtube_duration(duration_str):
    """Parse YouTube duration from ISO 8601 format (PT4M13S) to MM:SS or HH:MM:SS"""
    try:
        import re
        
        # Remove PT prefix
        duration_str = duration_str[2:]
        
        # Extract hours, minutes, seconds
        hours_match = re.search(r'(\d+)H', duration_str)
        minutes_match = re.search(r'(\d+)M', duration_str)
        seconds_match = re.search(r'(\d+)S', duration_str)
        
        hours = int(hours_match.group(1)) if hours_match else 0
        minutes = int(minutes_match.group(1)) if minutes_match else 0
        seconds = int(seconds_match.group(1)) if seconds_match else 0
        
        # Format as MM:SS or HH:MM:SS
        if hours > 0:
            return f"{hours:02d}:{minutes:02d}:{seconds:02d}"
        else:
            return f"{minutes:02d}:{seconds:02d}"
            
    except Exception as e:
        print(f"Error parsing YouTube duration: {e}")
        return "Unknown"

