@app.route('/api/download-launchbox-media', methods=['POST'])
@login_required
def download_launchbox_media():
    """Download and replace a specific media file from LaunchBox"""
    print(f"DEBUG: download_launchbox_media called with data: {request.get_json()}")
    try:
        data = request.get_json()
        game_id = data.get('game_id')  # This is actually the launchboxid for reference
        rom_path = data.get('rom_path')  # This is the actual game identifier
        media_type = data.get('media_type')
        media_url = data.get('media_url')
        region = data.get('region', 'Unknown')
        system_name = data.get('system_name')
        
        if not all([game_id, rom_path, media_type, media_url, system_name]):
            return jsonify({'error': 'Missing required parameters'}), 400
        
        # Load media config to get media mappings
        media_config = load_media_config()
        
        # Load image config for base URL
        image_config = load_image_mappings()
        
        # Find the media directory
        media_directory = get_media_directory(media_type)
        
        if not media_directory:
            return jsonify({'error': f'Unknown media type: {media_type}. Available fields: {list(media_config.get("media_fields", {}).keys())}'}), 400
        
        # Get the game from the current system (use var/gamelists, not roms)
        gamelist_path = os.path.join(GAMELISTS_FOLDER, system_name, 'gamelist.xml')
        
        print(f"DEBUG: GAMELISTS_FOLDER: {GAMELISTS_FOLDER}")
        print(f"DEBUG: system_name: {system_name}")
        print(f"DEBUG: gamelist_path: {gamelist_path}")
        print(f"DEBUG: gamelist exists: {os.path.exists(gamelist_path)}")
        
        if not os.path.exists(gamelist_path):
            return jsonify({'error': 'Gamelist not found'}), 404
        
        # Parse gamelist to find the game
        tree = ET.parse(gamelist_path)
        root = tree.getroot()
        
        print(f"DEBUG: Looking for game with rom_path: {rom_path}")
        print(f"DEBUG: Total games in gamelist: {len(root.findall('game'))}")
        
        game_element = None
        # Find by rom path
        for game in root.findall('game'):
            path_elem = game.find('path')
            if path_elem is not None:
                print(f"DEBUG: Found game with path: '{path_elem.text}'")
                if path_elem.text == rom_path:
                    game_element = game
                    print(f"DEBUG: MATCH FOUND! Game: {game.find('name').text if game.find('name') is not None else 'Unknown'}")
                    break
            else:
                name_elem = game.find('name')
                print(f"DEBUG: Game without path: {name_elem.text if name_elem is not None else 'Unknown'}")
        
        if not game_element:
            return jsonify({'error': f'Game with ROM path {rom_path} not found in {system_name} gamelist'}), 404
        
        # Get ROM filename for naming the media file
        rom_path_elem = game_element.find('path')
        if rom_path_elem is None or rom_path_elem.text is None:
            return jsonify({'error': 'Game path not found'}), 400
        
        # Create media directory if it doesn't exist
        system_path = os.path.join(ROMS_FOLDER, system_name)
        media_dir = os.path.join(system_path, 'media', media_directory)
        os.makedirs(media_dir, exist_ok=True)
        
        # Determine file extension from URL
        file_extension = os.path.splitext(media_url.split('/')[-1])[1]
        if not file_extension:
            file_extension = '.jpg'  # Default to jpg
        
        # Create local filename
        local_filename = create_media_filename(rom_path_elem.text, file_extension)
        local_path = os.path.join(media_dir, local_filename)
        
        # Download the media file
        import requests
        response = requests.get(media_url, timeout=30)
        response.raise_for_status()
        
        # Save the file
        with open(local_path, 'wb') as f:
            f.write(response.content)
        
        # Convert image if field has target_extension configured
        # Check the target field name, not the source field name
        from game_utils import should_convert_field, convert_image_replace, needs_conversion
        should_convert, target_extension = should_convert_field(media_type, config)
        
        if should_convert and needs_conversion(local_path, target_extension):
            new_path, status = convert_image_replace(local_path, target_extension)
            if status == "converted":
                # Conversion successful, update paths and filename
                local_path = new_path
                local_filename = os.path.basename(local_path)
                print(f"✅ Converted to {target_extension}: {local_filename}")
            elif status == "already_target":
                # File was already in target format, no conversion needed
                print(f"✅ Already {target_extension} format: {local_filename}")
            else:
                # Conversion failed
                print(f"⚠️ Failed to convert to {target_extension}, keeping original: {local_filename}")
        elif should_convert:
            # Field should be converted but file is already in target format
            print(f"✅ Already {target_extension} format: {local_filename}")
        else:
            # No conversion needed for this field
            print(f"✅ No conversion needed for field: {media_type}")
        
        # Update gamelist.xml
        media_field = game_element.find(media_type)
        if media_field is not None:
            media_field.text = f"./media/{media_directory}/{local_filename}"
        else:
            # Create new media field
            new_media_field = ET.SubElement(game_element, media_type)
            new_media_field.text = f"./media/{media_directory}/{local_filename}"
        
        # Save the updated gamelist
        save_formatted_gamelist_xml(tree, gamelist_path)
        notify_game_updated(system_name, game_element.find('path').text if game_element.find('path') is not None else '', [media_type])
        
        return jsonify({
            'success': True,
            'message': f'Media downloaded and replaced successfully',
            'local_path': local_path,
            'gamelist_field': media_type,
            'media_path': f"./media/{media_directory}/{local_filename}"
        })
        
    except Exception as e:
        print(f"Error downloading LaunchBox media: {e}")
        return jsonify({'error': f'Failed to download media: {str(e)}'}), 500

# =============================================================================
# IGDB Integration Functions
# =============================================================================

def get_igdb_config():
    """Get IGDB configuration from config.json with credentials from environment variables or credentials.json"""
    try:
        # Load base configuration from config.json
        config = load_config()
        igdb_config = scrappers_config.get('igdb', {})
        
        # Try to load credentials from credentials.json
        credentials = {}
        try:
            credentials_path = 'var/config/credentials.json'
            if os.path.exists(credentials_path):
                with open(credentials_path, 'r', encoding='utf-8') as f:
                    credentials = json.load(f)
        except Exception as e:
            print(f"Warning: Could not load credentials.json: {e}")
        
        # Priority order: environment variables > credentials.json > config.json
        client_id = os.getenv('IGDB_CLIENT_ID') or credentials.get('igdb', {}).get('client_id')
        client_secret = os.getenv('IGDB_CLIENT_SECRET') or credentials.get('igdb', {}).get('client_secret')
        
        if client_id:
            igdb_config['client_id'] = client_id
        if client_secret:
            igdb_config['client_secret'] = client_secret
            
        return igdb_config
    except Exception as e:
        print(f"Error loading IGDB config: {e}")
        return {}

def save_igdb_credentials(client_id, client_secret):
    """Save IGDB credentials to credentials.json file"""
    try:
        credentials_path = 'var/config/credentials.json'
        
        # Ensure the config directory exists
        os.makedirs(os.path.dirname(credentials_path), exist_ok=True)
        
        # Load existing credentials or create new structure
        credentials = {}
        if os.path.exists(credentials_path):
            try:
                with open(credentials_path, 'r', encoding='utf-8') as f:
                    credentials = json.load(f)
            except Exception as e:
                print(f"Warning: Could not load existing credentials.json: {e}")
                credentials = {}
        
        # Update IGDB credentials
        if 'igdb' not in credentials:
            credentials['igdb'] = {}
        
        credentials['igdb']['client_id'] = client_id
        credentials['igdb']['client_secret'] = client_secret
        
        # Save to file
        with open(credentials_path, 'w', encoding='utf-8') as f:
            json.dump(credentials, f, indent=4, ensure_ascii=False)
        
        print(f"IGDB credentials saved to {credentials_path}")
        return True
        
    except Exception as e:
        print(f"Error saving IGDB credentials: {e}")
        return False

